/**
 * Sidebar item browser. Right-click an inventory, bank, worn, or ground item and choose Item Browser Lookup.
 */
@Slf4j
@PluginDescriptor(
    name = "OSRS Item Browser",
    description = "Browse items, drop tables, shop prices, and sources",
    tags = {"item", "drops", "wiki", "browser", "search", "recipe"}
)
public class JEIPlugin extends Plugin {

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ItemManager itemManager;
    @Inject private JEIConfig config;
    @Inject private JEIPanel panel;
    @Inject private MapMarkers mapMarkers;
    @Inject private PlayerProgress progress;
    @Inject private ConfigManager configManager;

    /** Set only after InventoryID.BANK has changed, or a saved per-account flag and a loaded container. */
    private boolean bankSeen;

    private NavigationButton navButton;
    private boolean ironmanActive;
    private boolean ironmanKnown;
    private volatile OwnedItems.Snapshot owned = OwnedItems.Snapshot.NONE;
    private volatile WornGear worn = WornGear.LOGGED_OUT;

    @Override
    protected void startUp() {
        SwingUtilities.invokeLater(() -> {
            if (panel.isClosed()) {
                return;
            }
            try {
                panel.init();
                progress.setListener(snapshot -> SwingUtilities.invokeLater(() -> {
                    if (!panel.isClosed()) {
                        panel.onProgress(snapshot);
                    }
                }));
                navButton = NavigationButton.builder()
                    .tooltip("OSRS Item Browser")
                    .icon(createIcon())
                    .priority(6)
                    .panel(panel)
                    .build();
                clientToolbar.addNavigation(navButton);
                log.info("OSRS Item Browser started");
                clientThread.invokeLater(() -> {
                    if (panel.isClosed()) {
                        return;
                    }
                    panel.ensureItemIndex(client.getGameState());
                    publishIronman();
                    owned = OwnedItems.Snapshot.NONE;
                    publishOwned();
                    worn = WornGear.LOGGED_OUT;
                    publishWorn();
                    progress.refreshSkills();
                });
            } catch (Exception e) {
                log.error("OSRS Item Browser failed to start", e);
            }
        });
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (panel.isClosed()) {
            return;
        }
        GameState state = event.getGameState();
        panel.ensureItemIndex(state);
        if (state == GameState.LOGIN_SCREEN || state == GameState.LOGGING_IN || state == GameState.LOGGED_IN) {
            publishIronman();
        }
        publishOwned();
        publishWorn();
        progress.refreshSkills();
    }

    /** Real levels only. Boosts do not change the snapshot, so the sidebar stays still. */
    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (!panel.isClosed()) {
            progress.refreshSkills();
        }
    }

    /** Drains a quest-state refresh queued by a varbit change. One read per tick. */
    @Subscribe
    public void onGameTick(GameTick event) {
        if (!panel.isClosed()) {
            progress.readQuestsIfDirty();
            panel.nudgeMap();
        }
    }

    /**
     * Inventory, worn equipment, and bank. Read on the client thread and
     * forwarded only when the canonical totals actually change. The bank
     * counts only after that container has changed, not merely because an
     * empty container object exists.
     */
    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (panel.isClosed()) {
            return;
        }
        int containerId = event.getContainerId();
        if (containerId != InventoryID.INV && containerId != InventoryID.BANK && containerId != InventoryID.WORN) {
            return;
        }
        if (containerId == InventoryID.BANK) {
            rememberBank();
        }
        publishOwned();
        if (containerId == InventoryID.WORN) {
            publishWorn();
        }
    }

    /**
     * The logged-in account changed. {@code AccountHashChanged} is the client
     * event for that; the ironman varbit and game state carry the type used
     * by AUTO mode.
     */
    @Subscribe
    public void onAccountHashChanged(AccountHashChanged event) {
        bankSeen = false;
        if (!panel.isClosed()) {
            publishIronman();
            publishOwned();
            publishWorn();
            progress.refreshSkills();
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (panel.isClosed()) {
            return;
        }
        progress.markQuestsDirty();
        if (event.getVarbitId() != VarbitID.IRONMAN) {
            return;
        }
        publishIronman();
    }

    @Override
    protected void shutDown() {
        panel.shutdown();
        progress.setListener(null);
        owned = OwnedItems.Snapshot.NONE;
        worn = WornGear.LOGGED_OUT;
        SwingUtilities.invokeLater(() -> {
            if (navButton != null) {
                clientToolbar.removeNavigation(navButton);
                navButton = null;
            }
            log.info("OSRS Item Browser stopped");
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!"osrjei".equals(event.getGroup())) {
            return;
        }
        String key = event.getKey();
        if ("ironmanMode".equals(key)) {
            clientThread.invokeLater(this::publishIronman);
            return;
        }
        if ("mapPinColor".equals(key) || "pinSize".equals(key)) {
            if (mapMarkers != null) {
                mapMarkers.applyAppearance(config.mapPinColor(), config.pinSize());
            }
            return;
        }
        if ("rightClickLookup".equals(key) || "clearPinsOnSwitch".equals(key)) {
            return;
        }
        SwingUtilities.invokeLater(() -> panel.onConfigChanged(key));
    }

    /**
     * Reads the account-type varbit on the client thread and refreshes the
     * open detail view only when the effective ironman flag actually changes.
     */
    private void publishIronman() {
        if (panel.isClosed()) {
            return;
        }
        int accountType = 0;
        try {
            accountType = client.getVarbitValue(VarbitID.IRONMAN);
        } catch (Exception ignored) {
            accountType = 0;
        }
        boolean active = IronmanAccounts.effective(config.ironmanMode(), accountType);
        if (ironmanKnown && !IronmanAccounts.shouldRefreshDetail(ironmanActive, active)) {
            return;
        }
        ironmanActive = active;
        ironmanKnown = true;
        SwingUtilities.invokeLater(() -> {
            if (!panel.isClosed()) {
                panel.onIronmanChanged(active);
            }
        });
    }

    /**
     * Rebuilds the owned snapshot from the live containers. No-ops off the
     * client thread by rescheduling, and skips the Swing update when the
     * canonical map is unchanged.
     */
    private void publishOwned() {
        if (!client.isClientThread()) {
            clientThread.invokeLater(this::publishOwned);
            return;
        }
        if (panel.isClosed()) {
            return;
        }
        OwnedItems.Snapshot next = captureOwned();
        if (next.equals(owned)) {
            return;
        }
        owned = next;
        SwingUtilities.invokeLater(() -> {
            if (!panel.isClosed()) {
                panel.onOwnedChanged(next);
            }
        });
    }

    private OwnedItems.Snapshot captureOwned() {
        try {
            ItemContainer inventory = client.getItemContainer(InventoryID.INV);
            ItemContainer worn = client.getItemContainer(InventoryID.WORN);
            ItemContainer bank = client.getItemContainer(InventoryID.BANK);
            return OwnedItems.snapshot(
                readContainer(inventory),
                readContainer(worn),
                readContainer(bank),
                inventory != null,
                bankHasBeenSeen()
            );
        } catch (RuntimeException ex) {
            log.debug("Could not read item containers: {}", ex.getMessage());
            return OwnedItems.Snapshot.NONE;
        }
    }

    private void rememberBank() {
        bankSeen = true;
        if (configManager == null) {
            return;
        }
        try {
            configManager.setRSProfileConfiguration("osrjei", "bankSeen", Boolean.TRUE);
        } catch (RuntimeException ex) {
            log.debug("Could not remember that the bank was opened: {}", ex.getMessage());
        }
    }

    /**
     * A non-null bank container is not enough: the client can hold an empty
     * one before the player opens the bank. The flag is per account.
     */
    private boolean bankHasBeenSeen() {
        if (bankSeen) {
            return true;
        }
        if (configManager == null || client.getItemContainer(InventoryID.BANK) == null) {
            return false;
        }
        try {
            Boolean saved = configManager.getRSProfileConfiguration("osrjei", "bankSeen", Boolean.class);
            if (Boolean.TRUE.equals(saved)) {
                bankSeen = true;
                return true;
            }
        } catch (RuntimeException ex) {
            log.debug("Could not read the saved bank flag: {}", ex.getMessage());
        }
        return false;
    }

    private Map<Integer, Long> readContainer(ItemContainer container) {
        if (container == null) {
            return Collections.emptyMap();
        }
        Item[] items = container.getItems();
        if (items == null) {
            return Collections.emptyMap();
        }
        List<OwnedItems.Slot> slots = new ArrayList<>();
        for (int i = 0; i < items.length; i++) {
            Item item = items[i];
            if (item == null || item.getId() < 0 || item.getQuantity() <= 0) {
                continue;
            }
            try {
                ItemComposition composition = itemManager.getItemComposition(item.getId());
                int canonical = itemManager.canonicalize(item.getId());
                slots.add(new OwnedItems.Slot(canonical, item.getQuantity(), composition.getPlaceholderTemplateId()));
            } catch (RuntimeException ignored) {
                // one unreadable slot does not discard the rest of the container
            }
        }
        return OwnedItems.count(slots);
    }

    /**
     * Worn item ids for the equipment comparison. Read on the client thread.
     * This does not fetch wiki pages; the panel does that only after the
     * comparison is opened.
     */
    private void publishWorn() {
        if (!client.isClientThread()) {
            clientThread.invokeLater(this::publishWorn);
            return;
        }
        if (panel.isClosed()) {
            return;
        }
        WornGear next = captureWorn();
        if (next.equals(worn)) {
            return;
        }
        worn = next;
        SwingUtilities.invokeLater(() -> {
            if (!panel.isClosed()) {
                panel.onWornChanged(next);
            }
        });
    }

    private WornGear captureWorn() {
        int[] ids = new int[WornGear.SLOTS];
        Arrays.fill(ids, -1);
        boolean loggedIn = false;
        try {
            loggedIn = client.getGameState() == GameState.LOGGED_IN;
            if (!loggedIn) {
                return WornGear.LOGGED_OUT;
            }
            ItemContainer container = client.getItemContainer(InventoryID.WORN);
            if (container == null || container.getItems() == null) {
                return new WornGear(true, ids);
            }
            Item[] items = container.getItems();
            for (EquipmentInventorySlot slot : EquipmentInventorySlot.values()) {
                int index = slot.getSlotIdx();
                if (index < 0 || index >= items.length || index >= ids.length) {
                    continue;
                }
                Item item = items[index];
                if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
                    continue;
                }
                ids[index] = itemManager.canonicalize(item.getId());
            }
        } catch (RuntimeException ex) {
            log.debug("Could not read worn equipment: {}", ex.getMessage());
            return loggedIn ? new WornGear(true, ids) : WornGear.LOGGED_OUT;
        }
        return new WornGear(true, ids);
    }

    /**
     * Adds one Item Browser Lookup entry on ground items and on Examine for inventory,
     * bank (including placeholders and the bank side inventory), worn equipment,
     * and the equipment stats interface.
     */
    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (config != null && !config.rightClickLookup()) {
            return;
        }
        if (client.getMenu() == null || panel.isClosed()) {
            return;
        }
        if (LookupTargets.alreadyOffered(optionTexts(client.getMenu().getMenuEntries()))) {
            return;
        }
        int itemId = itemIdForLookup(event);
        if (itemId < 0) {
            return;
        }
        final int lookupId = itemId;
        client.getMenu().createMenuEntry(-1)
            .setOption(LookupTargets.MENU_OPTION)
            .setTarget(event.getTarget())
            .setType(MenuAction.RUNELITE)
            .setDeprioritized(true)
            .onClick(e -> clientThread.invoke(() -> openLookup(lookupId)));
    }

    private void openLookup(int itemId) {
        int resolved = canonicalItemId(itemId);
        SwingUtilities.invokeLater(() -> {
            if (navButton != null) {
                clientToolbar.openPanel(navButton);
            }
            panel.lookupItem(resolved);
        });
    }

    /**
     * Notes and placeholders are resolved from the composition, then
     * {@code itemManager.canonicalize} maps worn variants. Client thread only.
     */
    private int canonicalItemId(int itemId) {
        if (itemId < 0) {
            return -1;
        }
        try {
            ItemComposition composition = itemManager.getItemComposition(itemId);
            int fromComposition = CanonicalIds.resolve(
                itemId,
                composition.getNote(),
                composition.getLinkedNoteId(),
                composition.getPlaceholderTemplateId(),
                composition.getPlaceholderId());
            return itemManager.canonicalize(fromComposition);
        } catch (Exception ignored) {
            return itemId;
        }
    }

    private int itemIdForLookup(MenuEntryAdded event) {
        int type = event.getType();
        if (LookupTargets.groundExamine(type)) {
            return event.getIdentifier() >= 0 ? event.getIdentifier() : -1;
        }
        int group = WidgetUtil.componentToInterface(event.getActionParam1());
        if (!LookupTargets.widgetExamine(type, event.getOption(), group)) {
            return -1;
        }
        if (event.getItemId() > 0) {
            return event.getItemId();
        }
        return itemIdFromWidget(event.getActionParam1(), event.getActionParam0());
    }

    private int itemIdFromWidget(int widgetId, int childIndex) {
        Widget widget = client.getWidget(widgetId);
        if (widget == null) {
            return -1;
        }
        if (widget.getItemId() > 0) {
            return widget.getItemId();
        }
        Widget child = widget.getChild(childIndex);
        if (child != null && child.getItemId() > 0) {
            return child.getItemId();
        }
        Widget worn = widget.getChild(1);
        if (worn != null && worn.getItemId() > 0) {
            return worn.getItemId();
        }
        return -1;
    }

    private static List<String> optionTexts(MenuEntry[] entries) {
        List<String> options = new ArrayList<>();
        if (entries == null) {
            return options;
        }
        for (MenuEntry entry : entries) {
            if (entry != null) {
                options.add(entry.getOption());
            }
        }
        return options;
    }

    @Provides
    JEIConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(JEIConfig.class);
    }

    private BufferedImage createIcon() {
        BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setStroke(new BasicStroke(2.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(40, 30, 8));
        g.drawOval(1, 1, 9, 9);
        g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(230, 200, 90));
        g.drawOval(1, 1, 9, 9);
        g.setStroke(new BasicStroke(2.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(50, 30, 10));
        g.drawLine(9, 9, 14, 14);
        g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(120, 80, 35));
        g.drawLine(9, 9, 14, 14);
        g.dispose();
        return img;
    }
}

package com.osr.jei;

import java.awt.*;

/**
 * A FlowLayout variant that correctly reports its preferred height to a JScrollPane
 * so that items wrap to the next row instead of scrolling horizontally.
 *
 * The standard FlowLayout always returns a single-row height to
 * preferredLayoutSize(), which makes JScrollPane think no vertical scrolling is
 * needed.  This class fixes that by walking each "virtual" row and summing heights.
 *
 * Based on Rob Camick's WrapLayout:
 * https://tips4java.wordpress.com/2008/11/06/wrap-layout/
 */
public class WrapLayout extends FlowLayout {

    public WrapLayout() {
        super(LEFT, 2, 2);
    }

    public WrapLayout(int align, int hgap, int vgap) {
        super(align, hgap, vgap);
    }

    @Override
    public Dimension preferredLayoutSize(Container target) {
        return layoutSize(target, true);
    }

    @Override
    public Dimension minimumLayoutSize(Container target) {
        Dimension minimum = layoutSize(target, false);
        minimum.width -= (getHgap() + 1);
        return minimum;
    }

    private Dimension layoutSize(Container target, boolean preferred) {
        synchronized (target.getTreeLock()) {
            // On the first pass the container has zero width — walk up until we find
            // a parent that already has a real size so wrapping is calculated correctly.
            int targetWidth = target.getSize().width;
            Container parent = target;
            while (targetWidth == 0 && parent.getParent() != null) {
                parent = parent.getParent();
                targetWidth = parent.getSize().width;
            }
            if (targetWidth == 0) {
                targetWidth = Integer.MAX_VALUE;
            }

            int hgap = getHgap();
            int vgap = getVgap();
            Insets insets = target.getInsets();
            int horizontalInsetsAndGap = insets.left + insets.right + (hgap * 2);
            int maxWidth = targetWidth - horizontalInsetsAndGap;

            Dimension dim = new Dimension(0, 0);
            int rowWidth  = 0;
            int rowHeight = 0;

            int count = target.getComponentCount();
            for (int i = 0; i < count; i++) {
                Component m = target.getComponent(i);
                if (!m.isVisible()) continue;

                Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();

                if (rowWidth + d.width > maxWidth) {
                    addRow(dim, rowWidth, rowHeight);
                    rowWidth  = 0;
                    rowHeight = 0;
                }

                if (rowWidth != 0) rowWidth += hgap;
                rowWidth  += d.width;
                rowHeight  = Math.max(rowHeight, d.height);
            }
            addRow(dim, rowWidth, rowHeight);

            dim.width  += horizontalInsetsAndGap;
            dim.height += insets.top + insets.bottom + vgap * 2;
            return dim;
        }
    }

    private void addRow(Dimension dim, int rowWidth, int rowHeight) {
        dim.width = Math.max(dim.width, rowWidth);
        if (dim.height > 0) dim.height += getVgap();
        dim.height += rowHeight;
    }
}

package com.osr.jei.crafting;

import com.osr.jei.model.DropEntry;
import com.osr.jei.model.RecipeInfo;
import com.osr.jei.model.ShopEntry;
import com.osr.jei.service.ItemDetails;

import java.util.Locale;

/**
 * An item is a base material when it can be obtained without crafting it
 * from other items: a gathering recipe, a shop, a monster drop, or the
 * {@link RawMaterials} fallback when the page has not been read.
 * An optional recipe does not make it a crafting step.
 */
public final class BaseMaterials {

    private BaseMaterials() {
    }

    public static boolean isBase(String name, ItemDetails details) {
        if (RawMaterials.isBase(name)) {
            return true;
        }
        if (details == null || details.missing) {
            return false;
        }
        return soldInShop(details) || droppedByMonster(details) || gathered(details);
    }

    public static boolean gathered(ItemDetails details) {
        if (details == null || details.recipes == null) {
            return false;
        }
        for (RecipeInfo recipe : details.recipes) {
            if (recipe == null) {
                continue;
            }
            if (isGathering(recipe.skill) || isGathering(recipe.skill2)) {
                return true;
            }
        }
        return false;
    }

    public static boolean isGathering(String skill) {
        if (skill == null) {
            return false;
        }
        String text = skill.trim().toLowerCase(Locale.ROOT);
        return "mining".equals(text)
            || "woodcutting".equals(text)
            || "fishing".equals(text)
            || "hunter".equals(text)
            || "farming".equals(text);
    }

    private static boolean soldInShop(ItemDetails details) {
        if (details.shops == null) {
            return false;
        }
        for (ShopEntry shop : details.shops) {
            if (shop != null && shop.sells) {
                return true;
            }
        }
        return false;
    }

    private static boolean droppedByMonster(ItemDetails details) {
        if (details.drops == null) {
            return false;
        }
        for (DropEntry drop : details.drops) {
            if (drop != null && drop.getSource() != null && !drop.getSource().isEmpty()) {
                return true;
            }
        }
        return false;
    }

}

package com.osr.jei.crafting;

import com.osr.jei.model.RecipeInfo;
import com.osr.jei.model.RecipeIngredient;
import com.osr.jei.service.ItemDetails;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Expandable crafting tree. The root page is passed in and is never fetched.
 * Sub-pages are read from {@link RecipePages#cached} or, while expanding,
 * {@link RecipePages#load}. Cycles along the active path stop without another
 * request. Depth and the unique-item cap bound how far a walk can go.
 */
public final class BuildExpander {

    public static final int MAX_DEPTH = 4;
    public static final int MAX_NODES = 20;
    public static final String SEP = "\u001f";

    public static final class BuildNode {
        public final String name;
        public final long quantity;
        public final int depth;
        public final String path;
        public final boolean cycle;
        public final boolean capped;
        public final boolean loading;
        public final boolean expanded;
        /** First recipe used for this node, when it was expanded and one exists. */
        public final RecipeInfo recipe;
        /** Further recipes on the same page, not folded into the rollup. */
        public final int otherRecipes;
        public final List<BuildNode> children;
        /** False for a leaf. Unknown pages stay true until a load proves otherwise. */
        public final boolean showExpander;

        BuildNode(
            String name,
            long quantity,
            int depth,
            String path,
            boolean cycle,
            boolean capped,
            boolean loading,
            boolean expanded,
            RecipeInfo recipe,
            int otherRecipes,
            List<BuildNode> children,
            boolean showExpander
        ) {
            this.name = name;
            this.quantity = quantity;
            this.depth = depth;
            this.path = path;
            this.cycle = cycle;
            this.capped = capped;
            this.loading = loading;
            this.expanded = expanded;
            this.recipe = recipe;
            this.otherRecipes = otherRecipes;
            this.children = children;
            this.showExpander = showExpander;
        }

        public boolean expandable() {
            return !cycle && !capped && !loading && depth < MAX_DEPTH;
        }
    }

    public static final class RecipeBranch {
        public final RecipeInfo recipe;
        public final List<BuildNode> ingredients;
        /** Empty until at least one ingredient on this branch is expanded. */
        public final Map<String, Long> baseMaterials;

        RecipeBranch(RecipeInfo recipe, List<BuildNode> ingredients, Map<String, Long> baseMaterials) {
            this.recipe = recipe;
            this.ingredients = ingredients;
            this.baseMaterials = baseMaterials;
        }
    }

    public static final class Result {
        public final List<RecipeBranch> recipes;
        public final int fetches;
        public final int uniqueNodes;
        public final List<String> expandedPaths;
        /** Names whose pages still need a fetch. Empty when {@code fetchMissing} ran. */
        public final List<String> pending;

        Result(
            List<RecipeBranch> recipes,
            int fetches,
            int uniqueNodes,
            List<String> expandedPaths,
            List<String> pending
        ) {
            this.recipes = recipes;
            this.fetches = fetches;
            this.uniqueNodes = uniqueNodes;
            this.expandedPaths = expandedPaths;
            this.pending = pending;
        }
    }

    private BuildExpander() {
    }

    /** Open every eligible node, fetching pages that are not cached yet. */
    public static Result expandAll(String rootName, Integer rootId, ItemDetails root, RecipePages pages) {
        return walk(rootName, rootId, root, pages, Collections.emptySet(), true);
    }

    /**
     * Open only {@code expandedPaths}. Missing pages are listed as pending
     * and are not fetched here, so this is safe on the EDT.
     */
    public static Result expandSelected(
        String rootName,
        Integer rootId,
        ItemDetails root,
        RecipePages pages,
        Set<String> expandedPaths
    ) {
        return walk(rootName, rootId, root, pages, expandedPaths == null ? Collections.emptySet() : expandedPaths, false);
    }

    private static Result walk(
        String rootName,
        Integer rootId,
        ItemDetails root,
        RecipePages pages,
        Set<String> forcedPaths,
        boolean fetchMissing
    ) {
        Set<String> ancestors = new HashSet<>();
        ancestors.add(nameKey(rootName));
        if (rootId != null) {
            ancestors.add(idKey(rootId));
        }
        Set<String> unique = new LinkedHashSet<>();
        unique.add(norm(rootName));
        Map<String, ItemDetails> local = new HashMap<>();
        List<String> opened = new ArrayList<>();
        List<String> pending = new ArrayList<>();
        int[] fetches = new int[1];

        List<RecipeInfo> recipes = root == null || root.recipes == null
            ? Collections.emptyList()
            : root.recipes;
        List<RecipeBranch> branches = new ArrayList<>();
        for (int i = 0; i < recipes.size(); i++) {
            RecipeInfo recipe = recipes.get(i);
            long batch = Math.max(1, recipe.outputQuantity);
            List<BuildNode> ingredients = new ArrayList<>();
            if (recipe.ingredients != null) {
                for (RecipeIngredient ingredient : recipe.ingredients) {
                    long quantity = RecipeText.scale(batch, recipe.outputQuantity, ingredient.quantity);
                    String path = i + SEP + ingredient.name;
                    ingredients.add(node(
                        ingredient.name,
                        quantity,
                        1,
                        path,
                        ancestors,
                        unique,
                        local,
                        pages,
                        forcedPaths,
                        fetchMissing,
                        fetches,
                        opened,
                        pending
                    ));
                }
            }
            branches.add(new RecipeBranch(recipe, ingredients, rollup(ingredients)));
        }
        return new Result(branches, fetches[0], unique.size(), opened, pending);
    }

    private static BuildNode node(
        String name,
        long quantity,
        int depth,
        String path,
        Set<String> ancestors,
        Set<String> unique,
        Map<String, ItemDetails> local,
        RecipePages pages,
        Set<String> forcedPaths,
        boolean fetchMissing,
        int[] fetches,
        List<String> opened,
        List<String> pending
    ) {
        String key = norm(name);
        Integer id = pages == null ? null : pages.idFor(name);
        boolean cycle = ancestors.contains(nameKey(name)) || (id != null && ancestors.contains(idKey(id)));
        if (cycle) {
            return new BuildNode(name, quantity, depth, path, true, false, false, false, null, 0, Collections.emptyList(), false);
        }
        if (depth >= MAX_DEPTH) {
            return new BuildNode(name, quantity, depth, path, false, true, false, false, null, 0, Collections.emptyList(), false);
        }

        boolean known = unique.contains(key);
        if (!known && unique.size() >= MAX_NODES) {
            return new BuildNode(name, quantity, depth, path, false, true, false, false, null, 0, Collections.emptyList(), false);
        }

        boolean want = fetchMissing || forcedPaths.contains(path);
        if (!want) {
            ItemDetails cached = pages == null ? null : pages.cached(name);
            boolean expander = showExpander(name, cached);
            return new BuildNode(name, quantity, depth, path, false, false, false, false, null, 0, Collections.emptyList(), expander);
        }

        ItemDetails details = lookup(key, name, local, pages, fetchMissing, fetches);
        if (details == null) {
            if (!pending.contains(name)) {
                pending.add(name);
            }
            return new BuildNode(name, quantity, depth, path, false, false, true, true, null, 0, Collections.emptyList(), true);
        }
        if (!known) {
            unique.add(key);
        }

        RecipeInfo chosen = firstRecipe(details);
        int others = details.recipes == null ? 0 : Math.max(0, details.recipes.size() - (chosen == null ? 0 : 1));
        opened.add(path);
        if (chosen == null || chosen.ingredients == null || chosen.ingredients.isEmpty()) {
            return new BuildNode(name, quantity, depth, path, false, false, false, true, chosen, others, Collections.emptyList(), false);
        }

        Set<String> nextAncestors = new HashSet<>(ancestors);
        nextAncestors.add(nameKey(name));
        if (id != null) {
            nextAncestors.add(idKey(id));
        }
        List<BuildNode> children = new ArrayList<>();
        for (RecipeIngredient ingredient : chosen.ingredients) {
            long childQty = RecipeText.scale(quantity, chosen.outputQuantity, ingredient.quantity);
            String childPath = path + SEP + ingredient.name;
            children.add(node(
                ingredient.name,
                childQty,
                depth + 1,
                childPath,
                nextAncestors,
                unique,
                local,
                pages,
                forcedPaths,
                fetchMissing,
                fetches,
                opened,
                pending
            ));
        }
        return new BuildNode(name, quantity, depth, path, false, false, false, true, chosen, others, children, true);
    }

    /**
     * A classified base material never offers an arrow, even when its page
     * has not been fetched. An unknown crafted item still does.
     */
    private static boolean showExpander(String name, ItemDetails cached) {
        if (BaseMaterials.isBase(name, cached)) {
            return false;
        }
        if (cached == null) {
            return true;
        }
        return hasExpandableRecipe(cached);
    }

    private static boolean hasExpandableRecipe(ItemDetails details) {
        if (details == null || details.recipes == null) {
            return false;
        }
        for (RecipeInfo recipe : details.recipes) {
            if (recipe != null && recipe.ingredients != null && !recipe.ingredients.isEmpty()) {
                return true;
            }
        }
        return false;
    }

    private static ItemDetails lookup(
        String key,
        String name,
        Map<String, ItemDetails> local,
        RecipePages pages,
        boolean fetchMissing,
        int[] fetches
    ) {
        ItemDetails details = local.get(key);
        if (details != null) {
            return details;
        }
        if (pages != null) {
            details = pages.cached(name);
        }
        if (details != null) {
            local.put(key, details);
            return details;
        }
        if (!fetchMissing || pages == null) {
            return null;
        }
        details = pages.load(name);
        fetches[0]++;
        if (details == null) {
            details = ItemDetails.EMPTY;
        }
        local.put(key, details);
        return details;
    }

    private static RecipeInfo firstRecipe(ItemDetails details) {
        if (details == null || details.recipes == null) {
            return null;
        }
        for (RecipeInfo recipe : details.recipes) {
            if (recipe != null && recipe.ingredients != null && !recipe.ingredients.isEmpty()) {
                return recipe;
            }
        }
        return details.recipes.isEmpty() ? null : details.recipes.get(0);
    }

    static Map<String, Long> rollup(List<BuildNode> ingredients) {
        boolean any = false;
        for (BuildNode ingredient : ingredients) {
            if (ingredient.expanded || ingredient.loading || !ingredient.showExpander) {
                any = true;
                break;
            }
        }
        if (!any) {
            return Collections.emptyMap();
        }
        Map<String, Long> totals = new LinkedHashMap<>();
        for (BuildNode ingredient : ingredients) {
            collect(ingredient, totals);
        }
        return totals;
    }

    private static void collect(BuildNode node, Map<String, Long> totals) {
        if (node.cycle) {
            return;
        }
        if (node.children.isEmpty()) {
            totals.merge(node.name, node.quantity, Long::sum);
            return;
        }
        for (BuildNode child : node.children) {
            collect(child, totals);
        }
    }

    private static String norm(String name) {
        return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
    }

    private static String nameKey(String name) {
        return "n:" + norm(name);
    }

    private static String idKey(int id) {
        return "i:" + id;
    }
}

package com.osr.jei.crafting;

import java.util.Locale;

/**
 * Items that are gathered, not crafted. The crafting tree already treats them
 * as base materials, so they do not get an expand arrow and do not need a
 * wiki fetch to prove they have no recipe.
 */
public final class RawMaterials {

    private RawMaterials() {
    }

    public static boolean isBase(String name) {
        if (name == null) {
            return false;
        }
        String text = name.trim().toLowerCase(Locale.ROOT);
        if (text.isEmpty()) {
            return false;
        }
        if (text.endsWith(" essence") || text.equals("essence")) {
            return true;
        }
        if (text.endsWith(" ore") || text.equals("coal") || text.equals("clay") || text.equals("soft clay")) {
            return true;
        }
        if (text.equals("logs") || text.equals("log") || text.endsWith(" logs")) {
            return true;
        }
        if (text.startsWith("raw ")) {
            return true;
        }
        if (text.endsWith(" herb") || text.startsWith("grimy ")) {
            return true;
        }
        return false;
    }
}

package com.osr.jei.crafting;

import com.osr.jei.service.ItemDetails;

/**
 * Recipe pages for a build path. {@link #cached} must not hit the network.
 * {@link #load} is the coalesced fetch and is only used while expanding.
 */
public interface RecipePages {

    ItemDetails cached(String itemName);

    ItemDetails load(String itemName);

    /** Item id when the search index knows this name, otherwise null. */
    default Integer idFor(String itemName) {
        return null;
    }
}

package com.osr.jei.crafting;

import com.osr.jei.model.RecipeInfo;

import java.util.List;

/** One-line skill, level, facility, and XP summary. */
public final class RecipeText {

    private RecipeText() {
    }

    public static String summary(RecipeInfo recipe) {
        if (recipe == null) {
            return "";
        }
        StringBuilder info = new StringBuilder();
        if (recipe.skill != null && !recipe.skill.isEmpty()) {
            info.append(recipe.skill);
            if (recipe.level > 0) {
                info.append(" (Lv. ").append(recipe.level).append(")");
            }
        }
        if (recipe.skill2 != null && !recipe.skill2.isEmpty()) {
            if (info.length() > 0) {
                info.append(" \u00b7 ");
            }
            info.append(recipe.skill2);
            if (recipe.level2 > 0) {
                info.append(" (Lv. ").append(recipe.level2).append(")");
            }
        }
        if (recipe.facility != null && !recipe.facility.isEmpty()) {
            if (info.length() > 0) {
                info.append(" \u00b7 ");
            }
            info.append(recipe.facility);
        }
        if (recipe.experience > 0) {
            if (info.length() > 0) {
                info.append(" \u00b7 ");
            }
            if (recipe.experience == Math.floor(recipe.experience)) {
                info.append((int) recipe.experience);
            } else {
                info.append(recipe.experience);
            }
            info.append(" XP");
        }
        if (recipe.outputQuantity > 1) {
            if (info.length() > 0) {
                info.append(" \u00b7 ");
            }
            info.append("Makes ").append(recipe.outputQuantity);
        }
        return info.toString();
    }

    /**
     * Puts ingredients that loop back to an ancestor on the recipe line.
     * Names are joined with {@code +}. An existing skill summary stays in front.
     */
    public static String withLoopedIngredients(String summary, List<String> loopedNames) {
        String names = joinNames(loopedNames);
        if (names.isEmpty()) {
            return summary == null ? "" : summary;
        }
        if (summary == null || summary.isEmpty()) {
            return names;
        }
        return summary + " \u00b7 " + names;
    }

    private static String joinNames(List<String> names) {
        if (names == null || names.isEmpty()) {
            return "";
        }
        StringBuilder joined = new StringBuilder();
        for (String name : names) {
            if (name == null || name.trim().isEmpty()) {
                continue;
            }
            if (joined.length() > 0) {
                joined.append(" + ");
            }
            joined.append(name.trim());
        }
        return joined.toString();
    }

    /**
     * Materials for {@code needed} outputs. {@code outputQuantity} is how many
     * one craft produces; the result is rounded up to a whole craft.
     */
    public static long scale(long needed, int outputQuantity, int materialQuantity) {
        if (needed <= 0 || materialQuantity <= 0) {
            return 0;
        }
        int produced = Math.max(1, outputQuantity);
        long crafts = (needed + produced - 1) / produced;
        if (crafts > Long.MAX_VALUE / materialQuantity) {
            return Long.MAX_VALUE;
        }
        return crafts * materialQuantity;
    }
}

package com.osr.jei.drops;

import com.osr.jei.model.DropEntry;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
/**
 * One drop row per monster and combat level. The wiki lists a separate line
 * for each quantity. Those lines become one row: the level, then each
 * quantity with its own rate, most common first.
 */
public final class DropMerger {

    /** Joins the wiki rate cells stored on a merged row. Not used in the label. */
    static final String RATE_SEP = " | ";

    private DropMerger() {
    }

    public static List<DropEntry> merge(List<DropEntry> drops) {
        Map<String, List<DropEntry>> groups = new LinkedHashMap<>();
        if (drops != null) {
            for (DropEntry drop : drops) {
                if (drop == null || drop.getSource() == null || drop.getSource().trim().isEmpty()) {
                    continue;
                }
                groups.computeIfAbsent(key(drop), ignored -> new ArrayList<>()).add(drop);
            }
        }
        List<DropEntry> merged = new ArrayList<>();
        for (List<DropEntry> group : groups.values()) {
            merged.add(group.size() == 1 ? group.get(0) : combine(group));
        }
        return merged;
    }

    /**
     * One variant is {@code Lv. 48 · 5 at 1/51.2}. Several variants put the
     * level on its own line, then {@code 7 at 1/6.4} and {@code 2 at 1/8.53}.
     */
    public static String detail(DropEntry drop) {
        if (drop == null) {
            return "?";
        }
        List<String> pairs = pairs(drop);
        String level = levelText(drop);
        if (pairs.size() <= 1) {
            String pair = pairs.isEmpty() ? "" : pairs.get(0);
            if (level.isEmpty()) {
                return pair.isEmpty() ? "?" : pair;
            }
            if (pair.isEmpty()) {
                return level;
            }
            return level + " \u00b7 " + pair;
        }
        StringBuilder text = new StringBuilder();
        if (!level.isEmpty()) {
            text.append(level);
        }
        for (String pair : pairs) {
            if (pair.isEmpty()) {
                continue;
            }
            if (text.length() > 0) {
                text.append('\n');
            }
            text.append(pair);
        }
        return text.length() == 0 ? "?" : text.toString();
    }

    /** Tooltip text. Merged rows keep every original wiki fraction. */
    public static String tooltipRate(DropEntry drop) {
        String rate = drop == null || drop.getRate() == null ? "" : drop.getRate();
        if (rate.contains(RATE_SEP)) {
            return rate.replace(RATE_SEP, ", ");
        }
        DropRate parsed = DropRate.parse(rate, drop == null ? null : drop.getQuantity());
        if (parsed.original != null && !parsed.original.isEmpty()) {
            return parsed.original;
        }
        return parsed.display == null ? "" : parsed.display;
    }

    private static DropEntry combine(List<DropEntry> group) {
        DropEntry first = group.get(0);
        List<Rated> rated = new ArrayList<>();
        for (int i = 0; i < group.size(); i++) {
            String quantity = shownQuantity(group.get(i).getQuantity());
            String original = group.get(i).getRate() == null ? "" : group.get(i).getRate().trim();
            if (quantity.isEmpty() && original.isEmpty()) {
                continue;
            }
            boolean seen = false;
            for (Rated existing : rated) {
                if (existing.quantity.equals(quantity) && existing.original.equals(original)) {
                    seen = true;
                    break;
                }
            }
            if (seen) {
                continue;
            }
            DropRate parsed = DropRate.parse(original, quantity.isEmpty() ? null : quantity);
            rated.add(new Rated(quantity, original, parsed.probability, i));
        }
        rated.sort((left, right) -> {
            if (left.probability == null && right.probability == null) {
                return Integer.compare(left.order, right.order);
            }
            if (left.probability == null) {
                return 1;
            }
            if (right.probability == null) {
                return -1;
            }
            int chance = Double.compare(right.probability, left.probability);
            return chance != 0 ? chance : Integer.compare(left.order, right.order);
        });
        DropEntry combined = new DropEntry();
        combined.setSource(first.getSource());
        combined.setLevel(first.getLevel() == null ? "" : first.getLevel().trim());
        combined.setLevelKind(first.getLevelKind() == null ? "" : first.getLevelKind());
        combined.setQuantity(join(rated, true));
        combined.setRate(join(rated, false));
        combined.setRarity(first.getRarity() == null ? "" : first.getRarity());
        return combined;
    }

    private static String join(List<Rated> rated, boolean quantity) {
        StringBuilder joined = new StringBuilder();
        for (Rated entry : rated) {
            if (joined.length() > 0) {
                joined.append(RATE_SEP);
            }
            joined.append(quantity ? entry.quantity : entry.original);
        }
        return joined.toString();
    }

    private static List<String> pairs(DropEntry drop) {
        String rate = drop.getRate() == null ? "" : drop.getRate();
        String quantity = drop.getQuantity() == null ? "" : drop.getQuantity();
        boolean several = rate.contains(RATE_SEP) || quantity.contains(RATE_SEP);
        String[] rates = several ? rate.split("\\|", -1) : new String[] {rate};
        String[] quantities = several ? quantity.split("\\|", -1) : new String[] {quantity};
        int count = Math.max(rates.length, quantities.length);
        List<String> pairs = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            String qty = shownQuantity(i < quantities.length ? quantities[i] : "");
            String original = i < rates.length ? rates[i].trim() : "";
            String display = displayOf(DropRate.parse(original, qty.isEmpty() ? null : qty));
            if (!qty.isEmpty() && !display.isEmpty()) {
                pairs.add(qty + " at " + display);
            } else if (!display.isEmpty()) {
                pairs.add(display);
            } else if (!qty.isEmpty()) {
                pairs.add(qty);
            }
        }
        return pairs;
    }

    private static String levelText(DropEntry drop) {
        String level = drop.getLevel() == null ? "" : drop.getLevel().trim();
        level = level.replace('\u2013', '-').replace('\u2014', '-').replace('\u2212', '-');
        if (level.isEmpty() || "?".equals(level) || "n/a".equalsIgnoreCase(level)) {
            return "";
        }
        String kind = drop.getLevelKind() == null ? "" : drop.getLevelKind().trim().toLowerCase(Locale.ROOT);
        if (kind.isEmpty() || "combat".equals(kind)) {
            return "Lv. " + level;
        }
        if ("reward".equals(kind)) {
            return "";
        }
        return Character.toUpperCase(kind.charAt(0)) + kind.substring(1) + " " + level;
    }

    private static String shownQuantity(String quantity) {
        String text = quantity == null ? "" : quantity.trim();
        if (text.isEmpty() || "?".equals(text)) {
            return "";
        }
        return text;
    }

    private static String displayOf(DropRate parsed) {
        if (parsed == null || parsed.display == null || parsed.display.isEmpty() || "?".equals(parsed.display)) {
            return "";
        }
        return parsed.display;
    }

    private static String key(DropEntry drop) {
        return norm(drop.getSource()) + "\n" + norm(drop.getLevel());
    }

    private static String norm(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
    }

    private static final class Rated {
        private final String quantity;
        private final String original;
        private final Double probability;
        private final int order;

        private Rated(String quantity, String original, Double probability, int order) {
            this.quantity = quantity;
            this.original = original;
            this.probability = probability;
            this.order = order;
        }
    }
}

package com.osr.jei.drops;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Normalizes a drop-table rate to {@code 1/X}. The original cell text is kept
 * for the tooltip. A quantity such as {@code 1-3} is not itself a rate.
 */
public final class DropRate {

    private static final Pattern FRACTION = Pattern.compile("(\\d+(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:\\.\\d+)?)");
    private static final Pattern PERCENT = Pattern.compile("(\\d+(?:\\.\\d+)?)\\s*%");
    private static final Pattern TIMES = Pattern.compile("(?i)(\\d+(?:\\.\\d+)?)\\s*x\\s*\\d");
    private static final Pattern QUANTITY_PREFIX = Pattern.compile("(?i)^\\s*\\d+\\s*-\\s*\\d+\\s*x\\s*");
    private static final Pattern QUANTITY_ONLY = Pattern.compile("\\d+\\s*-\\s*\\d+");

    public final String display;
    public final String original;
    /** Chance from 0 to 1, or null when the cell is not a number (for example {@code Rare}). */
    public final Double probability;

    private DropRate(String display, String original, Double probability) {
        this.display = display;
        this.original = original == null ? "" : original;
        this.probability = probability;
    }

    public static DropRate parse(String rate, String quantity) {
        String original = rate == null ? "" : rate.trim();
        if (original.isEmpty()) {
            return new DropRate("?", "", null);
        }
        String working = original
            .replace('\u00d7', 'x')
            .replace('\u2013', '-')
            .replace('\u2014', '-')
            .replace("~", "")
            .replace(",", "")
            .trim();
        working = QUANTITY_PREFIX.matcher(working).replaceFirst("");
        String lower = working.toLowerCase(Locale.ROOT).trim();
        if (lower.equals("always") || lower.equals("guaranteed") || lower.equals("every kill") || lower.equals("100%")) {
            return new DropRate("1/1", original, 1.0);
        }
        if (isWord(lower)) {
            return new DropRate(original, original, null);
        }
        if (QUANTITY_ONLY.matcher(lower).matches()) {
            return new DropRate(original, original, null);
        }
        List<Double> chances = new ArrayList<>();
        Matcher fractions = FRACTION.matcher(working);
        while (fractions.find()) {
            double numerator = Double.parseDouble(fractions.group(1));
            double denominator = Double.parseDouble(fractions.group(2));
            if (denominator > 0) {
                chances.add(numerator / denominator);
            }
        }
        if (chances.size() == 1) {
            double chance = chances.get(0);
            Matcher times = TIMES.matcher(working);
            if (times.find()) {
                chance = chance * Double.parseDouble(times.group(1));
            }
            if (chance < 0) {
                chance = 0;
            }
            return new DropRate(oneOver(Math.min(chance, 1.0)), original, Math.min(chance, 1.0));
        }
        if (chances.size() >= 2) {
            double first = chances.get(0);
            double second = chances.get(chances.size() - 1);
            String display = oneOver(first) + "\u2013" + oneOver(second);
            return new DropRate(display, original, (first + second) / 2.0);
        }
        Matcher percent = PERCENT.matcher(working);
        if (percent.find()) {
            double chance = Double.parseDouble(percent.group(1)) / 100.0;
            return new DropRate(oneOver(chance), original, chance);
        }
        if (quantity != null && QUANTITY_ONLY.matcher(quantity.trim().replace('\u2013', '-')).matches() && original.isEmpty()) {
            return new DropRate("?", "", null);
        }
        return new DropRate(original, original, null);
    }

    static String oneOver(double probability) {
        if (probability >= 1.0) {
            return "1/1";
        }
        if (probability <= 0) {
            return "1/\u221e";
        }
        double denominator = 1.0 / probability;
        double nearest = Math.rint(denominator);
        if (Math.abs(denominator - nearest) < 0.001) {
            return "1/" + (long) nearest;
        }
        String rounded = String.format(Locale.ROOT, "%.2f", denominator);
        if (rounded.endsWith("0")) {
            rounded = rounded.substring(0, rounded.length() - 1);
        }
        if (rounded.endsWith(".0")) {
            rounded = rounded.substring(0, rounded.length() - 2);
        }
        return "1/" + rounded;
    }

    private static boolean isWord(String lower) {
        return lower.equals("rare")
            || lower.equals("very rare")
            || lower.equals("uncommon")
            || lower.equals("common")
            || lower.equals("varies")
            || lower.equals("unknown");
    }
}

