package com.osr.jei.drops;

import com.osr.jei.model.DropEntry;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Orders an already-parsed drop list. Missing combat levels sort after every real level. */
public final class DropSorter {

    private static final Pattern NUMBER = Pattern.compile("(\\d+)");

    private DropSorter() {
    }

    public static List<DropEntry> ordered(List<DropEntry> drops, DropSort sort) {
        List<DropEntry> copy = new ArrayList<>();
        if (drops != null) {
            copy.addAll(drops);
        }
        DropSort mode = sort == null ? DropSort.RATE : sort;
        copy.sort(comparator(mode));
        return copy;
    }

    /** First combat level in the cell, or {@link Integer#MAX_VALUE} when there is none. */
    public static int combatRank(String level) {
        if (level == null) {
            return Integer.MAX_VALUE;
        }
        String trimmed = level.trim();
        if (trimmed.isEmpty() || trimmed.equals("?") || trimmed.equalsIgnoreCase("n/a") || trimmed.equals("-")) {
            return Integer.MAX_VALUE;
        }
        Matcher matcher = NUMBER.matcher(trimmed);
        if (!matcher.find()) {
            return Integer.MAX_VALUE;
        }
        try {
            return Integer.parseInt(matcher.group(1));
        } catch (NumberFormatException e) {
            return Integer.MAX_VALUE;
        }
    }

    private static Comparator<DropEntry> comparator(DropSort sort) {
        Comparator<DropEntry> name = new Comparator<DropEntry>() {
            @Override
            public int compare(DropEntry left, DropEntry right) {
                return source(left).compareToIgnoreCase(source(right));
            }
        };
        if (sort == DropSort.NAME) {
            return name;
        }
        if (sort == DropSort.COMBAT) {
            return new Comparator<DropEntry>() {
                @Override
                public int compare(DropEntry left, DropEntry right) {
                    int levels = Integer.compare(combatRank(left.getLevel()), combatRank(right.getLevel()));
                    return levels != 0 ? levels : name.compare(left, right);
                }
            };
        }
        return new Comparator<DropEntry>() {
            @Override
            public int compare(DropEntry left, DropEntry right) {
                Double leftChance = DropRate.parse(left.getRate(), left.getQuantity()).probability;
                Double rightChance = DropRate.parse(right.getRate(), right.getQuantity()).probability;
                if (leftChance == null && rightChance == null) {
                    return name.compare(left, right);
                }
                if (leftChance == null) {
                    return 1;
                }
                if (rightChance == null) {
                    return -1;
                }
                int rate = Double.compare(rightChance, leftChance);
                return rate != 0 ? rate : name.compare(left, right);
            }
        };
    }

    private static String source(DropEntry drop) {
        if (drop == null || drop.getSource() == null) {
            return "";
        }
        return drop.getSource();
    }
}

package com.osr.jei.drops;

import com.osr.jei.model.DropEntry;

import java.util.Locale;

/**
 * Drop sources that are not monsters. The wiki marks the level cell with
 * {@code drops-combat}, {@code drops-sailing}, {@code drops-hunter},
 * {@code drops-thieving}, or {@code drops-reward}.
 */
public final class DropSources {

    public static final String MONSTER_EMPTY = "No locations are listed for this monster.";
    public static final String OTHER_EMPTY = "No locations are listed.";

    private DropSources() {
    }

    public static boolean monster(DropEntry drop) {
        String kind = kind(drop);
        return kind.isEmpty() || "combat".equals(kind);
    }

    /** Show on map needs coordinates and at least one place. A source with neither stays a text row. */
    public static boolean showMap(DropEntry drop, boolean mapped, int places) {
        return mapped && places > 0;
    }

    public static String emptyLocations(DropEntry drop) {
        return monster(drop) ? MONSTER_EMPTY : OTHER_EMPTY;
    }

    private static String kind(DropEntry drop) {
        if (drop == null || drop.getLevelKind() == null) {
            return "";
        }
        return drop.getLevelKind().trim().toLowerCase(Locale.ROOT);
    }
}

package com.osr.jei.equipment;

import com.osr.jei.model.EquipmentStats;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Bonus deltas against what is worn. A two-handed weapon replaces both the
 * weapon and the shield. Equipping a shield or a one-handed weapon while a
 * two-handed weapon is worn removes that weapon and does not also subtract a shield.
 */
public final class EquipmentCompare {

    private EquipmentCompare() {
    }

    /** One worn item's parsed bonuses. {@code weight} is NaN when the page has no weight. */
    public static final class Piece {
        public final EquipmentStats stats;
        public final double weight;

        public Piece(EquipmentStats stats, double weight) {
            this.stats = stats;
            this.weight = weight;
        }

        public boolean twoHanded() {
            return stats != null && stats.twoHanded();
        }
    }

    public static final class Delta {
        public final String label;
        public final double amount;
        public final boolean lowerIsBetter;
        public final boolean known;

        Delta(String label, double amount, boolean lowerIsBetter, boolean known) {
            this.label = label;
            this.amount = amount;
            this.lowerIsBetter = lowerIsBetter;
            this.known = known;
        }

        /** 1 when the change is better, -1 when it is worse, 0 when it is zero or unknown. */
        public int sign() {
            if (!known || amount == 0) {
                return 0;
            }
            boolean better = lowerIsBetter ? amount < 0 : amount > 0;
            return better ? 1 : -1;
        }
    }

    public static final class Result {
        public final String note;
        public final List<Delta> deltas;

        Result(String note, List<Delta> deltas) {
            this.note = note;
            this.deltas = deltas;
        }
    }

    public static Result compare(EquipmentStats item, double itemWeight, Piece weapon, Piece shield, Piece sameSlot) {
        if (item == null) {
            return new Result("", Collections.<Delta>emptyList());
        }
        GearSlot slot = GearSlot.fromWiki(item.slot);
        List<Piece> baseline = new ArrayList<>();
        String note = "Nothing in that slot";
        if (slot == GearSlot.WEAPON && item.twoHanded()) {
            if (weapon != null && weapon.twoHanded()) {
                baseline.add(weapon);
                note = "Replaces your two-handed weapon";
            } else {
                if (weapon != null) {
                    baseline.add(weapon);
                }
                if (shield != null) {
                    baseline.add(shield);
                }
                if (weapon != null && shield != null) {
                    note = "Replaces your weapon and shield";
                } else if (weapon != null) {
                    note = "Replaces your weapon";
                } else if (shield != null) {
                    note = "Replaces your shield";
                }
            }
        } else if (slot == GearSlot.WEAPON) {
            if (weapon != null) {
                baseline.add(weapon);
                note = weapon.twoHanded() ? "Replaces your two-handed weapon" : "Compared with your weapon";
            }
        } else if (slot == GearSlot.SHIELD) {
            if (weapon != null && weapon.twoHanded()) {
                baseline.add(weapon);
                note = "Replaces your two-handed weapon";
            } else if (shield != null) {
                baseline.add(shield);
                note = "Compared with your shield";
            }
        } else if (sameSlot != null) {
            baseline.add(sameSlot);
            note = "Compared with what you have equipped";
        }
        boolean includeSpeed = item.speed > 0 || slot == GearSlot.WEAPON;
        return new Result(note, deltas(item, itemWeight, baseline, includeSpeed));
    }

    private static List<Delta> deltas(EquipmentStats item, double itemWeight, List<Piece> baseline, boolean includeSpeed) {
        int[] worn = new int[14];
        double wornWeight = 0;
        boolean weightKnown = !Double.isNaN(itemWeight);
        int wornSpeed = 0;
        boolean sawWeaponSpeed = false;
        for (Piece piece : baseline) {
            if (piece == null || piece.stats == null) {
                continue;
            }
            EquipmentStats stats = piece.stats;
            worn[0] += stats.attackStab;
            worn[1] += stats.attackSlash;
            worn[2] += stats.attackCrush;
            worn[3] += stats.attackMagic;
            worn[4] += stats.attackRange;
            worn[5] += stats.defStab;
            worn[6] += stats.defSlash;
            worn[7] += stats.defCrush;
            worn[8] += stats.defMagic;
            worn[9] += stats.defRange;
            worn[10] += stats.meleeStr;
            worn[11] += stats.rangedStr;
            worn[12] += stats.magicDmg;
            worn[13] += stats.prayer;
            if (Double.isNaN(piece.weight)) {
                weightKnown = false;
            } else if (weightKnown) {
                wornWeight += piece.weight;
            }
            if (stats.speed > 0) {
                wornSpeed = stats.speed;
                sawWeaponSpeed = true;
            }
        }
        int[] itemStats = {
            item.attackStab, item.attackSlash, item.attackCrush, item.attackMagic, item.attackRange,
            item.defStab, item.defSlash, item.defCrush, item.defMagic, item.defRange,
            item.meleeStr, item.rangedStr, item.magicDmg, item.prayer
        };
        String[] labels = {
            "Stab atk", "Slash atk", "Crush atk", "Magic atk", "Range atk",
            "Stab def", "Slash def", "Crush def", "Magic def", "Range def",
            "Strength", "Ranged str", "Magic dmg", "Prayer"
        };
        List<Delta> lines = new ArrayList<>();
        for (int i = 0; i < itemStats.length; i++) {
            lines.add(new Delta(labels[i], itemStats[i] - worn[i], false, true));
        }
        if (weightKnown) {
            lines.add(new Delta("Weight", itemWeight - wornWeight, true, true));
        }
        if (includeSpeed && (item.speed > 0 || sawWeaponSpeed)) {
            lines.add(new Delta("Speed", item.speed - wornSpeed, true, true));
        }
        return lines;
    }
}

package com.osr.jei.equipment;

import net.runelite.api.EquipmentInventorySlot;

import java.util.Locale;

/** Wiki slot text and the worn-container index it occupies. */
public enum GearSlot {
    HEAD("Head", EquipmentInventorySlot.HEAD.getSlotIdx()),
    CAPE("Cape", EquipmentInventorySlot.CAPE.getSlotIdx()),
    AMULET("Amulet", EquipmentInventorySlot.AMULET.getSlotIdx()),
    WEAPON("Weapon", EquipmentInventorySlot.WEAPON.getSlotIdx()),
    BODY("Body", EquipmentInventorySlot.BODY.getSlotIdx()),
    SHIELD("Shield", EquipmentInventorySlot.SHIELD.getSlotIdx()),
    LEGS("Legs", EquipmentInventorySlot.LEGS.getSlotIdx()),
    GLOVES("Gloves", EquipmentInventorySlot.GLOVES.getSlotIdx()),
    BOOTS("Boots", EquipmentInventorySlot.BOOTS.getSlotIdx()),
    RING("Ring", EquipmentInventorySlot.RING.getSlotIdx()),
    AMMO("Ammo", EquipmentInventorySlot.AMMO.getSlotIdx());

    private final String label;
    private final int containerIndex;

    GearSlot(String label, int containerIndex) {
        this.label = label;
        this.containerIndex = containerIndex;
    }

    public int containerIndex() {
        return containerIndex;
    }

    @Override
    public String toString() {
        return label;
    }

    public static GearSlot fromWiki(String slot) {
        if (slot == null) {
            return null;
        }
        String key = slot.trim().toLowerCase(Locale.ROOT);
        if (key.equals("2h") || key.startsWith("2h ") || key.contains("two-hand") || key.contains("two hand")) {
            return WEAPON;
        }
        if (key.equals("head") || key.equals("helmet")) {
            return HEAD;
        }
        if (key.equals("cape")) {
            return CAPE;
        }
        if (key.equals("neck") || key.equals("amulet")) {
            return AMULET;
        }
        if (key.equals("weapon")) {
            return WEAPON;
        }
        if (key.equals("body") || key.equals("torso")) {
            return BODY;
        }
        if (key.equals("shield")) {
            return SHIELD;
        }
        if (key.equals("legs")) {
            return LEGS;
        }
        if (key.equals("hands") || key.equals("gloves")) {
            return GLOVES;
        }
        if (key.equals("feet") || key.equals("boots")) {
            return BOOTS;
        }
        if (key.equals("ring") || key.equals("finger")) {
            return RING;
        }
        if (key.equals("ammo") || key.equals("ammunition")) {
            return AMMO;
        }
        return null;
    }

    public static GearSlot fromContainerIndex(int index) {
        for (GearSlot slot : values()) {
            if (slot.containerIndex == index) {
                return slot;
            }
        }
        return null;
    }
}

package com.osr.jei.equipment;

import java.util.Arrays;

/** Canonical item ids in the worn container. Empty slots are {@code -1}. */
public final class WornGear {

    public static final int SLOTS = 14;
    public static final WornGear LOGGED_OUT = new WornGear(false, empty());

    public final boolean loggedIn;
    public final int[] ids;

    public WornGear(boolean loggedIn, int[] ids) {
        this.loggedIn = loggedIn;
        int[] copy = empty();
        if (ids != null) {
            System.arraycopy(ids, 0, copy, 0, Math.min(ids.length, copy.length));
        }
        this.ids = copy;
    }

    public int id(int slot) {
        if (slot < 0 || slot >= ids.length) {
            return -1;
        }
        return ids[slot];
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof WornGear)) {
            return false;
        }
        WornGear that = (WornGear) other;
        return loggedIn == that.loggedIn && Arrays.equals(ids, that.ids);
    }

    @Override
    public int hashCode() {
        return (loggedIn ? 1 : 0) * 31 + Arrays.hashCode(ids);
    }

    private static int[] empty() {
        int[] ids = new int[SLOTS];
        Arrays.fill(ids, -1);
        return ids;
    }
}

