package com.osr.jei.ironman;

import com.osr.jei.model.ShopEntry;
import com.osr.jei.pricing.Alchemy;
import com.osr.jei.pricing.PriceQuote;

/**
 * Price and shop lines. Ironman copy keeps high alch and store prices,
 * and does not frame anything as a Grand Exchange purchase.
 */
public final class TradeCopy {

    public static final String NEUTRAL = "#bebebe";
    public static final String CHEAPER = "#64d264";
    public static final String DEARER = "#dc6464";

    public static final class ShopLine {
        public final String stock;
        public final String price;
        public final String priceColor;
        /** True only when the price colour is a comparison against the GE buy price. */
        public final boolean comparedToGe;

        public ShopLine(String stock, String price, String priceColor, boolean comparedToGe) {
            this.stock = stock;
            this.price = price;
            this.priceColor = priceColor;
            this.comparedToGe = comparedToGe;
        }
    }

    private TradeCopy() {
    }

    /** Prices are requested only when the GE setting is on, ironman or not. */
    public static boolean shouldFetchGePrices(boolean showPrices) {
        return showPrices;
    }

    public static String geLine(boolean ironman, boolean showPrices, PriceQuote quote) {
        if (!showPrices) {
            return "";
        }
        if (quote == null || !quote.known()) {
            return ironman ? "" : "Not on the Grand Exchange.";
        }
        long value = quote.instantBuy > 0 ? quote.instantBuy : quote.mid;
        if (ironman) {
            return String.format("GE reference: %,d gp", value);
        }
        if (quote.instantBuy > 0) {
            return String.format("GE buy: %,d gp", quote.instantBuy);
        }
        return String.format("GE price: %,d gp", quote.mid);
    }

    /**
     * High-alch value. Profit versus a GE buy is only shown for non-iron accounts
     * when both the GE price and the nature-rune price are known.
     */
    public static String alchLine(boolean ironman, Alchemy.Result result) {
        if (result == null) {
            return "";
        }
        if (ironman || result.profit == null) {
            return String.format("High Alch: %,d gp", result.haValue);
        }
        String profit = result.profit >= 0
            ? String.format("+%,d gp", result.profit)
            : String.format("%,d gp", result.profit);
        return String.format("High Alch: %,d gp  (%s)", result.haValue, profit);
    }

    public static ShopLine shop(boolean ironman, ShopEntry shop, long geBuy) {
        String stock = "";
        if (shop.infiniteStock()) {
            stock = " (\u221e)";
        } else if (shop.stock > 0) {
            stock = " (" + String.format("%,d", shop.stock) + ")";
        }
        String unit = shop.isCoins() ? "gp" : shop.currency;
        String price = " \u2014 " + String.format("%,d %s", shop.price, unit);
        if (ironman || !shop.isCoins() || geBuy <= 0 || shop.price <= 0) {
            return new ShopLine(stock, price, NEUTRAL, false);
        }
        String color = shop.price <= geBuy ? CHEAPER : DEARER;
        return new ShopLine(stock, price, color, true);
    }
}

package com.osr.jei.lookup;

import java.util.Map;

/**
 * Resolves a noted, placeholder, or worn item id to the item players search for.
 *
 * <p>The rules match {@code ItemManager.canonicalize}: a note
 * ({@code ItemComposition.getNote() != -1}) becomes {@code getLinkedNoteId()};
 * a placeholder ({@code getPlaceholderTemplateId() != -1}) becomes
 * {@code getPlaceholderId()}; a worn variant can then map to its inventory id.
 * The live lookup still calls {@code itemManager.canonicalize} on the client
 * thread so the worn-item map stays the client's.
 */
public final class CanonicalIds {

    /** Sentinel used by item compositions when a link is absent. */
    public static final int NONE = -1;

    private CanonicalIds() {
    }

    public static int resolve(int itemId, int note, int linkedNoteId, int placeholderTemplateId, int placeholderId) {
        return resolve(itemId, note, linkedNoteId, placeholderTemplateId, placeholderId, null);
    }

    public static int resolve(
        int itemId,
        int note,
        int linkedNoteId,
        int placeholderTemplateId,
        int placeholderId,
        Map<Integer, Integer> wornToInventory
    ) {
        if (itemId < 0) {
            return NONE;
        }
        int resolved = itemId;
        if (note != NONE) {
            resolved = linkedNoteId;
        } else if (placeholderTemplateId != NONE) {
            resolved = placeholderId;
        }
        if (resolved < 0) {
            return itemId;
        }
        if (wornToInventory != null) {
            Integer worn = wornToInventory.get(resolved);
            if (worn != null && worn > 0) {
                return worn;
            }
        }
        return resolved;
    }
}

package com.osr.jei.lookup;

import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;

/**
 * Right-click Item Browser Lookup is offered on ground items and on item
 * examines in the inventory, the bank (including the side inventory and
 * placeholders), the worn-equipment panel, and the equipment-stats interface.
 * Other examines are left alone.
 */
public final class LookupTargets {

    /**
     * Menu option text. The color tag wraps the whole phrase so
     * {@link #alreadyOffered} can match {@code Item Browser Lookup}.
     */
    public static final String MENU_OPTION = "<col=ff9040>Item Browser Lookup</col>";

    private LookupTargets() {
    }

    public static boolean isItemInterface(int interfaceGroup) {
        return interfaceGroup == InterfaceID.INVENTORY
            || interfaceGroup == InterfaceID.BANKMAIN
            || interfaceGroup == InterfaceID.BANKSIDE
            || interfaceGroup == InterfaceID.WORNITEMS
            || interfaceGroup == InterfaceID.EQUIPMENT
            || interfaceGroup == InterfaceID.EQUIPMENT_SIDE;
    }

    public static boolean groundExamine(int actionId) {
        return actionId == MenuAction.EXAMINE_ITEM_GROUND.getId();
    }

    public static boolean widgetExamine(int actionId, String option, int interfaceGroup) {
        if (actionId != MenuAction.CC_OP_LOW_PRIORITY.getId()) {
            return false;
        }
        if (option == null || !"Examine".equals(option.trim())) {
            return false;
        }
        return isItemInterface(interfaceGroup);
    }

    /** True when this menu already has an Item Browser Lookup row. */
    public static boolean alreadyOffered(Iterable<String> options) {
        if (options == null) {
            return false;
        }
        for (String option : options) {
            if (option != null && option.contains("Item Browser Lookup")) {
                return true;
            }
        }
        return false;
    }
}

