package com.osr.jei.model;

/**
 * One row from an item's "Shop locations" table.
 *
 * <p>{@link #stock} is the wiki's default stock, not the restock timer.
 * {@link #UNKNOWN} means the cell was missing. {@link #INFINITE} means the
 * shop stocks the item without a finite cap ({@code ∞} / {@code 10e50}).
 * A real {@code 0} means the shop does not generate the item.
 */
public class ShopEntry {

    public static final int UNKNOWN = -1;
    public static final int INFINITE = Integer.MAX_VALUE;

    /** Display name of the shop (for example "Bob's Brilliant Axes"). */
    public final String shopName;

    /**
     * Price the player pays to buy one unit, in {@link #currency}.
     * {@code 0} is a real free price when {@link #sells} is true.
     */
    public final int price;

    /** Default stock. See the class constants. */
    public final int stock;

    /** {@code gp} for coins, otherwise the wiki currency name such as {@code Tokkul}. */
    public final String currency;

    /** False when the "Price sold at" cell is empty or "not sold" (buy-only rows). */
    public final boolean sells;

    public ShopEntry(String shopName, int price, int stock, String currency, boolean sells) {
        this.shopName = shopName;
        this.price = price;
        this.stock = stock;
        this.currency = currency == null ? "" : currency;
        this.sells = sells;
    }

    /** The shop's default stock is zero, so it never generates this item. */
    public boolean permanentlyOutOfStock() {
        return stock == 0;
    }

    public boolean infiniteStock() {
        return stock == INFINITE;
    }

    public boolean isCoins() {
        return "gp".equals(currency);
    }
}

package com.osr.jei.owned;

import com.osr.jei.lookup.CanonicalIds;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/**
 * Inventory, worn equipment, and bank totals. Notes are stored under the
 * unnoted id. Placeholders are not owned. The bank map is included only
 * after that container has been seen; an unseen bank is not zero.
 */
public final class OwnedItems {

    /**
     * One container slot after the client has resolved notes and worn variants.
     * {@code placeholderTemplateId != -1} means the slot is a bank placeholder.
     */
    public static final class Slot {
        public final int itemId;
        public final int quantity;
        public final int placeholderTemplateId;

        public Slot(int itemId, int quantity, int placeholderTemplateId) {
            this.itemId = itemId;
            this.quantity = quantity;
            this.placeholderTemplateId = placeholderTemplateId;
        }
    }

    /**
     * Counts the player can show. {@code inventoryKnown} is false at the login
     * screen. {@code bankKnown} is false until the bank container exists.
     */
    public static final class Snapshot {
        public static final Snapshot NONE = new Snapshot(false, false, Collections.emptyMap());

        private final boolean inventoryKnown;
        private final boolean bankKnown;
        private final Map<Integer, Long> counts;

        private Snapshot(boolean inventoryKnown, boolean bankKnown, Map<Integer, Long> counts) {
            this.inventoryKnown = inventoryKnown;
            this.bankKnown = bankKnown;
            this.counts = counts;
        }

        public boolean inventoryKnown() {
            return inventoryKnown;
        }

        public boolean bankKnown() {
            return bankKnown;
        }

        /** Owned amount of a canonical id. Zero when that id was not seen. */
        public long count(int itemId) {
            Long value = counts.get(itemId);
            return value == null ? 0L : value;
        }

        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof Snapshot)) {
                return false;
            }
            Snapshot snapshot = (Snapshot) other;
            return inventoryKnown == snapshot.inventoryKnown
                && bankKnown == snapshot.bankKnown
                && counts.equals(snapshot.counts);
        }

        @Override
        public int hashCode() {
            return Objects.hash(inventoryKnown, bankKnown, counts);
        }
    }

    private OwnedItems() {
    }

    /**
     * Sums stacks by id. Non-positive quantities and placeholders are skipped.
     * Callers pass ids that already went through note and worn canonicalization.
     */
    public static Map<Integer, Long> count(Iterable<Slot> slots) {
        Map<Integer, Long> totals = new HashMap<>();
        if (slots == null) {
            return totals;
        }
        for (Slot slot : slots) {
            if (slot == null || slot.itemId < 0 || slot.quantity <= 0) {
                continue;
            }
            if (slot.placeholderTemplateId != CanonicalIds.NONE) {
                continue;
            }
            totals.merge(slot.itemId, (long) slot.quantity, Long::sum);
        }
        return totals;
    }

    /**
     * @param inventoryKnown false when the inventory container does not exist yet
     * @param bankKnown      false when the bank has not been opened this session
     */
    public static Snapshot snapshot(
        Map<Integer, Long> inventory,
        Map<Integer, Long> worn,
        Map<Integer, Long> bank,
        boolean inventoryKnown,
        boolean bankKnown
    ) {
        Map<Integer, Long> totals = new HashMap<>();
        if (inventoryKnown) {
            addAll(totals, inventory);
            addAll(totals, worn);
        }
        if (bankKnown) {
            addAll(totals, bank);
        }
        return new Snapshot(inventoryKnown, bankKnown, Collections.unmodifiableMap(totals));
    }

    /** Items still required. Never negative. */
    public static long stillNeeded(long have, long need) {
        long owned = Math.max(0L, have);
        long required = Math.max(0L, need);
        if (owned >= required) {
            return 0L;
        }
        return required - owned;
    }

    public static boolean shortfall(long have, long need) {
        return stillNeeded(have, need) > 0L;
    }

    private static void addAll(Map<Integer, Long> into, Map<Integer, Long> from) {
        if (from == null) {
            return;
        }
        for (Map.Entry<Integer, Long> entry : from.entrySet()) {
            if (entry.getKey() == null || entry.getValue() == null || entry.getValue() <= 0L) {
                continue;
            }
            into.merge(entry.getKey(), entry.getValue(), Long::sum);
        }
    }
}

package com.osr.jei.owned;

import java.awt.Color;

/**
 * Sidebar copy for owned counts. Until the bank has been checked, the copy
 * names that gap instead of showing a zero or a trailing plus.
 */
public final class OwnedText {

    public static final String SHORT_COLOR = "#dc6464";
    public static final String OK_COLOR = "#96dc96";
    public static final String UNKNOWN_COLOR = "#c8c8c8";

    public static final String BANK_UNKNOWN_TIP =
        "Inventory and worn equipment only. Open the bank once to include it. Bank not checked means those items are not in this count.";

    private OwnedText() {
    }

    public static String header(boolean inventoryKnown, boolean bankKnown, long have) {
        if (!inventoryKnown) {
            return "Owned: log in to count";
        }
        long owned = Math.max(0L, have);
        if (!bankKnown) {
            if (owned <= 0L) {
                return "Owned: bank not checked";
            }
            return String.format("Owned: %,d (bank not checked)", owned);
        }
        return String.format("Owned: %,d", owned);
    }

    /** HTML fragment. The item name stays outside this span. */
    public static String haveNeedHtml(long have, long need, boolean bankKnown) {
        long owned = Math.max(0L, have);
        long required = Math.max(0L, need);
        String color = bankKnown ? color(OwnedItems.shortfall(owned, required)) : UNKNOWN_COLOR;
        return "<font color='" + color + "'>" + haveNeedPlain(owned, required, bankKnown) + "</font>";
    }

    /** Plain have/need text for a tree row. */
    public static String haveNeedPlain(long have, long need, boolean bankKnown) {
        long owned = Math.max(0L, have);
        long required = Math.max(0L, need);
        if (!bankKnown) {
            if (owned <= 0L) {
                return String.format("bank not checked / need %,d", required);
            }
            return String.format("have %,d (bank not checked) / need %,d", owned, required);
        }
        return String.format("have %,d / need %,d", owned, required);
    }

    /** Green or red once the bank is known. Neutral while it has not been checked. */
    public static Color haveNeedColor(long have, long need, boolean bankKnown) {
        if (!bankKnown) {
            return neutral();
        }
        boolean shortOfKnown = OwnedItems.shortfall(Math.max(0L, have), Math.max(0L, need));
        return shortOfKnown ? new Color(0xDC, 0x64, 0x64) : new Color(0x96, 0xDC, 0x96);
    }

    /** HTML fragment for one base-material row. */
    public static String stillNeededHtml(long have, long need, boolean bankKnown) {
        long still = OwnedItems.stillNeeded(have, need);
        String color = bankKnown ? color(still > 0L) : UNKNOWN_COLOR;
        String text = bankKnown
            ? String.format("still needed %,d", still)
            : String.format("still needed %,d (bank not checked)", still);
        return "<font color='" + color + "'>" + text + "</font>";
    }

    private static Color neutral() {
        return new Color(0xC8, 0xC8, 0xC8);
    }

    private static String color(boolean shortOfKnown) {
        return shortOfKnown ? SHORT_COLOR : OK_COLOR;
    }
}

package com.osr.jei.pricing;

/**
 * High-alchemy profit. A missing GE price or nature-rune price never becomes
 * a fabricated profit; only the high-alch value is reported in that case.
 */
public final class Alchemy {

    public static final class Result {
        public final int haValue;
        /** Null when profit cannot be computed honestly. */
        public final Long profit;

        public Result(int haValue, Long profit) {
            this.haValue = haValue;
            this.profit = profit;
        }
    }

    private Alchemy() {
    }

    /**
     * @param haPrice     high-alch value from the game cache; {@code <= 0} means not alchable
     * @param geBuyPrice  what the player would pay on the GE, or {@code <= 0} if unknown
     * @param naturePrice nature rune cost, or {@code <= 0} if unknown
     * @return null when the item has no high-alch value
     */
    public static Result compute(int haPrice, long geBuyPrice, long naturePrice) {
        if (haPrice <= 0) {
            return null;
        }
        if (geBuyPrice <= 0 || naturePrice <= 0) {
            return new Result(haPrice, null);
        }
        return new Result(haPrice, haPrice - geBuyPrice - naturePrice);
    }
}

package com.osr.jei.pricing;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Buy limits from one {@code /mapping} response. Items without a positive
 * {@code limit} are absent, which is not the same as a limit of zero.
 */
public final class BuyLimitSnapshot {

    public static final long TTL_MS = 24L * 60L * 60L * 1000L;

    private final long fetchedAt;
    private final Map<Integer, Integer> limits;

    private BuyLimitSnapshot(long fetchedAt, Map<Integer, Integer> limits) {
        this.fetchedAt = fetchedAt;
        this.limits = limits;
    }

    public static BuyLimitSnapshot empty() {
        return new BuyLimitSnapshot(0L, Collections.emptyMap());
    }

    public long fetchedAt() {
        return fetchedAt;
    }

    public boolean fresh(long nowMs) {
        return fetchedAt > 0L && nowMs - fetchedAt < TTL_MS;
    }

    /** Null when this id was not given a positive limit. */
    public Integer limit(int itemId) {
        return limits.get(itemId);
    }

    public static BuyLimitSnapshot fromMapping(JsonElement root, long nowMs) {
        Map<Integer, Integer> limits = new HashMap<>();
        if (root != null && root.isJsonArray()) {
            for (JsonElement element : root.getAsJsonArray()) {
                if (element == null || !element.isJsonObject()) {
                    continue;
                }
                JsonObject item = element.getAsJsonObject();
                if (!item.has("id") || item.get("id").isJsonNull()) {
                    continue;
                }
                if (!item.has("limit") || item.get("limit").isJsonNull()) {
                    continue;
                }
                try {
                    int id = item.get("id").getAsInt();
                    int limit = item.get("limit").getAsInt();
                    if (id >= 0 && limit > 0) {
                        limits.put(id, limit);
                    }
                } catch (RuntimeException ignored) {
                    // skip a malformed row
                }
            }
        }
        return new BuyLimitSnapshot(nowMs, limits);
    }
}

package com.osr.jei.pricing;

import net.runelite.api.gameval.ItemID;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Grand Exchange convenience fee: 2% of the sell price, rounded down, capped
 * at 5,000,000 coins per item. Items under 50 coins tax to zero because of
 * that rounding. Exempt ids follow the OSRS Wiki "Exempt from tax" list:
 * bonds, every energy-potion dose, the named early-game supplies, games
 * necklace(8), and ring of dueling(8).
 */
public final class GeTax {

    public static final int PERCENT = 2;
    public static final long CAP = 5_000_000L;

    /**
     * Tradeable ids from the wiki list. Energy potions are every dose.
     * Games necklace and ring of dueling are the fully charged items the
     * wiki names. Watering can is the empty can.
     */
    private static final Set<Integer> EXEMPT = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        ItemID.OSRS_BOND,
        ItemID._1DOSE1ENERGY,
        ItemID._2DOSE1ENERGY,
        ItemID._3DOSE1ENERGY,
        ItemID._4DOSE1ENERGY,
        ItemID.BRONZE_ARROW,
        ItemID.BRONZE_DART,
        ItemID.IRON_ARROW,
        ItemID.IRON_DART,
        ItemID.MINDRUNE,
        ItemID.STEEL_ARROW,
        ItemID.STEEL_DART,
        ItemID.BASS,
        ItemID.BREAD,
        ItemID.CAKE,
        ItemID.COOKED_CHICKEN,
        ItemID.COOKED_MEAT,
        ItemID.HERRING,
        ItemID.LOBSTER,
        ItemID.MACKEREL,
        ItemID.MEAT_PIE,
        ItemID.PIKE,
        ItemID.SALMON,
        ItemID.SHRIMP,
        ItemID.TUNA,
        ItemID.POH_TABLET_ARDOUGNETELEPORT,
        ItemID.POH_TABLET_CAMELOTTELEPORT,
        ItemID.POH_TABLET_FORTISTELEPORT,
        ItemID.POH_TABLET_FALADORTELEPORT,
        ItemID.NECKLACE_OF_MINIGAMES_8,
        ItemID.POH_TABLET_KOURENDTELEPORT,
        ItemID.POH_TABLET_LUMBRIDGETELEPORT,
        ItemID.RING_OF_DUELING_8,
        ItemID.POH_TABLET_TELEPORTTOHOUSE,
        ItemID.POH_TABLET_VARROCKTELEPORT,
        ItemID.CHISEL,
        ItemID.TROWEL,
        ItemID.GLASSBLOWINGPIPE,
        ItemID.HAMMER,
        ItemID.NEEDLE,
        ItemID.PESTLE_AND_MORTAR,
        ItemID.RAKE,
        ItemID.POH_SAW,
        ItemID.SECATEURS,
        ItemID.DIBBER,
        ItemID.SHEARS,
        ItemID.SPADE,
        ItemID.WATERING_CAN_0
    )));

    private GeTax() {
    }

    public static boolean exempt(int itemId) {
        return EXEMPT.contains(itemId);
    }

    /** Tax taken from one item sold at {@code sellPrice}. Zero when exempt. */
    public static long tax(long sellPrice, boolean exempt) {
        if (exempt || sellPrice <= 0L) {
            return 0L;
        }
        long raw = sellPrice * PERCENT / 100L;
        if (raw <= 0L) {
            return 0L;
        }
        return Math.min(CAP, raw);
    }

    /**
     * Coins the seller keeps. Null when either instant price is unknown,
     * so a missing side is never turned into a margin.
     */
    public static Long margin(long instantBuy, long instantSell, boolean exempt) {
        if (instantBuy <= 0L || instantSell <= 0L) {
            return null;
        }
        return instantSell - tax(instantSell, exempt) - instantBuy;
    }

    /** Margin times the 4-hour buy limit. Null when either input is missing. */
    public static Long perLimit(Long margin, Integer buyLimit) {
        if (margin == null || buyLimit == null || buyLimit <= 0) {
            return null;
        }
        return margin * buyLimit.longValue();
    }
}

