package com.osr.jei.pricing;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Grand Exchange sell, post-tax margin, buy limit, and profit across one
 * 4-hour limit. {@link #text} is the single sentence kept for callers that
 * still want it. {@link #lines} is the same information split into short
 * rows so a narrow sidebar can show each figure on its own line.
 * Ironman copy is explicitly a reference.
 */
public final class MarketQuote {

    /** One short row. An empty key is a full-width note, such as "Reference only". */
    public static final class Line {
        public final String key;
        public final String value;
        /** {@code 1} profit, {@code -1} loss, {@code 0} neutral. */
        public final int tone;

        public Line(String key, String value, int tone) {
            this.key = key == null ? "" : key;
            this.value = value == null ? "" : value;
            this.tone = tone;
        }
    }

    public final String text;
    /** {@code 1} profit, {@code -1} loss, {@code 0} when margin is unknown. */
    public final int marginSign;
    public final List<Line> lines;

    private MarketQuote(String text, int marginSign, List<Line> lines) {
        this.text = text;
        this.marginSign = marginSign;
        this.lines = lines == null ? Collections.emptyList() : Collections.unmodifiableList(lines);
    }

    public static MarketQuote describe(
        boolean ironman,
        int itemId,
        PriceQuote quote,
        Integer buyLimit,
        boolean limitsReady
    ) {
        return describe(ironman, itemId, quote, buyLimit, limitsReady, false);
    }

    public static MarketQuote describe(
        boolean ironman,
        int itemId,
        PriceQuote quote,
        Integer buyLimit,
        boolean limitsReady,
        boolean limitsUnavailable
    ) {
        boolean exempt = GeTax.exempt(itemId);
        boolean priced = quote != null && quote.instantBuy > 0L && quote.instantSell > 0L;
        Long margin = priced ? GeTax.margin(quote.instantBuy, quote.instantSell, exempt) : null;

        StringBuilder body = new StringBuilder();
        List<Line> lines = new ArrayList<>();
        if (priced && margin != null) {
            String sell = String.format("%,d gp", quote.instantSell);
            body.append("Instant sell: ").append(sell);
            lines.add(new Line("Instant sell", sell, 0));
            body.append(" \u00b7 ");
            int tone = Long.signum(margin);
            if (exempt) {
                String marginValue = String.format("%,d gp, tax exempt", margin);
                body.append("margin ").append(marginValue);
                lines.add(new Line("Margin", marginValue, tone));
            } else {
                String marginValue = String.format("%,d gp after tax", margin);
                body.append("margin ").append(marginValue);
                lines.add(new Line("Margin", marginValue, tone));
            }
        }
        appendLimit(body, lines, buyLimit, limitsReady, limitsUnavailable, margin);
        if (body.length() == 0) {
            return new MarketQuote("", 0, Collections.emptyList());
        }
        int sign = margin == null ? 0 : Long.signum(margin);
        String text = body.toString();
        if (ironman) {
            text = "Reference only \u00b7 " + text;
            lines.add(0, new Line("", "Reference only", 0));
        }
        return new MarketQuote(text, sign, lines);
    }

    private static void appendLimit(
        StringBuilder body,
        List<Line> lines,
        Integer buyLimit,
        boolean limitsReady,
        boolean limitsUnavailable,
        Long margin
    ) {
        String limitText;
        String limitKey;
        String limitValue;
        if (!limitsReady && limitsUnavailable) {
            limitText = "buy limits unavailable";
            limitKey = "Buy limit";
            limitValue = "unavailable";
        } else if (!limitsReady) {
            limitText = "buy limit loading";
            limitKey = "Buy limit";
            limitValue = "loading";
        } else if (buyLimit == null) {
            limitText = "buy limit not listed";
            limitKey = "Buy limit";
            limitValue = "not listed";
        } else {
            limitText = String.format("limit %,d", buyLimit);
            limitKey = "Limit";
            limitValue = String.format("%,d", buyLimit);
        }
        if (body.length() > 0) {
            body.append(" \u00b7 ");
        }
        body.append(limitText);
        lines.add(new Line(limitKey, limitValue, 0));
        Long perLimit = GeTax.perLimit(margin, buyLimit);
        if (perLimit != null) {
            String perValue = String.format("%,d gp", perLimit);
            body.append(" \u00b7 per 4h ").append(perValue);
            lines.add(new Line("Per 4h", perValue, Long.signum(perLimit)));
        }
    }
}

package com.osr.jei.pricing;

/**
 * Age text for a GE quote. Shown once the data is at least as old as the
 * shared price snapshot's TTL.
 */
public final class PriceAge {

    public static final String UNAVAILABLE = "Grand Exchange prices are unavailable.";

    private PriceAge() {
    }

    /**
     * {@code "12 min old"} when the quote (or, if it has no trade time, the
     * snapshot) is older than {@link PriceSnapshot#TTL_MS}. Empty otherwise.
     */
    public static String suffix(PriceQuote quote, long snapshotFetchedAtMs, long nowMs) {
        long dataMs = 0L;
        if (quote != null && quote.newestTimeSeconds() > 0L) {
            dataMs = quote.newestTimeSeconds() * 1000L;
        } else if (snapshotFetchedAtMs > 0L) {
            dataMs = snapshotFetchedAtMs;
        }
        if (dataMs <= 0L || nowMs < dataMs) {
            return "";
        }
        long age = nowMs - dataMs;
        if (age < PriceSnapshot.TTL_MS) {
            return "";
        }
        return format(age) + " old";
    }

    static String format(long ageMs) {
        long minutes = ageMs / 60_000L;
        if (minutes < 1L) {
            return "under a minute";
        }
        if (minutes < 90L) {
            return minutes + " min";
        }
        long hours = ageMs / 3_600_000L;
        if (hours < 48L) {
            return hours + " hr";
        }
        long days = ageMs / 86_400_000L;
        if (days < 1L) {
            days = 1L;
        }
        return days == 1L ? "1 day" : days + " days";
    }
}

package com.osr.jei.pricing;

/**
 * One item's price taken from the shared {@code /latest} snapshot.
 * A failed refresh keeps the previous snapshot and marks it stale.
 */
public final class PriceLookup {

    public static final PriceLookup UNAVAILABLE = new PriceLookup(PriceQuote.MISSING, 0L, true, false);
    /** GE prices are turned off. This is not an error. */
    public static final PriceLookup HIDDEN = new PriceLookup(PriceQuote.MISSING, 0L, false, false);

    public final PriceQuote quote;
    public final long fetchedAtMs;
    public final boolean unavailable;
    public final boolean stale;

    public PriceLookup(PriceQuote quote, long fetchedAtMs, boolean unavailable, boolean stale) {
        this.quote = quote == null ? PriceQuote.MISSING : quote;
        this.fetchedAtMs = fetchedAtMs;
        this.unavailable = unavailable;
        this.stale = stale;
    }

    public static PriceLookup from(PriceSnapshot snapshot, boolean failed, int itemId, long nowMs) {
        if (snapshot == null || snapshot.fetchedAt() <= 0L) {
            return UNAVAILABLE;
        }
        boolean stale = failed || !snapshot.fresh(nowMs);
        return new PriceLookup(snapshot.quote(itemId), snapshot.fetchedAt(), false, stale);
    }
}

package com.osr.jei.pricing;

import com.google.gson.JsonObject;

/**
 * One item's latest GE quote from the OSRS Wiki prices API.
 * {@code -1} means that side was missing.
 */
public final class PriceQuote {

    public static final PriceQuote MISSING = new PriceQuote(-1, -1, -1);

    /** Instant-buy price ({@code high}). */
    public final long instantBuy;
    /** Instant-sell price ({@code low}). */
    public final long instantSell;
    /** Midpoint when both sides exist, otherwise whichever side is present. */
    public final long mid;
    /** Unix seconds of the latest instant-buy trade, or {@code 0} when absent. */
    public final long highTime;
    /** Unix seconds of the latest instant-sell trade, or {@code 0} when absent. */
    public final long lowTime;

    public PriceQuote(long instantBuy, long instantSell, long mid) {
        this(instantBuy, instantSell, mid, 0L, 0L);
    }

    public PriceQuote(long instantBuy, long instantSell, long mid, long highTime, long lowTime) {
        this.instantBuy = instantBuy;
        this.instantSell = instantSell;
        this.mid = mid;
        this.highTime = highTime;
        this.lowTime = lowTime;
    }

    /** The newer trade time, in unix seconds, or {@code 0} when neither is known. */
    public long newestTimeSeconds() {
        return Math.max(highTime, lowTime);
    }

    public boolean known() {
        return instantBuy > 0 || instantSell > 0 || mid > 0;
    }

    /** Price a player pays to buy immediately, falling back to the mid. */
    public long buyPrice() {
        if (instantBuy > 0) {
            return instantBuy;
        }
        return mid > 0 ? mid : -1;
    }

    public static PriceQuote fromItem(JsonObject entry) {
        if (entry == null) {
            return MISSING;
        }
        long high = entry.has("high") && !entry.get("high").isJsonNull()
            ? entry.get("high").getAsLong() : -1;
        long low = entry.has("low") && !entry.get("low").isJsonNull()
            ? entry.get("low").getAsLong() : -1;
        long mid;
        if (high > 0 && low > 0) {
            mid = (high + low) / 2;
        } else if (high > 0) {
            mid = high;
        } else {
            mid = low;
        }
        return new PriceQuote(high, low, mid, seconds(entry, "highTime"), seconds(entry, "lowTime"));
    }

    private static long seconds(JsonObject entry, String field) {
        if (entry == null || !entry.has(field) || entry.get(field).isJsonNull()) {
            return 0L;
        }
        try {
            return entry.get(field).getAsLong();
        } catch (RuntimeException ignored) {
            return 0L;
        }
    }

    public static PriceQuote fromRoot(JsonObject root, int itemId) {
        if (root == null) {
            return MISSING;
        }
        JsonObject data = root.getAsJsonObject("data");
        if (data == null || !data.has(String.valueOf(itemId))) {
            return MISSING;
        }
        return fromItem(data.getAsJsonObject(String.valueOf(itemId)));
    }
}

package com.osr.jei.pricing;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * One bulk {@code /latest} response. Items absent from the map have no GE price
 * for the life of this snapshot, so they are not requested again until it expires.
 */
public final class PriceSnapshot {

    public static final long TTL_MS = 7 * 60 * 1000L;

    private final long fetchedAt;
    private final Map<Integer, PriceQuote> quotes;

    public PriceSnapshot(long fetchedAt, Map<Integer, PriceQuote> quotes) {
        this.fetchedAt = fetchedAt;
        this.quotes = quotes;
    }

    public static PriceSnapshot empty() {
        return new PriceSnapshot(0, Collections.emptyMap());
    }

    public long fetchedAt() {
        return fetchedAt;
    }

    public boolean fresh(long nowMs) {
        return fetchedAt > 0 && nowMs - fetchedAt < TTL_MS;
    }

    public PriceQuote quote(int itemId) {
        PriceQuote quote = quotes.get(itemId);
        return quote == null ? PriceQuote.MISSING : quote;
    }

    public static PriceSnapshot fromRoot(JsonObject root, long nowMs) {
        Map<Integer, PriceQuote> quotes = new HashMap<>();
        if (root != null && root.has("data") && root.get("data").isJsonObject()) {
            JsonObject data = root.getAsJsonObject("data");
            for (Map.Entry<String, JsonElement> entry : data.entrySet()) {
                if (!entry.getValue().isJsonObject()) {
                    continue;
                }
                try {
                    int id = Integer.parseInt(entry.getKey());
                    quotes.put(id, PriceQuote.fromItem(entry.getValue().getAsJsonObject()));
                } catch (NumberFormatException ignored) {
                    // skip unexpected keys
                }
            }
        }
        return new PriceSnapshot(nowMs, quotes);
    }
}

