package com.osr.jei.requirements;

import com.osr.jei.model.RecipeInfo;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Caches real skill levels and the quest states the open item actually names.
 * Levels are read with {@code getRealSkillLevel} on the client thread and refreshed
 * from {@code StatChanged}. Quest states use {@code Quest.getState} on the client
 * thread, only for names that map exactly, and only while one is on screen.
 */
@Singleton
public class PlayerProgress {

    public interface Listener {
        void onSnapshot(ProgressSnapshot snapshot);
    }

    private final Client client;
    private final ClientThread clientThread;
    private final Map<String, Quest> questsByKey;
    private final Map<String, String> officialByKey;

    private volatile ProgressSnapshot snapshot = ProgressSnapshot.LOGGED_OUT;
    private volatile Listener listener;
    private volatile Set<String> watched = Collections.emptySet();
    private static final long QUEST_REFRESH_MS = 2000L;

    private volatile boolean questDirty;
    private final AtomicBoolean questReadQueued = new AtomicBoolean();
    private long lastQuestReadMs;

    @Inject
    public PlayerProgress(Client client, ClientThread clientThread) {
        this.client = client;
        this.clientThread = clientThread;
        this.questsByKey = indexQuests();
        Map<String, String> names = new HashMap<>();
        for (Map.Entry<String, Quest> entry : questsByKey.entrySet()) {
            names.put(entry.getKey(), entry.getValue().getName());
        }
        this.officialByKey = names;
    }

    public ProgressSnapshot snapshot() {
        return snapshot;
    }

    public Mark skill(String name, int level, boolean judge) {
        return RequirementJudge.skill(name, level, snapshot, judge);
    }

    public Mark quest(String name, boolean judge) {
        return RequirementJudge.quest(name, officialByKey, snapshot, judge);
    }

    public Mark recipe(RecipeInfo recipe, boolean judge) {
        return RequirementJudge.recipe(recipe, snapshot, judge);
    }

    public void setListener(Listener listener) {
        this.listener = listener;
    }

    /** Names as written on the wiki. Unknown names are not queried and stay neutral. */
    public void watch(Collection<String> wikiNames) {
        Set<String> next = new LinkedHashSet<>();
        if (wikiNames != null) {
            for (String name : wikiNames) {
                String official = QuestNames.canonical(officialByKey, name);
                if (official != null) {
                    next.add(QuestNames.normalize(official));
                }
            }
        }
        boolean changed = !next.equals(watched);
        watched = Collections.unmodifiableSet(next);
        if (changed) {
            questDirty = true;
        }
        if (questDirty && !watched.isEmpty()) {
            scheduleQuestRead();
        }
    }

    /** Client-thread entry from {@code StatChanged} and login changes. */
    public void refreshSkills() {
        if (!client.isClientThread()) {
            clientThread.invokeLater(this::refreshSkills);
            return;
        }
        boolean loggedIn = loggedIn();
        Map<String, Integer> skills = loggedIn ? readLevels() : Collections.<String, Integer>emptyMap();
        Map<String, QuestProgress> quests = loggedIn ? snapshot.quests : Collections.<String, QuestProgress>emptyMap();
        publish(new ProgressSnapshot(loggedIn, skills, quests));
        if (loggedIn) {
            readQuestsIfDirty();
        }
    }

    /**
     * A varbit changed. The flag is drained on the next game tick so
     * {@code Quest.getState} is not called from inside the varbit event.
     */
    public void markQuestsDirty() {
        if (watched.isEmpty()) {
            return;
        }
        questDirty = true;
    }

    /**
     * Drained from the game tick. A new watched set still reads immediately via
     * {@link #watch}; this path only picks up later varbit changes, and at most
     * once every two seconds so {@code Quest.getState} is not run every tick.
     */
    public void readQuestsIfDirty() {
        if (!questDirty || watched.isEmpty()) {
            return;
        }
        if (System.currentTimeMillis() - lastQuestReadMs < QUEST_REFRESH_MS) {
            return;
        }
        scheduleQuestRead();
    }

    private void scheduleQuestRead() {
        if (!questReadQueued.compareAndSet(false, true)) {
            return;
        }
        clientThread.invokeLater(this::readQuests);
    }

    private void readQuests() {
        questReadQueued.set(false);
        if (!client.isClientThread()) {
            scheduleQuestRead();
            return;
        }
        if (!questDirty || watched.isEmpty()) {
            return;
        }
        if (!loggedIn()) {
            questDirty = false;
            publish(new ProgressSnapshot(false, Collections.<String, Integer>emptyMap(), Collections.<String, QuestProgress>emptyMap()));
            return;
        }
        questDirty = false;
        lastQuestReadMs = System.currentTimeMillis();
        Map<String, QuestProgress> states = new LinkedHashMap<>();
        for (String key : watched) {
            Quest quest = questsByKey.get(key);
            if (quest == null) {
                continue;
            }
            try {
                states.put(key, fromState(quest.getState(client)));
            } catch (RuntimeException ignored) {
                // Leave it absent so the row stays neutral rather than met.
            }
        }
        Map<String, Integer> skills = snapshot.loggedIn ? snapshot.skills : readLevels();
        publish(new ProgressSnapshot(true, skills, states));
    }

    private void publish(ProgressSnapshot next) {
        if (next.equals(snapshot)) {
            return;
        }
        snapshot = next;
        Listener current = listener;
        if (current != null) {
            current.onSnapshot(next);
        }
    }

    private Map<String, Integer> readLevels() {
        Map<String, Integer> levels = new LinkedHashMap<>();
        for (Skill skill : Skill.values()) {
            if (skill == null || skill.getName() == null) {
                continue;
            }
            try {
                levels.put(skill.getName(), client.getRealSkillLevel(skill));
            } catch (RuntimeException ignored) {
                // One unreadable skill stays neutral.
            }
        }
        return levels;
    }

    private boolean loggedIn() {
        try {
            return client.getGameState() == GameState.LOGGED_IN;
        } catch (RuntimeException ex) {
            return false;
        }
    }

    private static Map<String, Quest> indexQuests() {
        Map<String, Quest> unique = new HashMap<>();
        Set<String> ambiguous = new java.util.HashSet<>();
        for (Quest quest : Quest.values()) {
            if (quest == null || quest.getName() == null) {
                continue;
            }
            String key = QuestNames.normalize(quest.getName());
            if (key.isEmpty()) {
                continue;
            }
            if (unique.containsKey(key) || ambiguous.contains(key)) {
                unique.remove(key);
                ambiguous.add(key);
            } else {
                unique.put(key, quest);
            }
        }
        return unique;
    }

    private static QuestProgress fromState(QuestState state) {
        if (state == QuestState.FINISHED) {
            return QuestProgress.FINISHED;
        }
        if (state == QuestState.IN_PROGRESS) {
            return QuestProgress.IN_PROGRESS;
        }
        return QuestProgress.NOT_STARTED;
    }
}

package com.osr.jei.requirements;

import java.util.Collections;
import java.util.Map;

/**
 * Real skill levels and quest states captured on the client thread.
 * An empty logged-out snapshot carries no judgment.
 */
public final class ProgressSnapshot {

    public static final ProgressSnapshot LOGGED_OUT = new ProgressSnapshot(
        false,
        Collections.<String, Integer>emptyMap(),
        Collections.<String, QuestProgress>emptyMap()
    );

    public final boolean loggedIn;
    /** Canonical skill name to the real level. */
    public final Map<String, Integer> skills;
    /** Normalized official quest name to completion. */
    public final Map<String, QuestProgress> quests;

    public ProgressSnapshot(boolean loggedIn, Map<String, Integer> skills, Map<String, QuestProgress> quests) {
        this.loggedIn = loggedIn;
        this.skills = skills == null ? Collections.<String, Integer>emptyMap() : Collections.unmodifiableMap(skills);
        this.quests = quests == null ? Collections.<String, QuestProgress>emptyMap() : Collections.unmodifiableMap(quests);
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof ProgressSnapshot)) {
            return false;
        }
        ProgressSnapshot that = (ProgressSnapshot) other;
        return loggedIn == that.loggedIn && skills.equals(that.skills) && quests.equals(that.quests);
    }

    @Override
    public int hashCode() {
        int result = loggedIn ? 1 : 0;
        result = 31 * result + skills.hashCode();
        result = 31 * result + quests.hashCode();
        return result;
    }
}

package com.osr.jei.requirements;

import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Exact quest-name matching. A wiki name that is not an official quest name,
 * or that matches more than one, is unknown and must not be treated as complete.
 */
public final class QuestNames {

    private QuestNames() {
    }

    /**
     * Normalized name to the official display name. Ambiguous keys are omitted.
     */
    public static Map<String, String> index(Collection<String> officialNames) {
        if (officialNames == null || officialNames.isEmpty()) {
            return Collections.emptyMap();
        }
        Map<String, String> unique = new HashMap<>();
        Set<String> ambiguous = new HashSet<>();
        for (String name : officialNames) {
            String key = normalize(name);
            if (key.isEmpty()) {
                continue;
            }
            if (unique.containsKey(key) || ambiguous.contains(key)) {
                unique.remove(key);
                ambiguous.add(key);
            } else {
                unique.put(key, name);
            }
        }
        return unique;
    }

    /** Official display name, or null when {@code wikiName} is unknown or ambiguous. */
    public static String canonical(Map<String, String> index, String wikiName) {
        if (index == null || wikiName == null) {
            return null;
        }
        return index.get(normalize(wikiName));
    }

    public static String normalize(String raw) {
        if (raw == null) {
            return "";
        }
        String text = raw.toLowerCase(Locale.ROOT)
            .replace('&', ' ')
            .replace('/', ' ')
            .replace('-', ' ')
            .replace('\u2013', ' ')
            .replace('\u2014', ' ');
        text = text.replaceAll("[^a-z0-9 ]", "");
        text = text.replaceAll("\\s+", " ").trim();
        if (text.endsWith(" quest")) {
            text = text.substring(0, text.length() - " quest".length()).trim();
        }
        return text;
    }
}

package com.osr.jei.requirements;

/** Quest completion as read from {@code Quest.getState}. Only {@link #FINISHED} meets a requirement. */
public enum QuestProgress {
    NOT_STARTED,
    IN_PROGRESS,
    FINISHED
}

package com.osr.jei.requirements;

import com.osr.jei.model.RecipeInfo;

import java.util.Map;

/** Compares parsed requirements with a player snapshot. Unknown names are neutral, never met. */
public final class RequirementJudge {

    private RequirementJudge() {
    }

    public static Mark skill(String skillName, int level, ProgressSnapshot snapshot, boolean judge) {
        if (skillName == null || skillName.isEmpty() || level <= 0) {
            return Mark.MET;
        }
        if (!judge || snapshot == null || !snapshot.loggedIn) {
            return Mark.NEUTRAL;
        }
        String canonical = SkillNames.canonical(skillName);
        if (canonical == null) {
            return Mark.NEUTRAL;
        }
        Integer have = snapshot.skills.get(canonical);
        if (have == null) {
            return Mark.NEUTRAL;
        }
        return have >= level ? Mark.MET : Mark.UNMET;
    }

    public static Mark quest(String wikiName, Map<String, String> questIndex, ProgressSnapshot snapshot, boolean judge) {
        if (wikiName == null || wikiName.isEmpty()) {
            return Mark.MET;
        }
        if (!judge || snapshot == null || !snapshot.loggedIn) {
            return Mark.NEUTRAL;
        }
        String official = QuestNames.canonical(questIndex, wikiName);
        if (official == null) {
            return Mark.NEUTRAL;
        }
        QuestProgress state = snapshot.quests.get(QuestNames.normalize(official));
        if (state == null) {
            return Mark.NEUTRAL;
        }
        return state == QuestProgress.FINISHED ? Mark.MET : Mark.UNMET;
    }

    public static Mark recipe(RecipeInfo recipe, ProgressSnapshot snapshot, boolean judge) {
        if (recipe == null) {
            return Mark.NEUTRAL;
        }
        Mark mark = Mark.MET;
        boolean any = false;
        if (recipe.skill != null && !recipe.skill.isEmpty() && recipe.level > 0) {
            any = true;
            mark = Mark.worst(mark, skill(recipe.skill, recipe.level, snapshot, judge));
        }
        if (recipe.skill2 != null && !recipe.skill2.isEmpty() && recipe.level2 > 0) {
            any = true;
            mark = Mark.worst(mark, skill(recipe.skill2, recipe.level2, snapshot, judge));
        }
        return any ? mark : Mark.NEUTRAL;
    }

    /** HTML prefix for a marker. Empty when the requirement is not judged. */
    public static String htmlPrefix(Mark mark) {
        if (mark == Mark.MET) {
            return "<font color='#64d264'>&#10003;</font> ";
        }
        if (mark == Mark.UNMET) {
            return "<font color='#dc6464'>&#10007;</font> ";
        }
        return "";
    }
}

package com.osr.jei.requirements;

import com.osr.jei.wiki.WikiText;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads skill and quest requirements that are already in an item page's wikitext.
 * The lede, a Requirements section, and the text next to {@code {{Infobox Bonuses}}
 * are the only windows. Recipe blocks are skipped so a smithing level is not
 * treated as a wield requirement.
 */
public final class RequirementParser {

    private static final Pattern WIKILINK_TARGET = Pattern.compile("\\[\\[([^|\\]]+)(?:\\|[^\\]]*)?\\]\\]");
    private static final Pattern SCP = Pattern.compile("\\{\\{\\s*(?:SCP|Skillreq)\\s*\\|\\s*([A-Za-z ]+?)\\s*\\|\\s*(\\d{1,2})\\b");
    private static final Pattern REQUIREMENTS_HEADING = Pattern.compile("(?m)^==+\\s*Requirements?\\s*==+\\s*$");
    private static final Pattern NEXT_HEADING = Pattern.compile("(?m)^==+");
    private static final Pattern COMPLETED = Pattern.compile("(?i)\\bcompleted the ([A-Za-z0-9][^.]{1,70}?) quest\\b");
    private static final Pattern COMPLETION = Pattern.compile("(?i)\\bcompletion of (?:the )?([A-Za-z0-9][^.]{1,70}?)(?=\\s+is required|\\s+quest\\b|[.])");
    private static final Pattern NEGATED = Pattern.compile("(?i)\\bno particular\\b|\\bno\\b.{0,40}\\brequirement\\b|\\bdoes not require\\b|\\bcannot be made\\b");

    private static final String[] SKILL_WORDS = {
        "Attack", "Strength", "Defence", "Defense", "Ranged", "Range", "Prayer", "Magic",
        "Hitpoints", "Constitution", "Cooking", "Woodcutting", "Fletching", "Fishing",
        "Firemaking", "Crafting", "Smithing", "Mining", "Herblore", "Agility", "Thieving",
        "Slayer", "Farming", "Runecrafting", "Runecraft", "Hunter", "Construction", "Sailing"
    };

    private static final Pattern LEVEL_OF;
    private static final Pattern LEVEL_NUM;
    private static final Pattern NUM_SKILL;

    static {
        String alt = String.join("|", SKILL_WORDS);
        LEVEL_OF = Pattern.compile("(?i)\\b(" + alt + ")\\s+level\\s+of\\s+(\\d{1,2})\\b");
        LEVEL_NUM = Pattern.compile("(?i)\\blevel\\s+(\\d{1,2})\\s+(" + alt + ")\\b");
        NUM_SKILL = Pattern.compile("(?i)\\b(\\d{1,2})\\s+(" + alt + ")\\b");
    }

    private RequirementParser() {
    }

    public static ItemRequirements parse(String wikitext) {
        if (wikitext == null || wikitext.isEmpty()) {
            return ItemRequirements.NONE;
        }
        Map<String, Integer> skills = new LinkedHashMap<>();
        Map<String, String> quests = new LinkedHashMap<>();
        readInfoboxQuest(wikitext, quests);
        for (String window : windows(wikitext)) {
            readWindow(window, skills, quests);
        }
        if (skills.isEmpty() && quests.isEmpty()) {
            return ItemRequirements.NONE;
        }
        List<ItemRequirements.SkillNeed> skillList = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : skills.entrySet()) {
            skillList.add(new ItemRequirements.SkillNeed(entry.getKey(), entry.getValue()));
        }
        return new ItemRequirements(skillList, new ArrayList<>(quests.values()));
    }

    private static void readInfoboxQuest(String wikitext, Map<String, String> quests) {
        List<Integer> hits = WikiText.findTemplates(wikitext, "infobox item");
        if (hits.isEmpty()) {
            return;
        }
        String block = WikiText.extractTemplateBlock(wikitext, hits.get(0));
        if (block == null) {
            return;
        }
        String raw = WikiText.parseParams(block).get("quest");
        if (raw == null || raw.trim().isEmpty() || isYesNo(raw)) {
            return;
        }
        Matcher links = WIKILINK_TARGET.matcher(raw);
        boolean any = false;
        while (links.find()) {
            addQuest(quests, links.group(1));
            any = true;
        }
        if (!any) {
            addQuest(quests, WikiText.clean(raw));
        }
    }

    private static List<String> windows(String wikitext) {
        List<String> windows = new ArrayList<>();
        int ledeEnd = headingAt(wikitext, 0);
        windows.add(ledeEnd < 0 ? wikitext : wikitext.substring(0, ledeEnd));
        Matcher requirements = REQUIREMENTS_HEADING.matcher(wikitext);
        while (requirements.find()) {
            int from = requirements.end();
            int to = headingAt(wikitext, from);
            windows.add(to < 0 ? wikitext.substring(from) : wikitext.substring(from, to));
        }
        for (int start : WikiText.findTemplates(wikitext, "infobox bonuses")) {
            String block = WikiText.extractTemplateBlock(wikitext, start);
            if (block == null) {
                continue;
            }
            int from = start + block.length();
            int to = headingAt(wikitext, from);
            int end = to < 0 ? wikitext.length() : to;
            if (end - from > 600) {
                end = from + 600;
            }
            if (from < end) {
                windows.add(wikitext.substring(from, end));
            }
        }
        return windows;
    }

    private static int headingAt(String text, int from) {
        Matcher matcher = NEXT_HEADING.matcher(text);
        if (from > 0) {
            matcher.region(from, text.length());
        }
        return matcher.find() ? matcher.start() : -1;
    }

    private static void readWindow(String window, Map<String, Integer> skills, Map<String, String> quests) {
        String stripped = removeBlocks(window, "recipe");
        stripped = removeBlocks(stripped, "infobox");
        Matcher scp = SCP.matcher(stripped);
        while (scp.find()) {
            addSkill(skills, scp.group(1), parseLevel(scp.group(2)));
        }
        stripped = removeAllTemplates(stripped);
        stripped = linksToTargets(stripped);
        stripped = stripped.replace("'''", "").replace("''", "");
        String[] sentences = stripped.split("(?<=[.!?])\\s+");
        for (String sentence : sentences) {
            if (sentence.trim().isEmpty() || NEGATED.matcher(sentence).find()) {
                continue;
            }
            if (!mentionsWield(sentence)) {
                continue;
            }
            String usable = sentence.replaceAll("(?i),\\s+which\\s+requires?\\b[^.]*", "");
            if (usable.toLowerCase(Locale.ROOT).contains("only if")) {
                continue;
            }
            collectSkills(usable, skills);
            collectQuests(usable, quests);
        }
    }

    private static boolean mentionsWield(String sentence) {
        String lower = sentence.toLowerCase(Locale.ROOT);
        return lower.contains("wield") || lower.contains("equip");
    }

    private static void collectSkills(String sentence, Map<String, Integer> skills) {
        Matcher levelOf = LEVEL_OF.matcher(sentence);
        while (levelOf.find()) {
            addSkill(skills, levelOf.group(1), parseLevel(levelOf.group(2)));
        }
        Matcher levelNum = LEVEL_NUM.matcher(sentence);
        while (levelNum.find()) {
            addSkill(skills, levelNum.group(2), parseLevel(levelNum.group(1)));
        }
        Matcher numSkill = NUM_SKILL.matcher(sentence);
        while (numSkill.find()) {
            addSkill(skills, numSkill.group(2), parseLevel(numSkill.group(1)));
        }
    }

    private static void collectQuests(String sentence, Map<String, String> quests) {
        Matcher completed = COMPLETED.matcher(sentence);
        while (completed.find()) {
            addQuest(quests, completed.group(1));
        }
        Matcher completion = COMPLETION.matcher(sentence);
        while (completion.find()) {
            addQuest(quests, completion.group(1));
        }
    }

    private static void addSkill(Map<String, Integer> skills, String raw, int level) {
        if (level < 1 || level > 99) {
            return;
        }
        String canonical = SkillNames.canonical(raw);
        if (canonical == null) {
            return;
        }
        Integer have = skills.get(canonical);
        if (have == null || level > have) {
            skills.put(canonical, level);
        }
    }

    private static void addQuest(Map<String, String> quests, String raw) {
        if (raw == null) {
            return;
        }
        String name = raw.replaceAll("\\s+", " ").trim();
        name = name.replaceAll("(?i)\\s+quest$", "").trim();
        if (name.isEmpty() || isYesNo(name)) {
            return;
        }
        String key = QuestNames.normalize(name);
        if (key.isEmpty() || quests.containsKey(key)) {
            return;
        }
        quests.put(key, name);
    }

    private static boolean isYesNo(String raw) {
        String plain = WikiText.clean(raw).trim();
        return plain.matches("(?i)no|yes|none|n/a|na");
    }

    private static int parseLevel(String raw) {
        try {
            return Integer.parseInt(raw.trim());
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    private static String linksToTargets(String text) {
        Matcher matcher = WIKILINK_TARGET.matcher(text);
        StringBuffer buffer = new StringBuffer();
        while (matcher.find()) {
            matcher.appendReplacement(buffer, Matcher.quoteReplacement(matcher.group(1).trim()));
        }
        matcher.appendTail(buffer);
        return buffer.toString();
    }

    private static String removeBlocks(String text, String templateName) {
        String current = text;
        while (true) {
            List<Integer> hits = WikiText.findTemplates(current, templateName);
            if (hits.isEmpty()) {
                return current;
            }
            int start = hits.get(0);
            String block = WikiText.extractTemplateBlock(current, start);
            if (block == null) {
                return current;
            }
            current = current.substring(0, start) + current.substring(start + block.length());
        }
    }

    private static String removeAllTemplates(String text) {
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < text.length()) {
            if (i + 1 < text.length() && text.charAt(i) == '{' && text.charAt(i + 1) == '{') {
                String block = WikiText.extractTemplateBlock(text, i);
                if (block == null) {
                    out.append(text.charAt(i));
                    i++;
                } else {
                    i += block.length();
                }
            } else {
                out.append(text.charAt(i));
                i++;
            }
        }
        return out.toString();
    }
}

package com.osr.jei.requirements;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Canonical skill names, matching {@code Skill.getName()} in the client.
 * Unknown names stay unknown so a requirement is never marked met by a guess.
 */
public final class SkillNames {

    private static final Map<String, String> CANONICAL;

    static {
        Map<String, String> map = new HashMap<>();
        String[] names = {
            "Attack", "Strength", "Defence", "Hitpoints", "Ranged", "Prayer", "Magic",
            "Cooking", "Woodcutting", "Fletching", "Fishing", "Firemaking", "Crafting",
            "Smithing", "Mining", "Herblore", "Agility", "Thieving", "Slayer", "Farming",
            "Runecraft", "Hunter", "Construction", "Sailing"
        };
        for (String name : names) {
            map.put(normalize(name), name);
        }
        map.put(normalize("Defense"), "Defence");
        map.put(normalize("Range"), "Ranged");
        map.put(normalize("Constitution"), "Hitpoints");
        map.put(normalize("Runecrafting"), "Runecraft");
        map.put(normalize("HP"), "Hitpoints");
        CANONICAL = Collections.unmodifiableMap(map);
    }

    private SkillNames() {
    }

    /** Display name such as {@code Attack}, or null when {@code raw} is not a skill. */
    public static String canonical(String raw) {
        if (raw == null) {
            return null;
        }
        return CANONICAL.get(normalize(raw));
    }

    public static String normalize(String raw) {
        if (raw == null) {
            return "";
        }
        return raw.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z]", "");
    }
}

