package com.osr.jei.search;

import com.osr.jei.model.SearchItem;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Filters the item index. Names that start with the query come first.
 * Within each group the original id order is preserved.
 */
public final class ItemSearch {

    private ItemSearch() {
    }

    public static List<SearchItem> rank(List<SearchItem> items, String query, int limit) {
        return rank(items, query, limit, SearchCriteria.ANY);
    }

    public static List<SearchItem> rank(List<SearchItem> items, String query, int limit, SearchCriteria criteria) {
        if (items == null || items.isEmpty() || query == null || limit <= 0) {
            return Collections.emptyList();
        }
        SearchCriteria filter = criteria == null ? SearchCriteria.ANY : criteria;
        String lower = query.trim().toLowerCase(java.util.Locale.ROOT);
        if (lower.length() < 2) {
            return Collections.emptyList();
        }
        List<SearchItem> prefix = new ArrayList<>();
        List<SearchItem> rest = new ArrayList<>();
        for (SearchItem item : items) {
            if (item == null || item.nameLower == null || !filter.matches(item)) {
                continue;
            }
            if (!item.nameLower.contains(lower)) {
                continue;
            }
            if (item.nameLower.startsWith(lower)) {
                prefix.add(item);
            } else {
                rest.add(item);
            }
        }
        List<SearchItem> out = new ArrayList<>(Math.min(limit, prefix.size() + rest.size()));
        for (SearchItem item : prefix) {
            if (out.size() >= limit) {
                return out;
            }
            out.add(item);
        }
        for (SearchItem item : rest) {
            if (out.size() >= limit) {
                break;
            }
            out.add(item);
        }
        return out;
    }
}

package com.osr.jei.search;

/**
 * Compact flags stored on each index entry.
 * Bit 0 members, bit 1 tradeable, bit 2 equipable, bit 3 slot present,
 * bits 4-7 the worn-container slot index (0 is a real slot, so presence is separate).
 */
public final class ItemTraits {

    public static final int MEMBERS = 1;
    public static final int TRADEABLE = 1 << 1;
    public static final int EQUIPABLE = 1 << 2;
    public static final int HAS_SLOT = 1 << 3;
    public static final int SLOT_SHIFT = 4;
    public static final int SLOT_MASK = 0xF;

    private ItemTraits() {
    }

    public static int pack(boolean members, boolean tradeable, boolean equipable, int slotIndex) {
        int flags = 0;
        if (members) {
            flags |= MEMBERS;
        }
        if (tradeable) {
            flags |= TRADEABLE;
        }
        if (equipable) {
            flags |= EQUIPABLE;
        }
        if (slotIndex >= 0 && slotIndex <= SLOT_MASK) {
            flags |= HAS_SLOT;
            flags |= (slotIndex & SLOT_MASK) << SLOT_SHIFT;
        }
        return flags;
    }

    public static boolean members(int flags) {
        return (flags & MEMBERS) != 0;
    }

    public static boolean tradeable(int flags) {
        return (flags & TRADEABLE) != 0;
    }

    public static boolean equipable(int flags) {
        return (flags & EQUIPABLE) != 0;
    }

    /** Worn-container index, or -1 when the item has no gear slot. */
    public static int slot(int flags) {
        if ((flags & HAS_SLOT) == 0) {
            return -1;
        }
        return (flags >> SLOT_SHIFT) & SLOT_MASK;
    }
}

package com.osr.jei.search;

import com.osr.jei.model.SearchItem;

/** Sidebar filters. All of them default to allowing every item. */
public final class SearchCriteria {

    public enum Trade {
        ANY("Any trade"),
        TRADEABLE("Tradeable"),
        UNTRADEABLE("Untradeable");

        private final String label;

        Trade(String label) {
            this.label = label;
        }

        @Override
        public String toString() {
            return label;
        }
    }

    public enum Members {
        ANY("Any world"),
        MEMBERS("Members"),
        FREE("Free-to-play");

        private final String label;

        Members(String label) {
            this.label = label;
        }

        @Override
        public String toString() {
            return label;
        }
    }

    public enum Equip {
        ANY("Any item"),
        EQUIPABLE("Equipable"),
        NOT_EQUIPABLE("Not equipable");

        private final String label;

        Equip(String label) {
            this.label = label;
        }

        @Override
        public String toString() {
            return label;
        }
    }

    public enum SlotChoice {
        ANY("Any slot", -1),
        HEAD("Head", 0),
        CAPE("Cape", 1),
        AMULET("Amulet", 2),
        WEAPON("Weapon", 3),
        BODY("Body", 4),
        SHIELD("Shield", 5),
        LEGS("Legs", 7),
        GLOVES("Gloves", 9),
        BOOTS("Boots", 10),
        RING("Ring", 12),
        AMMO("Ammo", 13);

        private final String label;
        private final int containerIndex;

        SlotChoice(String label, int containerIndex) {
            this.label = label;
            this.containerIndex = containerIndex;
        }

        public int containerIndex() {
            return containerIndex;
        }

        @Override
        public String toString() {
            return label;
        }
    }

    public static final SearchCriteria ANY = new SearchCriteria(Trade.ANY, Members.ANY, Equip.ANY, SlotChoice.ANY);

    public final Trade trade;
    public final Members members;
    public final Equip equip;
    public final SlotChoice slot;
    /** When false, cutscene props from the animation-item list are left out. */
    public final boolean showAnimationItems;
    /** When false, sailing courier crates from the task-carry list are left out. */
    public final boolean showTaskCarryItems;

    public SearchCriteria(Trade trade, Members members, Equip equip, SlotChoice slot) {
        this(trade, members, equip, slot, true, true);
    }

    public SearchCriteria(
        Trade trade,
        Members members,
        Equip equip,
        SlotChoice slot,
        boolean showAnimationItems,
        boolean showTaskCarryItems
    ) {
        this.trade = trade == null ? Trade.ANY : trade;
        this.members = members == null ? Members.ANY : members;
        this.equip = equip == null ? Equip.ANY : equip;
        this.slot = slot == null ? SlotChoice.ANY : slot;
        this.showAnimationItems = showAnimationItems;
        this.showTaskCarryItems = showTaskCarryItems;
    }

    public boolean matches(SearchItem item) {
        if (item == null) {
            return false;
        }
        int flags = item.traits;
        if (trade == Trade.TRADEABLE && !ItemTraits.tradeable(flags)) {
            return false;
        }
        if (trade == Trade.UNTRADEABLE && ItemTraits.tradeable(flags)) {
            return false;
        }
        if (members == Members.MEMBERS && !item.members) {
            return false;
        }
        if (members == Members.FREE && item.members) {
            return false;
        }
        if (equip == Equip.EQUIPABLE && !ItemTraits.equipable(flags)) {
            return false;
        }
        if (equip == Equip.NOT_EQUIPABLE && ItemTraits.equipable(flags)) {
            return false;
        }
        if (slot != SlotChoice.ANY && ItemTraits.slot(flags) != slot.containerIndex()) {
            return false;
        }
        if (!showAnimationItems && AnimationItems.contains(item.id)) {
            return false;
        }
        if (!showTaskCarryItems && TaskCarryItems.contains(item.id)) {
            return false;
        }
        return true;
    }
}

package com.osr.jei.service;

import com.osr.jei.pricing.BuyLimitSnapshot;
import com.osr.jei.pricing.LimitResult;
import com.osr.jei.wiki.RequestCancelledException;
import com.osr.jei.wiki.WikiHttp;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;

/**
 * One {@code /mapping} download for GE buy limits. It is started only when a
 * caller asks, kept for {@link BuyLimitSnapshot#TTL_MS}, and not requested
 * again per item. Concurrent callers share one request. A failed attempt
 * keeps the previous snapshot, waits {@link #FAILURE_BACKOFF_MS}, and does
 * not replace a previous good snapshot. {@link #allowRetry()} clears the wait.
 */
@Slf4j
@Singleton
public class BuyLimitService {

    static final String MAPPING = "https://prices.runescape.wiki/api/v1/osrs/mapping";
    static final long FAILURE_BACKOFF_MS = 8_000L;

    private final WikiHttp wikiHttp;
    private final Object lock = new Object();
    private volatile BuyLimitSnapshot snapshot;
    private volatile long nextAttemptAt;
    private CompletableFuture<LimitResult> inflight;

    @Inject
    public BuyLimitService(WikiHttp wikiHttp) {
        this.wikiHttp = wikiHttp;
    }

    /** Lets the next load contact the mapping API even if a failure holdoff is active. */
    public void allowRetry() {
        nextAttemptAt = 0L;
    }

    public CompletableFuture<LimitResult> load() {
        long now = System.currentTimeMillis();
        BuyLimitSnapshot current = snapshot;
        if (current != null && current.fresh(now)) {
            return CompletableFuture.completedFuture(new LimitResult(current, false));
        }
        if (now < nextAttemptAt) {
            return CompletableFuture.completedFuture(new LimitResult(current, true));
        }
        synchronized (lock) {
            current = snapshot;
            now = System.currentTimeMillis();
            if (current != null && current.fresh(now)) {
                return CompletableFuture.completedFuture(new LimitResult(current, false));
            }
            if (now < nextAttemptAt) {
                return CompletableFuture.completedFuture(new LimitResult(current, true));
            }
            if (inflight != null) {
                return inflight;
            }
            CompletableFuture<LimitResult> mine = new CompletableFuture<>();
            inflight = mine;
            wikiHttp.getStableElement(MAPPING).whenComplete((root, error) -> {
                synchronized (lock) {
                    if (inflight == mine) {
                        inflight = null;
                    }
                }
                if (error != null) {
                    Throwable cause = unwrap(error);
                    if (cause instanceof RequestCancelledException) {
                        mine.completeExceptionally(cause);
                        return;
                    }
                    nextAttemptAt = System.currentTimeMillis() + FAILURE_BACKOFF_MS;
                    log.debug("Could not refresh GE buy limits: {}", cause.getMessage());
                    mine.complete(new LimitResult(snapshot, true));
                    return;
                }
                if (root == null || !root.isJsonArray()) {
                    nextAttemptAt = System.currentTimeMillis() + FAILURE_BACKOFF_MS;
                    mine.completeExceptionally(new IOException("Unexpected mapping JSON"));
                    return;
                }
                BuyLimitSnapshot fresh = BuyLimitSnapshot.fromMapping(root, System.currentTimeMillis());
                snapshot = fresh;
                nextAttemptAt = 0L;
                mine.complete(new LimitResult(fresh, false));
            });
            return mine;
        }
    }

    private static Throwable unwrap(Throwable error) {
        Throwable current = error;
        while (current instanceof CompletionException && current.getCause() != null) {
            current = current.getCause();
        }
        return current;
    }
}

