package com.osr.jei.service;

import com.osr.jei.model.DropEntry;
import com.osr.jei.model.EquipmentStats;
import com.osr.jei.model.RecipeInfo;
import com.osr.jei.model.ShopEntry;
import com.osr.jei.requirements.ItemRequirements;
import com.osr.jei.requirements.RequirementParser;
import com.osr.jei.wiki.DropTableParser;
import com.osr.jei.wiki.EquipmentParser;
import com.osr.jei.wiki.HtmlSections;
import com.osr.jei.wiki.PageContent;
import com.osr.jei.wiki.RecipeParser;
import com.osr.jei.wiki.RecipeUses;
import com.osr.jei.wiki.ShopTableParser;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Optional;

/** Everything parsed from a single item-page response. */
public final class ItemDetails {

    public static final ItemDetails EMPTY = new ItemDetails(
        Collections.emptyList(),
        Optional.empty(),
        Double.NaN,
        Collections.emptyList(),
        Collections.emptyList(),
        Collections.emptyList()
    );

    public final List<RecipeInfo> recipes;
    public final Optional<EquipmentStats> stats;
    public final double weight;
    public final List<ShopEntry> shops;
    public final List<DropEntry> drops;
    public final List<String> products;
    public final ItemRequirements requirements;
    /** True when the wiki confirmed it has no page for this name. */
    public final boolean missing;

    public static final ItemDetails MISSING = new ItemDetails(
        Collections.emptyList(),
        Optional.empty(),
        Double.NaN,
        Collections.emptyList(),
        Collections.emptyList(),
        Collections.emptyList(),
        ItemRequirements.NONE,
        true
    );

    public ItemDetails(
        List<RecipeInfo> recipes,
        Optional<EquipmentStats> stats,
        double weight,
        List<ShopEntry> shops,
        List<DropEntry> drops,
        List<String> products
    ) {
        this(recipes, stats, weight, shops, drops, products, ItemRequirements.NONE);
    }

    public ItemDetails(
        List<RecipeInfo> recipes,
        Optional<EquipmentStats> stats,
        double weight,
        List<ShopEntry> shops,
        List<DropEntry> drops,
        List<String> products,
        ItemRequirements requirements
    ) {
        this(recipes, stats, weight, shops, drops, products, requirements, false);
    }

    public ItemDetails(
        List<RecipeInfo> recipes,
        Optional<EquipmentStats> stats,
        double weight,
        List<ShopEntry> shops,
        List<DropEntry> drops,
        List<String> products,
        ItemRequirements requirements,
        boolean missing
    ) {
        this.recipes = recipes;
        this.stats = stats;
        this.weight = weight;
        this.shops = shops;
        this.drops = drops;
        this.products = products;
        this.requirements = requirements == null ? ItemRequirements.NONE : requirements;
        this.missing = missing;
    }

    public static ItemDetails from(PageContent page) {
        return from(page, "");
    }

    /**
     * Recipes whose product is {@code viewedName} stay in Crafting. Recipes that
     * use that item to make something else add that product to Used to craft.
     * An empty name keeps every recipe, which is the older page-wide parse.
     */
    public static ItemDetails from(PageContent page, String viewedName) {
        if (page == null || page.missing) {
            return MISSING;
        }
        String shopsHtml = shopSection(page.html);
        String sourcesHtml = firstSection(page.html, "Item_sources", "Sources", "Drop_sources", "Drops");
        String productsHtml = firstSection(page.html, "Products", "Uses", "Items_created", "Created_from");
        RecipeUses.Split uses = RecipeUses.split(
            RecipeParser.parseAll(page.wikitext),
            viewedName,
            RecipeUses.pageSubject(page.wikitext));
        return new ItemDetails(
            uses.crafting,
            EquipmentParser.parseStats(page.wikitext),
            EquipmentParser.parseWeight(page.wikitext),
            ShopTableParser.parse(shopsHtml),
            DropTableParser.parse(sourcesHtml),
            RecipeUses.mergeProducts(UsedInService.parseProductsTable(productsHtml), uses.otherProducts),
            RequirementParser.parse(page.wikitext)
        );
    }

    /**
     * Shop rows live in a {@code store-locations-list} table. Prefer the shop
     * heading, but if that slice has no such table, scan the rest of the page.
     * Some pages render the table under a heading id this plugin does not know.
     */
    private static String shopSection(String html) {
        String slice = firstSection(html, "Shop_locations", "Shops", "Sold_by", "Store_locations");
        if (hasStoreTable(slice)) {
            return slice;
        }
        if (hasStoreTable(html)) {
            return html;
        }
        return slice;
    }

    private static boolean hasStoreTable(String html) {
        return html != null && html.toLowerCase(Locale.ROOT).contains("store-locations-list");
    }

    private static String firstSection(String html, String... ids) {
        for (String id : ids) {
            String slice = HtmlSections.sliceById(html, id);
            if (!slice.isEmpty()) {
                return slice;
            }
        }
        return "";
    }
}

package com.osr.jei.service;

import com.osr.jei.wiki.TtlCache;
import com.osr.jei.wiki.WikiPages;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Locale;
import java.util.concurrent.CompletableFuture;

/**
 * Loads an item page once and reuses the parsed result for {@link WikiPages#TTL_MS}.
 * Confirmed missing pages stay cached. Transport errors do not.
 */
@Slf4j
@Singleton
public class ItemDetailsService {

    static final int CACHE_SIZE = 96;

    private final WikiPages pages;
    private final TtlCache<String, ItemDetails> cache = new TtlCache<>(CACHE_SIZE, WikiPages.TTL_MS);

    @Inject
    public ItemDetailsService(WikiPages pages) {
        this.pages = pages;
    }

    /** Cached parse, or null when this name has not been loaded. Does not fetch. */
    public ItemDetails peek(String itemName) {
        if (itemName == null || itemName.isEmpty()) {
            return null;
        }
        return cache.get(itemName.toLowerCase(Locale.ROOT), System.currentTimeMillis());
    }

    /** Drops a parsed page and its failure holdoff so the next load can fetch it. */
    public void retry(String itemName) {
        if (itemName == null || itemName.isEmpty()) {
            return;
        }
        cache.remove(itemName.toLowerCase(Locale.ROOT));
        pages.allowRetry(itemName);
    }

    public CompletableFuture<ItemDetails> load(String itemName) {
        if (itemName == null || itemName.isEmpty()) {
            return CompletableFuture.completedFuture(ItemDetails.EMPTY);
        }
        String key = itemName.toLowerCase(Locale.ROOT);
        ItemDetails cached = cache.get(key, System.currentTimeMillis());
        if (cached != null) {
            return CompletableFuture.completedFuture(cached);
        }
        return pages.load(itemName).handle((page, error) -> {
            if (error != null) {
                Throwable cause = error.getCause() == null ? error : error.getCause();
                if (cause instanceof com.osr.jei.wiki.RequestCancelledException) {
                    throw new java.util.concurrent.CompletionException(cause);
                }
                log.debug("[Item Browser] Item page failed for '{}': {}", itemName, cause.getMessage());
                throw new java.util.concurrent.CompletionException(cause);
            }
            ItemDetails details = ItemDetails.from(page, itemName);
            cache.put(key, details, System.currentTimeMillis());
            return details;
        });
    }
}

package com.osr.jei.service;

import com.osr.jei.model.MonsterInfo;
import com.osr.jei.wiki.MonsterParser;
import com.osr.jei.wiki.TtlCache;
import com.osr.jei.wiki.RequestCancelledException;
import com.osr.jei.wiki.WikiPages;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Locale;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;

/** One parse per monster page, cached after a successful read for {@link WikiPages#TTL_MS}. */
@Slf4j
@Singleton
public class MonsterService {

    static final int CACHE_SIZE = 64;

    private final WikiPages pages;
    private final TtlCache<String, Optional<MonsterInfo>> cache = new TtlCache<>(CACHE_SIZE, WikiPages.TTL_MS);

    @Inject
    public MonsterService(WikiPages pages) {
        this.pages = pages;
    }

    public CompletableFuture<Optional<MonsterInfo>> getMonsterInfo(String monsterName) {
        if (monsterName == null || monsterName.isEmpty()) {
            return CompletableFuture.completedFuture(Optional.empty());
        }
        String key = monsterName.toLowerCase(Locale.ROOT);
        Optional<MonsterInfo> cached = cache.get(key, System.currentTimeMillis());
        if (cached != null) {
            return CompletableFuture.completedFuture(cached);
        }
        final long requested = System.nanoTime();
        return pages.loadWikitext(monsterName).handle((page, error) -> {
            long arrived = System.nanoTime();
            if (error != null) {
                Throwable cause = error.getCause() == null ? error : error.getCause();
                if (cause instanceof RequestCancelledException) {
                    throw new CompletionException(cause);
                }
                log.debug("[Item Browser] Monster info failed for '{}': {}", monsterName, cause.getMessage());
                throw new CompletionException(cause);
            }
            long parseStarted = System.nanoTime();
            Optional<MonsterInfo> info = page.missing
                ? Optional.empty()
                : MonsterParser.parse(monsterName, page.wikitext);
            log.debug(
                "Monster {} wiki {} ms, parse {} ms. Not queued on the client thread or the panel scheduler.",
                monsterName,
                (arrived - requested) / 1_000_000L,
                (System.nanoTime() - parseStarted) / 1_000_000L
            );
            cache.put(key, info, System.currentTimeMillis());
            return info;
        });
    }

    /** Drops a parsed monster and its failure holdoff so the next load can fetch it. */
    public void retry(String monsterName) {
        if (monsterName == null || monsterName.isEmpty()) {
            return;
        }
        cache.remove(monsterName.toLowerCase(Locale.ROOT));
        pages.allowRetry(monsterName);
    }
}

package com.osr.jei.service;

import com.osr.jei.pricing.PriceLookup;
import com.osr.jei.pricing.PriceSnapshot;
import com.osr.jei.wiki.RequestCancelledException;
import com.osr.jei.wiki.WikiHttp;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;

/**
 * One bulk {@code /latest} download shared by every price lookup, including the nature rune.
 * The snapshot lives for {@link PriceSnapshot#TTL_MS}. A failed refresh keeps the previous
 * snapshot, waits {@link #FAILURE_BACKOFF_MS}, and does not hit the prices API again until
 * that passes or {@link #allowRetry()} is called. Concurrent lookups share one request.
 */
@Slf4j
@Singleton
public class PriceService {

    static final String LATEST = "https://prices.runescape.wiki/api/v1/osrs/latest";
    static final long FAILURE_BACKOFF_MS = 8_000L;

    private final WikiHttp wikiHttp;
    private final Object lock = new Object();
    private volatile PriceSnapshot snapshot;
    private volatile long nextAttemptAt;
    private CompletableFuture<Load> inflight;

    @Inject
    public PriceService(WikiHttp wikiHttp) {
        this.wikiHttp = wikiHttp;
    }

    /** Lets the next lookup contact the prices API even if a failure holdoff is active. */
    public void allowRetry() {
        nextAttemptAt = 0L;
    }

    public CompletableFuture<PriceLookup> lookup(int itemId) {
        return load().thenApply(loaded ->
            PriceLookup.from(loaded.snapshot, loaded.failed, itemId, System.currentTimeMillis()));
    }

    private CompletableFuture<Load> load() {
        long now = System.currentTimeMillis();
        PriceSnapshot current = snapshot;
        if (current != null && current.fresh(now)) {
            return CompletableFuture.completedFuture(new Load(current, false));
        }
        if (now < nextAttemptAt) {
            return CompletableFuture.completedFuture(new Load(current, true));
        }
        synchronized (lock) {
            current = snapshot;
            now = System.currentTimeMillis();
            if (current != null && current.fresh(now)) {
                return CompletableFuture.completedFuture(new Load(current, false));
            }
            if (now < nextAttemptAt) {
                return CompletableFuture.completedFuture(new Load(current, true));
            }
            if (inflight != null) {
                return inflight;
            }
            CompletableFuture<Load> mine = new CompletableFuture<>();
            inflight = mine;
            wikiHttp.getJson(LATEST).whenComplete((root, error) -> {
                synchronized (lock) {
                    if (inflight == mine) {
                        inflight = null;
                    }
                }
                if (error != null) {
                    Throwable cause = unwrap(error);
                    if (cause instanceof RequestCancelledException) {
                        mine.completeExceptionally(cause);
                        return;
                    }
                    nextAttemptAt = System.currentTimeMillis() + FAILURE_BACKOFF_MS;
                    log.debug("Could not refresh GE prices: {}", cause.getMessage());
                    mine.complete(new Load(snapshot, true));
                    return;
                }
                PriceSnapshot fresh = PriceSnapshot.fromRoot(root, System.currentTimeMillis());
                snapshot = fresh;
                nextAttemptAt = 0L;
                mine.complete(new Load(fresh, false));
            });
            return mine;
        }
    }

    private static Throwable unwrap(Throwable error) {
        Throwable current = error;
        while (current instanceof CompletionException && current.getCause() != null) {
            current = current.getCause();
        }
        return current;
    }

    private static final class Load {
        private final PriceSnapshot snapshot;
        private final boolean failed;

        private Load(PriceSnapshot snapshot, boolean failed) {
            this.snapshot = snapshot == null ? PriceSnapshot.empty() : snapshot;
            this.failed = failed;
        }
    }
}

