package com.osr.jei.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.ContainerAdapter;
import java.awt.event.ContainerEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * A section header that shows or hides an already-built body.
 * Toggling only changes visibility. It does not load anything.
 */
public final class CollapsibleSection extends JPanel {

    private static final Color HEADER = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color HEADER_HOVER = ColorScheme.DARK_GRAY_HOVER_COLOR;
    private static final String CHEVRON = "#64b4ff";

    private final String key;
    private final SectionState state;
    private final JPanel header;
    private final WrappingLabel titleLabel;
    private final JPanel body;
    private String title = "";
    private Runnable onToggle;

    public CollapsibleSection(String key, SectionState state, UiStyle style) {
        this.key = key;
        this.state = state == null ? new SectionState() : state;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setOpaque(false);
        setAlignmentX(LEFT_ALIGNMENT);
        setBorder(BorderFactory.createEmptyBorder(1, 0, 3, 0));

        header = new JPanel(new BorderLayout()) {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }

            @Override
            public Dimension getMinimumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(0, preferred.height);
            }
        };
        header.setOpaque(true);
        header.setBackground(HEADER);
        header.setAlignmentX(LEFT_ALIGNMENT);
        header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        header.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));

        titleLabel = new WrappingLabel();
        if (style != null) {
            style.apply(titleLabel, "bodyBold");
        }
        titleLabel.setForeground(Color.WHITE);
        titleLabel.setCursor(header.getCursor());
        header.add(titleLabel, BorderLayout.CENTER);

        MouseAdapter toggle = new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (e.getButton() != MouseEvent.BUTTON1) {
                    return;
                }
                toggle();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                header.setBackground(HEADER_HOVER);
                header.repaint();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                header.setBackground(HEADER);
                header.repaint();
            }
        };
        header.addMouseListener(toggle);
        titleLabel.addMouseListener(toggle);
        titleLabel.addContainerListener(new ContainerAdapter() {
            @Override
            public void componentAdded(ContainerEvent event) {
                if (event.getChild() != null) {
                    event.getChild().addMouseListener(toggle);
                }
            }
        });

        body = new ScrollWidthPanel();
        body.setOpaque(false);
        body.setAlignmentX(LEFT_ALIGNMENT);
        body.setBorder(BorderFactory.createEmptyBorder(1, 8, 2, 0));

        add(header);
        add(body);
        apply();
    }

    public void setTitle(String title) {
        this.title = title == null ? "" : title;
        apply();
    }

    public String getTitle() {
        return title;
    }

    public JPanel body() {
        return body;
    }

    public boolean isExpanded() {
        return state.expanded(key);
    }

    /** Applies the current {@link SectionState} without notifying the toggle listener. */
    public void sync() {
        apply();
    }

    /**
     * Runs after the body is shown or hidden. The runnable must not assume
     * a wiki fetch; the section itself only changes visibility.
     */
    public void setOnToggle(Runnable onToggle) {
        this.onToggle = onToggle;
    }

    /**
     * Shows or hides {@link #body()}. Callers keep the body contents they
     * already built; this method does not replace them.
     */
    public void toggle() {
        state.toggle(key);
        apply();
        if (onToggle != null) {
            onToggle.run();
        }
        revalidate();
        Container parent = getParent();
        if (parent != null) {
            parent.revalidate();
        }
        repaint();
    }

    private void apply() {
        String mark = state.expanded(key) ? "\u25be" : "\u25b8";
        titleLabel.setHtml("<font color='" + CHEVRON + "'>" + mark + "</font> " + escape(title));
        titleLabel.setToolTipText(title.isEmpty() ? null : title);
        body.setVisible(state.expanded(key));
    }

    private static String escape(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osr.jei.ui;

import com.osr.jei.JEIConfig;

/**
 * Which detail sections start open for a new item. This only flips visibility.
 * It does not request a wiki page. Monster rows still load when they are clicked.
 */
public final class DefaultOpen {

    private DefaultOpen() {
    }

    public static void apply(SectionState state, JEIConfig config) {
        if (state == null) {
            return;
        }
        state.reset();
        if (config == null) {
            return;
        }
        state.setExpanded(SectionState.TRADING, config.openTradingByDefault());
        state.setExpanded(SectionState.EQUIPMENT, config.openEquipmentByDefault());
        state.setExpanded(SectionState.SHOPS, config.openShopsByDefault());
        state.setExpanded(SectionState.USED_IN, config.openUsedInByDefault());
        state.setExpanded(SectionState.DROPS, config.openDropsByDefault());
        state.setExpanded(SectionState.CRAFTING, config.openCraftingByDefault());
        state.setExpanded(SectionState.LOCATIONS, config.openLocationsByDefault());
    }

    /** Config key to section id, or null when the key is not one of these settings. */
    public static String sectionKey(String configKey) {
        if (configKey == null) {
            return null;
        }
        switch (configKey) {
            case "openTradingByDefault":
                return SectionState.TRADING;
            case "openEquipmentByDefault":
                return SectionState.EQUIPMENT;
            case "openShopsByDefault":
                return SectionState.SHOPS;
            case "openUsedInByDefault":
                return SectionState.USED_IN;
            case "openDropsByDefault":
                return SectionState.DROPS;
            case "openCraftingByDefault":
                return SectionState.CRAFTING;
            case "openLocationsByDefault":
                return SectionState.LOCATIONS;
            default:
                return null;
        }
    }

    public static boolean enabled(JEIConfig config, String configKey) {
        if (config == null) {
            return false;
        }
        switch (configKey) {
            case "openTradingByDefault":
                return config.openTradingByDefault();
            case "openEquipmentByDefault":
                return config.openEquipmentByDefault();
            case "openShopsByDefault":
                return config.openShopsByDefault();
            case "openUsedInByDefault":
                return config.openUsedInByDefault();
            case "openDropsByDefault":
                return config.openDropsByDefault();
            case "openCraftingByDefault":
                return config.openCraftingByDefault();
            case "openLocationsByDefault":
                return config.openLocationsByDefault();
            default:
                return false;
        }
    }
}

package com.osr.jei.ui;

/**
 * Chevron and hint on a monster row in the drop list.
 * The hint is only on a collapsed row, so an open row stays one line shorter.
 */
public final class DropRowMarks {

    public static final String HINT = "Click for locations";
    public static final String CHEVRON_COLOR = "#64b4ff";

    private DropRowMarks() {
    }

    public static String chevron(boolean open) {
        return open ? "\u25be" : "\u25b8";
    }

    /** {@code name} and {@code detail} are already escaped. */
    public static String html(String name, String detail, boolean open) {
        StringBuilder html = new StringBuilder();
        html.append("<b>").append(name == null ? "" : name).append("</b>");
        html.append("<br><font color='#999999'>").append(detail == null ? "" : detail).append("</font>");
        if (!open) {
            html.append("<br><font color='#888888'>").append(HINT).append("</font>");
        }
        return html.toString();
    }
}

package com.osr.jei.ui;

import javax.swing.JLabel;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Insets;

/**
 * Single-line label for an icon row. Text that does not fit the current
 * sidebar width is cut with an ellipsis; the tooltip keeps the full line.
 */
public class EllipsisLabel extends JLabel {

    private String name = "";
    private Color nameColor = Color.WHITE;
    private String suffix = "";
    private Color suffixColor = Color.LIGHT_GRAY;

    public EllipsisLabel() {
        setAlignmentX(LEFT_ALIGNMENT);
    }

    public void setPieces(String name, Color nameColor, String suffix, Color suffixColor) {
        this.name = name == null ? "" : name;
        this.nameColor = nameColor == null ? getForeground() : nameColor;
        this.suffix = suffix == null ? "" : suffix;
        this.suffixColor = suffixColor == null ? this.nameColor : suffixColor;
        setForeground(this.nameColor);
        setToolTipText(fullText());
        revalidate();
        repaint();
    }

    @Override
    public String getText() {
        return fullText();
    }

    @Override
    public void setText(String text) {
        setPieces(text, nameColor == null ? getForeground() : nameColor, "", null);
    }

    private String fullText() {
        if (suffix == null || suffix.isEmpty()) {
            return name == null ? "" : name;
        }
        return name + " \u00b7 " + suffix;
    }

    @Override
    public Dimension getPreferredSize() {
        FontMetrics metrics = getFontMetrics(getFont());
        Insets insets = getInsets();
        int textWidth = metrics.stringWidth(fullText());
        int available = WidthLimit.of(this);
        int width = Math.min(textWidth, Math.max(0, available));
        int height = metrics.getHeight() + insets.top + insets.bottom;
        return new Dimension(Math.max(0, width), Math.max(1, height));
    }

    @Override
    public Dimension getMinimumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(0, preferred.height);
    }

    @Override
    public Dimension getMaximumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(Integer.MAX_VALUE, preferred.height);
    }

    @Override
    protected void paintComponent(Graphics g) {
        if (isOpaque()) {
            g.setColor(getBackground());
            g.fillRect(0, 0, getWidth(), getHeight());
        }
        FontMetrics metrics = g.getFontMetrics(getFont());
        Insets insets = getInsets();
        int available = getWidth() - insets.left - insets.right;
        if (available <= 0) {
            return;
        }
        int y = insets.top + metrics.getAscent();
        String shownName = name == null ? "" : name;
        String shownSuffix = suffix == null || suffix.isEmpty() ? "" : " \u00b7 " + suffix;
        int nameWidth = metrics.stringWidth(shownName);
        int suffixWidth = metrics.stringWidth(shownSuffix);
        if (nameWidth + suffixWidth <= available) {
            g.setColor(nameColor);
            g.drawString(shownName, insets.left, y);
            if (!shownSuffix.isEmpty()) {
                g.setColor(suffixColor);
                g.drawString(shownSuffix, insets.left + nameWidth, y);
            }
            return;
        }
        g.setColor(nameColor);
        g.drawString(clip(metrics, shownName + shownSuffix, available), insets.left, y);
    }

    private static String clip(FontMetrics metrics, String text, int available) {
        String ellipsis = "\u2026";
        int ellipsisWidth = metrics.stringWidth(ellipsis);
        if (available <= ellipsisWidth) {
            return ellipsis;
        }
        int end = text.length();
        while (end > 0 && metrics.stringWidth(text.substring(0, end)) + ellipsisWidth > available) {
            end--;
        }
        return text.substring(0, end) + ellipsis;
    }
}

