package com.osr.jei.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;

/**
 * Equal icon cells that fill the current width. Extra space becomes the gap
 * between columns, so a row does not leave a dead strip on the right.
 */
public final class IconGridLayout implements LayoutManager {

    private final int cell;
    private final int gap;

    public IconGridLayout(int cell, int gap) {
        this.cell = Math.max(1, cell);
        this.gap = Math.max(0, gap);
    }

    public static int columns(int innerWidth, int cell, int gap) {
        int unit = Math.max(1, cell + Math.max(0, gap));
        int width = Math.max(cell, innerWidth);
        return Math.max(1, (width + Math.max(0, gap)) / unit);
    }

    @Override
    public void addLayoutComponent(String name, Component comp) {
    }

    @Override
    public void removeLayoutComponent(Component comp) {
    }

    @Override
    public Dimension preferredLayoutSize(Container parent) {
        return size(parent, true);
    }

    @Override
    public Dimension minimumLayoutSize(Container parent) {
        Insets insets = parent.getInsets();
        return new Dimension(cell + insets.left + insets.right, cell + insets.top + insets.bottom);
    }

    @Override
    public void layoutContainer(Container parent) {
        synchronized (parent.getTreeLock()) {
            Insets insets = parent.getInsets();
            int inner = Math.max(cell, parent.getWidth() - insets.left - insets.right);
            int columns = columns(inner, cell, gap);
            int count = visibleCount(parent);
            if (count == 0) {
                return;
            }
            int hgap = horizontalGap(inner, columns);
            int index = 0;
            for (Component child : parent.getComponents()) {
                if (!child.isVisible()) {
                    continue;
                }
                int column = index % columns;
                int row = index / columns;
                int x = insets.left + column * (cell + hgap);
                if (columns == 1) {
                    x = insets.left + Math.max(0, (inner - cell) / 2);
                }
                int y = insets.top + row * (cell + gap);
                child.setBounds(x, y, cell, cell);
                index++;
            }
        }
    }

    private Dimension size(Container parent, boolean preferred) {
        Insets insets = parent.getInsets();
        int inner = parent.getWidth() - insets.left - insets.right;
        if (inner < cell && parent.getParent() != null) {
            Insets outer = parent.getParent().getInsets();
            inner = parent.getParent().getWidth() - outer.left - outer.right;
        }
        if (inner < cell) {
            inner = net.runelite.client.ui.PluginPanel.PANEL_WIDTH - 16;
        }
        int count = visibleCount(parent);
        int columns = columns(inner, cell, gap);
        int rows = count == 0 ? 0 : (count + columns - 1) / columns;
        int height = rows == 0 ? 0 : rows * cell + Math.max(0, rows - 1) * gap;
        int width = Math.max(inner, cell);
        return new Dimension(width + insets.left + insets.right, height + insets.top + insets.bottom);
    }

    private int horizontalGap(int inner, int columns) {
        if (columns <= 1) {
            return 0;
        }
        int leftover = inner - columns * cell;
        return Math.max(gap, leftover / (columns - 1));
    }

    private static int visibleCount(Container parent) {
        int count = 0;
        for (Component child : parent.getComponents()) {
            if (child.isVisible()) {
                count++;
            }
        }
        return count;
    }
}

package com.osr.jei.ui;

import net.runelite.client.ui.PluginPanel;

import javax.swing.JPanel;
import javax.swing.Scrollable;
import java.awt.Dimension;
import java.awt.Rectangle;

/** Icon grid that stays as wide as the sidebar and reports the wrapped height. */
public class IconGridPanel extends JPanel implements Scrollable {

    public IconGridPanel(int cell, int gap) {
        super(new IconGridLayout(cell, gap));
        setAlignmentX(LEFT_ALIGNMENT);
    }

    @Override
    public Dimension getPreferredSize() {
        return getLayout().preferredLayoutSize(this);
    }

    @Override
    public Dimension getMinimumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(0, preferred.height);
    }

    @Override
    public Dimension getMaximumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(Integer.MAX_VALUE, preferred.height);
    }

    @Override
    public Dimension getPreferredScrollableViewportSize() {
        return new Dimension(PluginPanel.PANEL_WIDTH, getPreferredSize().height);
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
        return Math.max(16, visibleRect == null ? 16 : visibleRect.height - 16);
    }

    @Override
    public boolean getScrollableTracksViewportWidth() {
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight() {
        return false;
    }
}

package com.osr.jei.ui;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.List;

/**
 * One filter per row. Every label uses the same column width, the widest
 * label at the current font, so the combos start on one line and share the
 * leftover sidebar width.
 */
public final class LabeledFilters {

    private static final int GAP = 8;

    private LabeledFilters() {
    }

    public static JPanel column(UiStyle style, Color labelColor, String[] labels, JComponent[] fields) {
        return column(style, style == null ? null : style.forRole("small"), labelColor, labels, fields);
    }

    public static JPanel column(Font labelFont, Color labelColor, String[] labels, JComponent[] fields) {
        return column(null, labelFont, labelColor, labels, fields);
    }

    private static JPanel column(
        UiStyle style,
        Font labelFont,
        Color labelColor,
        String[] labels,
        JComponent[] fields
    ) {
        List<JLabel> names = new ArrayList<>();
        JPanel box = new JPanel() {
            @Override
            public Dimension getPreferredSize() {
                shareLabelColumn(names);
                return super.getPreferredSize();
            }

            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }

            @Override
            public Dimension getMinimumSize() {
                return new Dimension(0, getPreferredSize().height);
            }

            @Override
            public void doLayout() {
                shareLabelColumn(names);
                super.doLayout();
            }
        };
        box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
        box.setOpaque(false);
        box.setAlignmentX(0f);
        for (int i = 0; i < labels.length; i++) {
            if (i > 0) {
                box.add(Box.createRigidArea(new Dimension(0, 3)));
            }
            JLabel name = nameLabel(style, labelFont, labelColor, labels[i]);
            names.add(name);
            box.add(row(name, fields[i]));
        }
        shareLabelColumn(names);
        return box;
    }

    /** Widest label at the fonts they have now. Called again after a font-size change. */
    static int shareLabelColumn(List<JLabel> names) {
        int column = 0;
        for (JLabel name : names) {
            column = Math.max(column, textWidth(name));
        }
        for (JLabel name : names) {
            int height = Math.max(1, name.getFontMetrics(name.getFont()).getHeight());
            Dimension size = new Dimension(column, height);
            name.setPreferredSize(size);
            name.setMinimumSize(size);
            name.setMaximumSize(size);
        }
        return column;
    }

    private static int textWidth(JLabel name) {
        String text = name.getText() == null ? "" : name.getText();
        FontMetrics metrics = name.getFontMetrics(name.getFont());
        Insets insets = name.getInsets();
        int pad = insets == null ? 0 : insets.left + insets.right;
        return metrics.stringWidth(text) + pad;
    }

    private static JLabel nameLabel(UiStyle style, Font labelFont, Color labelColor, String text) {
        JLabel name = new JLabel(text);
        if (style != null) {
            style.apply(name, "small");
        } else if (labelFont != null) {
            name.setFont(labelFont);
            name.putClientProperty(UiStyle.ROLE, "small");
        } else {
            name.putClientProperty(UiStyle.ROLE, "small");
        }
        if (labelColor != null) {
            name.setForeground(labelColor);
        }
        name.setHorizontalAlignment(JLabel.LEFT);
        return name;
    }

    private static JPanel row(JLabel name, JComponent field) {
        JPanel line = new JPanel(new GridBagLayout()) {
            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }

            @Override
            public Dimension getMinimumSize() {
                return new Dimension(0, getPreferredSize().height);
            }
        };
        line.setOpaque(false);
        line.setAlignmentX(0f);
        GridBagConstraints label = new GridBagConstraints();
        label.gridx = 0;
        label.gridy = 0;
        label.anchor = GridBagConstraints.LINE_START;
        label.fill = GridBagConstraints.NONE;
        label.insets = new Insets(0, 0, 0, GAP);
        label.weightx = 0;
        GridBagConstraints value = new GridBagConstraints();
        value.gridx = 1;
        value.gridy = 0;
        value.anchor = GridBagConstraints.LINE_START;
        value.fill = GridBagConstraints.HORIZONTAL;
        value.weightx = 1;
        field.setMinimumSize(new Dimension(0, field.getMinimumSize().height));
        line.add(name, label);
        line.add(field, value);
        return line;
    }
}

package com.osr.jei.ui;

import com.osr.jei.wiki.LocationNames;

import javax.swing.JComponent;
import java.awt.Color;
import java.util.List;

/**
 * Monster and item location blocks. One place is a single line. Several places
 * are a count header and the full list, with no place name repeated in the header.
 */
public final class LocationLines {

    private static final Color ROW = new Color(200, 200, 200);

    private LocationLines() {
    }

    public static JComponent create(UiStyle style, SectionState state, List<String> places) {
        List<String> shown = LocationNames.distinct(places);
        if (shown.size() == 1) {
            WrappingLabel line = label(style, SectionSummaries.locations(shown), "bodyBold");
            line.setForeground(Color.WHITE);
            return line;
        }
        CollapsibleSection section = new CollapsibleSection(
            SectionState.LOCATIONS, state == null ? new SectionState() : state, style);
        section.setTitle(SectionSummaries.locations(shown));
        for (String place : shown) {
            WrappingLabel row = label(style, "\u00b7 " + place, "small");
            row.setForeground(ROW);
            row.setToolTipText(place);
            section.body().add(row);
        }
        return section;
    }

    private static WrappingLabel label(UiStyle style, String text, String role) {
        WrappingLabel label = new WrappingLabel();
        if (style != null) {
            style.apply(label, role);
        }
        label.setHtml(escape(text));
        label.setAlignmentX(WrappingLabel.LEFT_ALIGNMENT);
        return label;
    }

    private static String escape(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osr.jei.ui;

