package com.osr.jei.ui;

import java.util.List;

/**
 * Recent ids are newest first. The oldest entry is at the end of the list.
 */
public final class RecentItems {

    /** The list length Recent used before Max recent items existed. */
    public static final int PREVIOUS_CAP = 12;

    private RecentItems() {
    }

    public static int cap(RecentLimit limit) {
        return limit == null ? RecentLimit.TWELVE.count() : limit.count();
    }

    /** The Recent row is shown only while the setting is on and the list has entries. */
    public static boolean shows(boolean enabled, boolean hasEntries) {
        return enabled && hasEntries;
    }

    /**
     * Adds {@code id} at the front when Recent is shown. When it is hidden the
     * list is left as it is. Returns whether the list changed.
     */
    public static boolean record(List<Integer> newestFirst, int id, boolean enabled, int cap) {
        if (!enabled || newestFirst == null) {
            return false;
        }
        newestFirst.remove(Integer.valueOf(id));
        newestFirst.add(0, id);
        trim(newestFirst, cap);
        return true;
    }

    /** Drops the oldest entries past {@code cap}. Returns whether the list changed. */
    public static boolean trim(List<Integer> newestFirst, int cap) {
        if (newestFirst == null) {
            return false;
        }
        int limit = Math.max(0, cap);
        boolean changed = false;
        while (newestFirst.size() > limit) {
            newestFirst.remove(newestFirst.size() - 1);
            changed = true;
        }
        return changed;
    }

    public static void clear(List<Integer> newestFirst) {
        if (newestFirst != null) {
            newestFirst.clear();
        }
    }
}

package com.osr.jei.ui;

/**
 * How many icons Recent keeps. Each step is one full row of six.
 */
public enum RecentLimit {
    SIX(6),
    TWELVE(12),
    EIGHTEEN(18),
    TWENTY_FOUR(24),
    THIRTY(30),
    THIRTY_SIX(36);

    private final int count;

    RecentLimit(int count) {
        this.count = count;
    }

    public int count() {
        return count;
    }

    @Override
    public String toString() {
        return Integer.toString(count);
    }

    /** Nearest step. A tie rounds to the higher step, then stays inside 6 to 36. */
    public static RecentLimit nearest(int value) {
        int snapped = (int) (Math.round(value / 6.0) * 6);
        if (snapped < SIX.count) {
            snapped = SIX.count;
        }
        if (snapped > THIRTY_SIX.count) {
            snapped = THIRTY_SIX.count;
        }
        for (RecentLimit limit : values()) {
            if (limit.count == snapped) {
                return limit;
            }
        }
        return TWELVE;
    }
}

package com.osr.jei.ui;

import com.osr.jei.crafting.BuildExpander;
import com.osr.jei.crafting.RecipeText;
import com.osr.jei.model.RecipeInfo;
import com.osr.jei.owned.OwnedText;
import com.osr.jei.requirements.Mark;
import com.osr.jei.requirements.RequirementJudge;
import net.runelite.client.ui.ColorScheme;

import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Crafting tree for the detail pane. Rows wrap to the sidebar and use {@link UiStyle}.
 * The expand control and the item name are separate clicks.
 */
public final class RecipeTreeView {

    private static final Color LINK = new Color(100, 180, 255);
    private static final Color MUTED = new Color(150, 150, 150);
    private static final Color GOOD = new Color(150, 220, 150);
    private static final Color UNMET = new Color(130, 130, 130);

    public interface Actions {
        void toggle(String path, String itemName);

        void openItem(String itemName);

        boolean canOpen(String itemName);

        void expandAll();

        void collapseAll();

        void icon(JLabel label, String itemName);
    }

    /**
     * Owned counts for the open item. {@link #have(String)} is null when the
     * name is not in the catalogue, so the row must not claim zero.
     */
    public interface Counts {
        boolean show();

        boolean inventoryKnown();

        boolean bankKnown();

        Long have(String itemName);
    }

    /** Requirement judgment for recipe rows. Null means show the requirement with no marker. */
    public interface Marks {
        Mark recipe(RecipeInfo recipe);
    }

    private RecipeTreeView() {
    }

    public static void fill(JPanel body, UiStyle style, BuildExpander.Result result, boolean anyOpen, Actions actions) {
        fill(body, style, result, anyOpen, actions, null);
    }

    public static void fill(
        JPanel body,
        UiStyle style,
        BuildExpander.Result result,
        boolean anyOpen,
        Actions actions,
        Counts counts
    ) {
        fill(body, style, result, anyOpen, actions, counts, null);
    }

    public static void fill(
        JPanel body,
        UiStyle style,
        BuildExpander.Result result,
        boolean anyOpen,
        Actions actions,
        Counts counts,
        Marks marks
    ) {
        fill(body, style, result, anyOpen, actions, counts, marks, true);
    }

    public static void fill(
        JPanel body,
        UiStyle style,
        BuildExpander.Result result,
        boolean anyOpen,
        Actions actions,
        Counts counts,
        Marks marks,
        boolean includeHeader
    ) {
        body.removeAll();
        boolean ingredients = hasIngredients(result);
        if (includeHeader) {
            JLabel header = label(style, ingredients
                ? "Crafting / Build path"
                : (result.recipes.size() == 1 ? "Crafting recipe" : "Crafting recipes"), "bodyBold", Color.WHITE);
            body.add(header);
        }
        body.add(Box.createRigidArea(new Dimension(0, 3)));
        BuildExpander.RecipeBranch summaryBranch = summaryBranch(result);
        for (int i = 0; i < result.recipes.size(); i++) {
            if (i > 0) {
                body.add(Box.createRigidArea(new Dimension(0, 8)));
            }
            BuildExpander.RecipeBranch branch = result.recipes.get(i);
            Mark mark = markOf(marks, branch.recipe);
            String summary = RecipeText.withLoopedIngredients(
                RecipeText.summary(branch.recipe), loopedNames(branch.ingredients));
            if (!summary.isEmpty()) {
                body.add(html(style, RequirementJudge.htmlPrefix(mark) + escape(summary), "small", mark == Mark.UNMET ? UNMET : GOOD));
            }
            for (BuildExpander.BuildNode ingredient : branch.ingredients) {
                if (!ingredient.cycle) {
                    addNode(body, style, ingredient, actions, counts, marks, mark == Mark.UNMET);
                }
            }
        }
        addBaseMaterials(body, style, summaryBranch, counts);
    }

    /** One summary: the expanded recipe if there is one, otherwise the first. */
    private static BuildExpander.RecipeBranch summaryBranch(BuildExpander.Result result) {
        BuildExpander.RecipeBranch first = null;
        if (result == null || result.recipes == null) {
            return null;
        }
        for (BuildExpander.RecipeBranch branch : result.recipes) {
            if (first == null) {
                first = branch;
            }
            if (branchExpanded(branch)) {
                return branch;
            }
        }
        return first;
    }

    private static boolean branchExpanded(BuildExpander.RecipeBranch branch) {
        if (branch == null || branch.ingredients == null) {
            return false;
        }
        for (BuildExpander.BuildNode ingredient : branch.ingredients) {
            if (ingredient.expanded || ingredient.loading || !ingredient.children.isEmpty()) {
                return true;
            }
        }
        return false;
    }

    private static void addBaseMaterials(
        JPanel body,
        UiStyle style,
        BuildExpander.RecipeBranch branch,
        Counts counts
    ) {
        if (branch == null || branch.baseMaterials == null || branch.baseMaterials.isEmpty()) {
            return;
        }
        body.add(Box.createRigidArea(new Dimension(0, 6)));
        boolean bankUnknown = counts != null && counts.show() && counts.inventoryKnown() && !counts.bankKnown();
        String materials = bankUnknown ? "Base materials (bank not checked)" : "Base materials";
        body.add(label(style, materials, "bodyBold", ColorScheme.LIGHT_GRAY_COLOR));
        for (Map.Entry<String, Long> material : branch.baseMaterials.entrySet()) {
            String line = "\u00b7 " + escape(quantityText(material.getKey(), material.getValue()));
            if (!bankUnknown) {
                line = line + ownedSuffix(counts, material.getKey(), material.getValue(), true);
            }
            body.add(html(style, line, "small", MUTED));
        }
    }

    private static List<String> loopedNames(List<BuildExpander.BuildNode> nodes) {
        List<String> names = new ArrayList<>();
        if (nodes == null) {
            return names;
        }
        for (BuildExpander.BuildNode node : nodes) {
            if (node != null && node.cycle && node.name != null && !node.name.isEmpty()) {
                names.add(node.name);
            }
        }
        return names;
    }

    private static boolean hasIngredients(BuildExpander.Result result) {
        for (BuildExpander.RecipeBranch branch : result.recipes) {
            if (!branch.ingredients.isEmpty()) {
                return true;
            }
        }
        return false;
    }

    private static Mark markOf(Marks marks, RecipeInfo recipe) {
        if (marks == null || recipe == null) {
            return Mark.NEUTRAL;
        }
        Mark mark = marks.recipe(recipe);
        return mark == null ? Mark.NEUTRAL : mark;
    }

    private static void addNode(
        JPanel parent,
        UiStyle style,
        BuildExpander.BuildNode node,
        Actions actions,
        Counts counts,
        Marks marks,
        boolean parentUnmet
    ) {
        JPanel block = column();
        int inset = Math.min(Math.max(0, node.depth - 1), 6) * 8;
        if (inset > 0) {
            block.setBorder(BorderFactory.createEmptyBorder(0, inset, 0, 0));
        }
        block.add(row(style, node, actions, counts, parentUnmet));
        Mark childMark = Mark.NEUTRAL;
        List<String> loopedChildren = loopedNames(node.children);
        if (node.expanded && node.recipe != null) {
            childMark = markOf(marks, node.recipe);
            String summary = RecipeText.withLoopedIngredients(RecipeText.summary(node.recipe), loopedChildren);
            if (!summary.isEmpty()) {
                block.add(html(style, RequirementJudge.htmlPrefix(childMark) + escape(summary), "small", childMark == Mark.UNMET ? UNMET : GOOD));
            }
        } else if (node.expanded && !loopedChildren.isEmpty()) {
            block.add(html(style, escape(RecipeText.withLoopedIngredients("", loopedChildren)), "small", MUTED));
        }
        if (node.loading) {
            block.add(label(style, "Loading recipe\u2026", "small", MUTED));
        }
        if (node.otherRecipes > 0 && node.expanded) {
            String extra = node.otherRecipes == 1
                ? "1 other method on this page"
                : node.otherRecipes + " other methods on this page";
            block.add(label(style, extra, "small", MUTED));
        }
        boolean unmetHere = parentUnmet || childMark == Mark.UNMET;
        for (BuildExpander.BuildNode child : node.children) {
            if (!child.cycle) {
                addNode(block, style, child, actions, counts, marks, unmetHere);
            }
        }
        parent.add(block);
    }

    private static JPanel row(UiStyle style, BuildExpander.BuildNode node, Actions actions, Counts counts, boolean unmet) {
        JPanel row = new JPanel(new BorderLayout(4, 0)) {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }

            @Override
            public Dimension getMinimumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(0, preferred.height);
            }
        };
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setAlignmentX(0f);
        JPanel toggleSlot = new JPanel(new BorderLayout());
        toggleSlot.setOpaque(false);
        toggleSlot.setPreferredSize(new Dimension(18, 18));
        toggleSlot.setMinimumSize(new Dimension(18, 18));
        toggleSlot.setMaximumSize(new Dimension(18, 18));
        toggleSlot.putClientProperty("jei.role", "tree-toggle");
        if (node.showExpander) {
            JButton toggle = button(style, node.expanded ? "\u25be" : "\u25b8", "small");
            toggle.setForeground(LINK);
            toggle.setMargin(new java.awt.Insets(0, 0, 0, 0));
            String path = node.path;
            String itemName = node.name;
            toggle.addActionListener(e -> actions.toggle(path, itemName));
            toggle.setPreferredSize(new Dimension(18, 18));
            toggle.setMaximumSize(new Dimension(18, 18));
            toggleSlot.add(toggle, BorderLayout.NORTH);
        }
        row.add(toggleSlot, BorderLayout.WEST);
        JLabel icon = new JLabel() {
            @Override
            public Dimension getPreferredSize() {
                return iconSize(this);
            }

            @Override
            public Dimension getMinimumSize() {
                return iconSize(this);
            }

            @Override
            public void setIcon(javax.swing.Icon image) {
                super.setIcon(image);
                if (getParent() != null) {
                    getParent().revalidate();
                }
            }
        };
        icon.putClientProperty("jei.role", "tree-icon");
        icon.setVerticalAlignment(javax.swing.SwingConstants.TOP);
        icon.setHorizontalAlignment(javax.swing.SwingConstants.CENTER);
        icon.setAlignmentY(0f);
        actions.icon(icon, node.name);
        boolean open = actions.canOpen(node.name);
        String text = quantityText(node.name, node.quantity);
        Color nameColor = unmet ? UNMET : (open ? LINK : ColorScheme.LIGHT_GRAY_COLOR);
        String suffix = "";
        Color suffixColor = nameColor;
        if (counts != null && counts.show() && counts.inventoryKnown()) {
            Long have = counts.have(node.name);
            if (have != null) {
                suffix = OwnedText.haveNeedPlain(have.longValue(), node.quantity, counts.bankKnown());
                suffixColor = OwnedText.haveNeedColor(have.longValue(), node.quantity, counts.bankKnown());
            }
        }
        JPanel lines = new JPanel() {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }

            @Override
            public Dimension getMinimumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(0, preferred.height);
            }
        };
        lines.setLayout(new BoxLayout(lines, BoxLayout.Y_AXIS));
        lines.setOpaque(false);
        lines.setAlignmentX(0f);
        WrappingLabel name = html(style, escape(text), "small", nameColor);
        String tip = suffix.isEmpty() ? text : text + " \u00b7 " + suffix;
        if (counts != null && counts.show() && counts.inventoryKnown() && !counts.bankKnown()) {
            tip = tip + " \u00b7 " + OwnedText.BANK_UNKNOWN_TIP;
        }
        name.setToolTipText(tip);
        lines.add(name);
        WrappingLabel have = null;
        if (!suffix.isEmpty()) {
            have = html(style, escape(suffix), "small", suffixColor);
            have.setToolTipText(tip);
            lines.add(have);
        }
        if (open) {
            String itemName = node.name;
            MouseAdapter opener = new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    actions.openItem(itemName);
                }
            };
            name.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            icon.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            name.addMouseListener(opener);
            icon.addMouseListener(opener);
            if (have != null) {
                have.setCursor(name.getCursor());
                have.addMouseListener(opener);
            }
        }
        JPanel center = new JPanel(new BorderLayout(4, 0)) {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }

            @Override
            public Dimension getMinimumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(0, preferred.height);
            }
        };
        center.setOpaque(false);
        center.setAlignmentX(0f);
        center.add(icon, BorderLayout.WEST);
        center.add(lines, BorderLayout.CENTER);
        row.add(center, BorderLayout.CENTER);
        return row;
    }

    /** Inventory sprites are about 32–36px. The cell must not be shorter than the image. */
    static Dimension iconSize(JLabel icon) {
        int width = 36;
        int height = 36;
        javax.swing.Icon image = icon.getIcon();
        if (image != null) {
            width = Math.max(width, image.getIconWidth());
            height = Math.max(height, image.getIconHeight());
        }
        return new Dimension(width, height);
    }

    private static String ownedSuffix(Counts counts, String itemName, long need, boolean baseMaterial) {
        if (counts == null || !counts.show() || !counts.inventoryKnown()) {
            return "";
        }
        Long have = counts.have(itemName);
        if (have == null) {
            return "";
        }
        boolean shortfall = com.osr.jei.owned.OwnedItems.stillNeeded(have, need) > 0L;
        String fragment = baseMaterial && shortfall
            ? OwnedText.stillNeededHtml(have, need, counts.bankKnown())
            : OwnedText.haveNeedHtml(have, need, counts.bankKnown());
        return " \u00b7 " + fragment;
    }

    static String quantityText(String name, long quantity) {
        if (quantity == 1) {
            return name;
        }
        return name + " \u00d7 " + String.format("%,d", quantity);
    }

    private static JPanel column() {
        JPanel panel = new JPanel() {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }
        };
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setAlignmentX(0f);
        return panel;
    }

    private static JLabel label(UiStyle style, String text, String role, Color color) {
        WrappingLabel label = new WrappingLabel();
        style.apply(label, role);
        label.setForeground(color);
        label.setHtml(escape(text));
        label.setToolTipText(text);
        label.setAlignmentX(0f);
        return label;
    }

    private static WrappingLabel html(UiStyle style, String inner, String role, Color color) {
        WrappingLabel label = new WrappingLabel();
        style.apply(label, role);
        label.setForeground(color);
        label.setHtml(inner);
        label.setAlignmentX(0f);
        return label;
    }

    private static JButton button(UiStyle style, String text, String role) {
        JButton button = new WrappingButton(text);
        style.apply(button, role);
        button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        button.setOpaque(false);
        button.setBorderPainted(false);
        button.setFocusPainted(false);
        button.setContentAreaFilled(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setAlignmentX(0f);
        button.setHorizontalAlignment(javax.swing.SwingConstants.LEFT);
        return button;
    }

    private static String escape(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osr.jei.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;

/**
 * Compact label between Recent and the search-result icons.
 * Same header style as Favourites and Recent: a small gap, then the word.
 */
public final class ResultsHeading {

    public static final String LABEL = "Results";
    private static final Color MUTED = new Color(150, 150, 150);

    private ResultsHeading() {
    }

    public static JPanel create(UiStyle style) {
        JPanel bar = new JPanel() {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }

            @Override
            public Dimension getMinimumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(0, preferred.height);
            }
        };
        bar.setLayout(new BoxLayout(bar, BoxLayout.Y_AXIS));
        bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bar.setOpaque(true);
        bar.setAlignmentX(Component.LEFT_ALIGNMENT);
        bar.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));

        WrappingLabel label = new WrappingLabel();
        label.setName("resultsLabel");
        if (style != null) {
            style.apply(label, "small");
        }
        label.setForeground(MUTED);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        label.setBorder(BorderFactory.createEmptyBorder(0, 0, 2, 0));
        label.setHtml(LABEL);

        bar.add(label);
        return bar;
    }

    public static JLabel label(JPanel heading) {
        return (JLabel) heading.getComponent(0);
    }
}

package com.osr.jei.ui;

import net.runelite.client.ui.PluginPanel;

import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.JViewport;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Rectangle;

/**
 * Vertical stack that tracks the scroll viewport width. A long child cannot
 * make the scroll view wider than the sidebar, so text wraps instead of clipping.
 */
public class ScrollWidthPanel extends JPanel implements javax.swing.Scrollable {

    public ScrollWidthPanel() {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setAlignmentX(LEFT_ALIGNMENT);
    }

    @Override
    public Dimension getPreferredSize() {
        Dimension pref = super.getPreferredSize();
        int width = trackedWidth();
        if (width > 0) {
            return new Dimension(width, pref.height);
        }
        int capped = Math.min(Math.max(pref.width, 0), PluginPanel.PANEL_WIDTH);
        return new Dimension(capped, pref.height);
    }

    @Override
    public Dimension getMinimumSize() {
        Dimension min = super.getMinimumSize();
        return new Dimension(0, min.height);
    }

    @Override
    public Dimension getMaximumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(Integer.MAX_VALUE, preferred.height);
    }

    private int trackedWidth() {
        Container parent = getParent();
        if (parent instanceof JViewport && parent.getWidth() > 0) {
            return parent.getWidth();
        }
        return -1;
    }

    @Override
    public Dimension getPreferredScrollableViewportSize() {
        return new Dimension(PluginPanel.PANEL_WIDTH, 180);
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
        return Math.max(16, visibleRect == null ? 16 : visibleRect.height - 16);
    }

    @Override
    public boolean getScrollableTracksViewportWidth() {
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight() {
        return false;
    }
}

