package com.osr.jei.ui;

import java.util.HashMap;
import java.util.Map;

/**
 * Collapsed or expanded choice for the detail sections of the open item.
 * Every section starts collapsed. A per-section setting can start it open
 * when the item changes. Switching items clears the previous choices.
 */
public final class SectionState {

    public static final String EQUIPMENT = "equipment";
    public static final String SHOPS = "shops";
    public static final String USED_IN = "usedIn";
    public static final String DROPS = "drops";
    public static final String CRAFTING = "crafting";
    public static final String LOCATIONS = "locations";
    public static final String TRADING = "trading";

    private final Map<String, Boolean> expanded = new HashMap<>();

    public boolean expanded(String key) {
        Boolean value = expanded.get(key);
        return value != null && value.booleanValue();
    }

    /** Back to collapsed for every section. Used when the open item changes. */
    public void reset() {
        expanded.clear();
    }

    public void setExpanded(String key, boolean value) {
        if (key == null) {
            return;
        }
        expanded.put(key, Boolean.valueOf(value));
    }

    /** @return the state after the flip */
    public boolean toggle(String key) {
        boolean next = !expanded(key);
        setExpanded(key, next);
        return next;
    }
}

package com.osr.jei.ui;

import com.osr.jei.ironman.TradeCopy;
import com.osr.jei.model.DropEntry;
import com.osr.jei.model.RecipeInfo;
import com.osr.jei.model.ShopEntry;
import com.osr.jei.wiki.LocationNames;

import java.util.List;
import java.util.Locale;

/**
 * One-line headers for detail sections. Shop and crafting headers keep a
 * short summary. The drop header is only the count. A location header is
 * {@code Location: name} for one place and {@code Locations (N)} for more,
 * with no place name in the count.
 */
public final class SectionSummaries {

    private SectionSummaries() {
    }

    public static String shops(List<ShopEntry> shops) {
        int count = shops == null ? 0 : shops.size();
        if (count == 0) {
            return "Shop sources";
        }
        String title = "Shop sources (" + count + ")";
        ShopEntry cheapest = cheapest(shops);
        if (cheapest == null) {
            return title;
        }
        String price = formatPrice(cheapest);
        if (count == 1) {
            return title + " \u00b7 " + price;
        }
        return title + " \u00b7 cheapest " + price;
    }

    public static String drops(List<DropEntry> drops) {
        int count = drops == null ? 0 : drops.size();
        return "Dropped by (" + count + ")";
    }

    public static String uses(List<String> names) {
        int count = names == null ? 0 : names.size();
        if (count == 0) {
            return "Used to craft";
        }
        if (count == 1 && names.get(0) != null && !names.get(0).isEmpty()) {
            return "Used to craft (1) \u00b7 " + names.get(0);
        }
        return "Used to craft (" + count + ")";
    }

    public static String crafting(List<RecipeInfo> recipes) {
        int count = recipes == null ? 0 : recipes.size();
        if (count == 0) {
            return "Crafting";
        }
        String title = "Crafting (" + count + ")";
        String skill = skillLevel(recipes.get(0));
        if (skill.isEmpty()) {
            return title;
        }
        return title + " \u00b7 " + skill;
    }

    public static String equipment(String slot, boolean twoHanded) {
        if (slot == null || slot.trim().isEmpty()) {
            return "Equipment";
        }
        String pretty = slot.trim();
        String lower = pretty.toLowerCase(Locale.ROOT);
        if (twoHanded && !lower.contains("2h") && !lower.contains("two")) {
            pretty = pretty + ", two-handed";
        }
        return "Equipment \u00b7 " + pretty;
    }

    public static String locations(List<String> places) {
        List<String> shown = LocationNames.distinct(places);
        if (shown.isEmpty()) {
            return "Locations";
        }
        if (shown.size() == 1) {
            return "Location: " + shown.get(0);
        }
        return "Locations (" + shown.size() + ")";
    }

    public static String shopPlain(ShopEntry shop, TradeCopy.ShopLine line) {
        String name = shop == null || shop.shopName == null ? "" : shop.shopName;
        String stock = line == null || line.stock == null ? "" : line.stock;
        String price = line == null || line.price == null ? "" : line.price;
        return name + stock + price;
    }

    public static String shopHtml(ShopEntry shop, TradeCopy.ShopLine line) {
        String name = shop == null || shop.shopName == null ? "" : shop.shopName;
        String stock = line == null || line.stock == null ? "" : line.stock;
        String price = line == null || line.price == null ? "" : line.price;
        String color = line == null || line.priceColor == null ? TradeCopy.NEUTRAL : line.priceColor;
        return "<font color='#bebebe'>\u00b7 " + escape(name) + escape(stock) + "</font>"
            + "<font color='" + color + "'>" + keepPriceTogether(escape(price)) + "</font>";
    }

    static ShopEntry cheapest(List<ShopEntry> shops) {
        if (shops == null) {
            return null;
        }
        ShopEntry coins = null;
        for (ShopEntry shop : shops) {
            if (!priced(shop) || !shop.isCoins()) {
                continue;
            }
            if (coins == null || shop.price < coins.price) {
                coins = shop;
            }
        }
        if (coins != null) {
            return coins;
        }
        String currency = null;
        ShopEntry best = null;
        for (ShopEntry shop : shops) {
            if (!priced(shop) || shop.currency.isEmpty()) {
                continue;
            }
            if (currency == null) {
                currency = shop.currency;
            }
            if (!currency.equals(shop.currency)) {
                continue;
            }
            if (best == null || shop.price < best.price) {
                best = shop;
            }
        }
        return best;
    }

    private static boolean priced(ShopEntry shop) {
        return shop != null && shop.sells && shop.price >= 0;
    }

    static String formatPrice(ShopEntry shop) {
        String unit = shop.isCoins() ? "gp" : shop.currency;
        return String.format(Locale.ROOT, "%,d\u00a0%s", shop.price, unit);
    }

    private static String skillLevel(RecipeInfo recipe) {
        if (recipe == null || recipe.skill == null || recipe.skill.isEmpty()) {
            return "";
        }
        if (recipe.level > 0) {
            return recipe.skill + " (Lv. " + recipe.level + ")";
        }
        return recipe.skill;
    }

    /** Keep "4 gp" on one line while still allowing the price to wrap after the shop name. */
    private static String keepPriceTogether(String price) {
        return price.replaceAll("(\\d) ", "$1\u00a0");
    }

    private static String escape(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osr.jei.ui;

import com.osr.jei.ironman.TradeCopy;
import com.osr.jei.model.ShopEntry;

import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

/**
 * One shop: the name is a wiki link, the price is its own column, and map is a separate action.
 */
public final class ShopRows {

    private static final Color LINK = new Color(100, 180, 255);
    private static final Color NAME = new Color(190, 190, 190);
    /** Gold, not the shop-name blue, so the control reads as an action. */
    public static final Color MAP_ACTION = new Color(196, 163, 90);
    public static final String MAP_LINK = "\u2316 Show on map";
    public static final String MAP_PINNED = "\u2316 Pinned. Open the world map to view.";

    private ShopRows() {
    }

    public static JPanel row(
        UiStyle style,
        ShopEntry shop,
        TradeCopy.ShopLine line,
        Runnable openWiki,
        Consumer<WrappingLabel> showMap
    ) {
        JPanel row = new JPanel(new BorderLayout(6, 0)) {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }

            @Override
            public Dimension getMinimumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(0, preferred.height);
            }
        };
        row.setOpaque(false);
        row.setAlignmentX(0f);

        String stock = line == null || line.stock == null ? "" : line.stock.trim();
        String name = shop == null || shop.shopName == null ? "" : shop.shopName;
        String label = stock.isEmpty() ? name : name + " " + stock;
        WrappingLabel title = new WrappingLabel();
        if (style != null) {
            style.apply(title, "small");
        }
        title.setForeground(LINK);
        title.setHtml(escape(label));
        title.setToolTipText("Open the " + name + " wiki page");
        title.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        if (openWiki != null) {
            title.addMouseListener(click(openWiki));
        }

        String priceText = priceText(shop);
        JLabel price = new JLabel(priceText);
        if (style != null) {
            style.apply(price, "small");
        }
        price.setForeground(color(line));
        price.setHorizontalAlignment(JLabel.RIGHT);
        Dimension priceSize = price.getPreferredSize();
        price.setPreferredSize(priceSize);
        price.setMinimumSize(priceSize);

        JPanel text = new JPanel(new BorderLayout(0, 0));
        text.setOpaque(false);
        text.add(title, BorderLayout.CENTER);
        if (showMap != null) {
            WrappingLabel map = mapLink(style);
            map.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    showMap.accept(map);
                }
            });
            text.add(map, BorderLayout.SOUTH);
        }

        row.add(text, BorderLayout.CENTER);
        row.add(price, BorderLayout.EAST);
        row.setToolTipText(name + " " + priceText);
        return row;
    }

    /** Indented, smaller, gold action. Not the same blue as a shop or monster name. */
    public static WrappingLabel mapLink(UiStyle style) {
        WrappingLabel map = new WrappingLabel();
        if (style != null) {
            style.apply(map, "small");
        }
        map.setForeground(MAP_ACTION);
        map.setHtml(MAP_LINK);
        map.setBorder(BorderFactory.createEmptyBorder(0, 16, 2, 0));
        map.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        map.setToolTipText("Pin this place. Open the world map to view it.");
        return map;
    }

    public static String priceText(ShopEntry shop) {
        if (shop == null) {
            return "";
        }
        String unit = shop.isCoins() ? "gp" : shop.currency;
        return String.format(java.util.Locale.ROOT, "%,d %s", shop.price, unit);
    }

    private static Color color(TradeCopy.ShopLine line) {
        if (line == null || line.priceColor == null) {
            return NAME;
        }
        try {
            return Color.decode(line.priceColor);
        } catch (NumberFormatException e) {
            return NAME;
        }
    }

    private static MouseAdapter click(Runnable action) {
        return new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                action.run();
            }
        };
    }

    private static String escape(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osr.jei.ui;

import com.osr.jei.model.ShopEntry;

import java.util.ArrayList;
