/**
 * Shop rows for the item currently open. Each row is that item's stock in
 * that shop. A zero-stock row is omitted. The same shop still appears on
 * another item when that item's stock there is above zero or unlimited.
 */
public final class ShopSources {

    private ShopSources() {
    }

    public static List<ShopEntry> visible(List<ShopEntry> shops) {
        if (shops == null || shops.isEmpty()) {
            return Collections.emptyList();
        }
        List<ShopEntry> shown = new ArrayList<>();
        for (ShopEntry shop : shops) {
            if (shop == null || !shop.sells || shop.stock == 0) {
                continue;
            }
            shown.add(shop);
        }
        return shown;
    }
}

package com.osr.jei.ui;

/** Pure layout math for the sidebar split between results and item details. */
public final class SplitLayout {

    public static final int MIN_DETAIL_PERCENT = 25;
    public static final int MAX_DETAIL_PERCENT = 75;

    private SplitLayout() {
    }

    public static int clampDetailPercent(int value) {
        return Math.max(MIN_DETAIL_PERCENT, Math.min(MAX_DETAIL_PERCENT, value));
    }

    /** Pixel offset of the divider from the top of a vertical split of {@code height}. */
    public static int topDividerPx(int height, int dividerSize, int detailPercent) {
        if (height <= 0) {
            return 0;
        }
        int pct = clampDetailPercent(detailPercent);
        int top = height - (height * pct / 100) - Math.max(0, dividerSize);
        return Math.max(0, top);
    }

    /** Detail-pane share implied by a divider the user dragged. */
    public static int detailPercentFromDivider(int height, int dividerLocation) {
        if (height <= 0) {
            return 45;
        }
        int topPct = (int) Math.round(100.0 * dividerLocation / height);
        topPct = Math.max(0, Math.min(100, topPct));
        return clampDetailPercent(100 - topPct);
    }
}

package com.osr.jei.ui;

import javax.swing.JToggleButton;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/**
 * 24px favourite control. It stays in the tab order and toggles with Space.
 */
public class StarButton extends JToggleButton {

    public static final int SIZE = 24;

    private static final Color GOLD = new Color(220, 185, 75);
    private static final Color HOVER = new Color(70, 62, 32);
    private static final Color FOCUS = new Color(255, 152, 31);

    public StarButton(String tooltip) {
        setToolTipText(tooltip);
        setPreferredSize(new Dimension(SIZE, SIZE));
        setMinimumSize(new Dimension(SIZE, SIZE));
        setMaximumSize(new Dimension(SIZE, SIZE));
        setFocusable(true);
        setOpaque(false);
        setContentAreaFilled(false);
        setBorderPainted(false);
        setRolloverEnabled(true);
        setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
    }

    @Override
    public Dimension getPreferredSize() {
        return new Dimension(SIZE, SIZE);
    }

    @Override
    protected void paintComponent(Graphics graphics) {
        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        if (getModel().isRollover() || getModel().isPressed() || isSelected()) {
            g.setColor(HOVER);
            g.fillRoundRect(1, 1, getWidth() - 2, getHeight() - 2, 6, 6);
        }
        if (isFocusOwner()) {
            g.setColor(FOCUS);
            g.drawRoundRect(1, 1, getWidth() - 3, getHeight() - 3, 6, 6);
        }
        int[] xs = starXs(getWidth() / 2, 9);
        int[] ys = starYs(getHeight() / 2, 9);
        if (isSelected()) {
            g.setColor(GOLD);
            g.fillPolygon(xs, ys, xs.length);
        } else {
            g.setColor(GOLD);
            g.drawPolygon(xs, ys, xs.length);
        }
        g.dispose();
    }

    private static int[] starXs(int cx, int r) {
        int[] xs = new int[10];
        for (int i = 0; i < 10; i++) {
            double angle = Math.toRadians(-90 + i * 36);
            int radius = (i % 2 == 0) ? r : r / 2;
            xs[i] = cx + (int) Math.round(Math.cos(angle) * radius);
        }
        return xs;
    }

    private static int[] starYs(int cy, int r) {
        int[] ys = new int[10];
        for (int i = 0; i < 10; i++) {
            double angle = Math.toRadians(-90 + i * 36);
            int radius = (i % 2 == 0) ? r : r / 2;
            ys[i] = cy + (int) Math.round(Math.sin(angle) * radius);
        }
        return ys;
    }
}

package com.osr.jei.ui;

import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Short labelled rows for Grand Exchange figures. Keys share one width and
 * values wrap in the space that is left, so a narrow sidebar cannot clip them.
 */
public final class StatGrid extends ScrollWidthPanel {

    public static final class Row {
        public final String key;
        public final String value;
        public final Color color;

        public Row(String key, String value, Color color) {
            this.key = key == null ? "" : key;
            this.value = value == null ? "" : value;
            this.color = color == null ? Color.LIGHT_GRAY : color;
        }

        public boolean fullWidth() {
            return key.isEmpty();
        }
    }

    private UiStyle style;
    private List<Row> rows = Collections.emptyList();

    public StatGrid(UiStyle style) {
        this.style = style;
        setOpaque(false);
        setAlignmentX(LEFT_ALIGNMENT);
    }

    public void useStyle(UiStyle style) {
        if (style != null) {
            this.style = style;
        }
    }

    public void setRows(List<Row> rows) {
        this.rows = rows == null ? Collections.emptyList() : new ArrayList<>(rows);
        rebuild();
    }

    private void rebuild() {
        removeAll();
        if (rows.isEmpty()) {
            setVisible(false);
            return;
        }
        int keyWidth = keyColumnWidth();
        for (Row row : rows) {
            add(row.fullWidth() ? fullWidth(row) : keyed(row, keyWidth));
        }
        setVisible(true);
    }

    private int keyColumnWidth() {
        if (style == null) {
            return 0;
        }
        FontMetrics metrics = getFontMetrics(style.forRole("small"));
        int width = 0;
        for (Row row : rows) {
            if (!row.fullWidth()) {
                width = Math.max(width, metrics.stringWidth(row.key));
            }
        }
        return width;
    }

    private JPanel fullWidth(Row row) {
        JPanel line = rowPanel();
        WrappingLabel value = valueLabel(row.value, row.color);
        value.setToolTipText(row.value);
        line.add(value, BorderLayout.CENTER);
        return line;
    }

    private JPanel keyed(Row row, int keyWidth) {
        JPanel line = rowPanel();
        JLabel key = new JLabel(row.key);
        if (style != null) {
            style.apply(key, "small");
        }
        key.setForeground(new Color(150, 150, 150));
        Dimension keySize = new Dimension(keyWidth, key.getPreferredSize().height);
        key.setPreferredSize(keySize);
        key.setMinimumSize(keySize);
        WrappingLabel value = valueLabel(row.value, row.color);
        String tip = row.key + ": " + row.value;
        value.setToolTipText(tip);
        key.setToolTipText(tip);
        line.add(key, BorderLayout.WEST);
        line.add(value, BorderLayout.CENTER);
        return line;
    }

    private WrappingLabel valueLabel(String value, Color color) {
        WrappingLabel label = new WrappingLabel();
        if (style != null) {
            style.apply(label, "small");
        }
        label.setForeground(color);
        label.setHtml(escape(value));
        return label;
    }

    private static JPanel rowPanel() {
        JPanel line = new JPanel(new BorderLayout(6, 0)) {
            @Override
            public Dimension getMaximumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(Integer.MAX_VALUE, preferred.height);
            }

            @Override
            public Dimension getMinimumSize() {
                Dimension preferred = getPreferredSize();
                return new Dimension(0, preferred.height);
            }
        };
        line.setOpaque(false);
        line.setAlignmentX(LEFT_ALIGNMENT);
        return line;
    }

    private static String escape(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osr.jei.ui;

import net.runelite.client.ui.FontManager;

import javax.swing.JComponent;
import javax.swing.UIManager;
import java.awt.Font;

/**
 * Fonts for the sidebar. The default family is RuneLite's UI font.
 * Every label reads its size from here instead of calling {@code deriveFont} ad hoc.
 */
public final class UiStyle {

    public static final String ROLE = "jei.font";
    public static final String WRAP = "jei.wrap";

    public final Font title;
    public final Font body;
    public final Font bodyBold;
    public final Font small;
    public final Font price;
    public final Font button;
    public final boolean wrap;

    public UiStyle(Font title, Font body, Font bodyBold, Font small, Font price, Font button) {
        this(title, body, bodyBold, small, price, button, true);
    }

    public UiStyle(Font title, Font body, Font bodyBold, Font small, Font price, Font button, boolean wrap) {
        this.title = title;
        this.body = body;
        this.bodyBold = bodyBold;
        this.small = small;
        this.price = price;
        this.button = button;
        this.wrap = wrap;
    }

    public UiStyle withWrap(boolean wrap) {
        return new UiStyle(title, body, bodyBold, small, price, button, wrap);
    }

    public static UiStyle from(int fontSize, FontStyleChoice styleChoice, FontFamilyChoice familyChoice) {
        int size = Math.max(10, Math.min(22, fontSize));
        int style = styleChoice == FontStyleChoice.BOLD ? Font.BOLD : Font.PLAIN;
        Font base = family(familyChoice, size, style);
        return new UiStyle(
            base.deriveFont(Font.BOLD, size + 1f),
            base.deriveFont(style, (float) size),
            base.deriveFont(Font.BOLD, (float) size),
            base.deriveFont(style, Math.max(9f, size - 1f)),
            base.deriveFont(Font.BOLD, (float) size),
            base.deriveFont(style, (float) size)
        );
    }

    public Font forRole(String role) {
        if (role == null) {
            return body;
        }
        switch (role) {
            case "title":
                return title;
            case "bodyBold":
                return bodyBold;
            case "small":
                return small;
            case "price":
                return price;
            case "button":
                return button;
            case "body":
            default:
                return body;
        }
    }

    public void apply(JComponent component, String role) {
        component.putClientProperty(ROLE, role);
        component.putClientProperty(WRAP, wrap);
        component.setFont(forRole(role));
    }

    public void applyTree(java.awt.Component root) {
        if (root instanceof JComponent) {
            JComponent component = (JComponent) root;
            Object role = component.getClientProperty(ROLE);
            if (role instanceof String) {
                component.putClientProperty(WRAP, wrap);
                root.setFont(forRole((String) role));
            }
        }
        if (root instanceof java.awt.Container) {
            for (java.awt.Component child : ((java.awt.Container) root).getComponents()) {
                applyTree(child);
            }
        }
    }

    private static Font family(FontFamilyChoice choice, int size, int style) {
        if (choice == null || choice == FontFamilyChoice.DEFAULT) {
            Font ui = FontManager.getDefaultFont();
            if (ui == null) {
                ui = UIManager.getFont("Label.font");
            }
            if (ui == null) {
                return new Font(Font.SANS_SERIF, style, size);
            }
            return ui.deriveFont(style, (float) size);
        }
        String name;
        switch (choice) {
            case SERIF:
                name = Font.SERIF;
                break;
            case MONOSPACED:
                name = Font.MONOSPACED;
                break;
            case SANS_SERIF:
            default:
                name = Font.SANS_SERIF;
                break;
        }
        return new Font(name, style, size);
    }
}

package com.osr.jei.ui;

import net.runelite.client.ui.PluginPanel;

import java.awt.Component;
import java.awt.Container;
import java.awt.Insets;
import javax.swing.JViewport;
import java.awt.BorderLayout;
import java.awt.LayoutManager;

/**
 * Width a label should wrap or ellipsize to. Walks up to the scroll viewport
 * and subtracts borders plus any west/east siblings, so a resize of the
 * sidebar changes the limit on the next layout without a second measurement pass.
 */
public final class WidthLimit {

    private static final int FALLBACK = PluginPanel.PANEL_WIDTH - 24;
    private static final int SAFETY = 4;

    private WidthLimit() {
    }

    public static int of(Component component) {
        if (component == null) {
            return FALLBACK;
        }
        int fromViewport = fromViewport(component);
        int laidOut = narrowestLaidOut(component);
        if (fromViewport > 20 && laidOut > 20) {
            return Math.min(fromViewport, laidOut);
        }
        if (laidOut > 20) {
            return laidOut;
        }
        if (fromViewport > 20) {
            return fromViewport;
        }
        int own = component.getWidth();
        Insets insets = insetsOf(component);
        int inner = own - insets.left - insets.right;
        if (inner > 20) {
            return inner;
        }
        return FALLBACK;
    }

    /** Smallest already-sized ancestor, so a line cannot prefer a width past the row. */
    private static int narrowestLaidOut(Component component) {
        int best = -1;
        int chrome = 0;
        Component child = component;
        Container parent = component.getParent();
        if (component instanceof Container) {
            chrome += horizontalInsets((Container) component);
        }
        int guard = 0;
        while (parent != null && guard++ < 24) {
            if (parent.getWidth() > 20) {
                int inner = parent.getWidth() - horizontalInsets(parent) - chrome - siblingBreadth(parent, child);
                if (inner > 20) {
                    best = best < 0 ? inner : Math.min(best, inner);
                }
            }
            chrome += horizontalInsets(parent);
            chrome += siblingBreadth(parent, child);
            child = parent;
            parent = parent.getParent();
        }
        return best;
    }

    private static int fromViewport(Component component) {
        int chrome = 0;
        Component child = component;
        Container parent = component.getParent();
        Insets self = insetsOf(component);
        chrome += self.left + self.right;
        int guard = 0;
        while (parent != null && guard++ < 24) {
            if (parent instanceof JViewport) {
                int width = parent.getWidth();
                if (width <= 20) {
                    return -1;
                }
                return Math.max(40, width - chrome - SAFETY);
            }
            chrome += horizontalInsets(parent);
            chrome += siblingBreadth(parent, child);
            child = parent;
            parent = parent.getParent();
        }
        return -1;
    }

    private static int siblingBreadth(Container parent, Component child) {
        LayoutManager layout = parent.getLayout();
        if (!(layout instanceof BorderLayout)) {
            return 0;
        }
        BorderLayout border = (BorderLayout) layout;
        int extra = 0;
        Component west = border.getLayoutComponent(parent, BorderLayout.WEST);
        Component east = border.getLayoutComponent(parent, BorderLayout.EAST);
        if (west != null && west != child && west.isVisible()) {
            extra += west.getPreferredSize().width + border.getHgap();
        }
        if (east != null && east != child && east.isVisible()) {
            extra += east.getPreferredSize().width + border.getHgap();
        }
        return extra;
    }

    private static int horizontalInsets(Container container) {
        Insets insets = container.getInsets();
        if (insets == null) {
            return 0;
        }
        return insets.left + insets.right;
    }

    private static Insets insetsOf(Component component) {
        if (component instanceof Container) {
            Insets insets = ((Container) component).getInsets();
            if (insets != null) {
                return insets;
            }
        }
        return new Insets(0, 0, 0, 0);
    }
}

package com.osr.jei.ui;

import javax.swing.JButton;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import java.awt.Dimension;

/**
 * Link-styled button whose label wraps to the sidebar width.
 * {@link #getText()} stays the plain label so callers can still read it.
 */
public class WrappingButton extends JButton {

    private String plain = "";
    private int laidOutWidth = -1;
    private View sizedView;

    public WrappingButton(String text) {
        super();
        setAlignmentX(LEFT_ALIGNMENT);
        setText(text);
    }

    @Override
    public void setText(String text) {
        String next = text == null ? "" : text;
        if (next.startsWith("<html>")) {
            plain = next;
            laidOutWidth = -1;
            sizedView = null;
            super.setText(next);
            return;
        }
        plain = next;
        laidOutWidth = -1;
        sizedView = null;
        super.setText("<html>" + escape(next) + "</html>");
    }

    /** Plain label, without the HTML wrapper used for wrapping. */
    public String plainText() {
        return plain;
    }

    @Override
    public void setFont(java.awt.Font font) {
        super.setFont(font);
        laidOutWidth = -1;
        sizedView = null;
    }

    @Override
    public Dimension getPreferredSize() {
        if (isPreferredSizeSet()) {
            return super.getPreferredSize();
        }
        int limit = WidthLimit.of(this);
        View view = (View) getClientProperty(BasicHTML.propertyKey);
        if (view == null) {
            Dimension plainSize = super.getPreferredSize();
            return new Dimension(Math.min(plainSize.width, limit), plainSize.height);
        }
        int unwrapped = (int) Math.ceil(view.getPreferredSpan(View.X_AXIS));
        int width = Math.max(1, Math.min(unwrapped, limit));
        if (view != sizedView || width != laidOutWidth) {
            view.setSize(width, 0);
            sizedView = view;
            laidOutWidth = width;
        }
        int height = (int) Math.ceil(view.getPreferredSpan(View.Y_AXIS));
        return new Dimension(width, Math.max(1, height));
    }

    @Override
    public Dimension getMinimumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(0, preferred.height);
    }

    @Override
    public Dimension getMaximumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(Integer.MAX_VALUE, preferred.height);
    }

    private static String escape(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osr.jei.ui;

import net.runelite.client.ui.PluginPanel;

import javax.swing.JLabel;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import java.awt.Dimension;
import java.awt.Insets;

/**
 * HTML label whose preferred height follows the current sidebar width,
 * so names and shop lines wrap instead of clipping when the sidebar is resized.
 */
public class WrappingLabel extends JLabel {

    private int laidOutWidth = -1;
    private int settledWidth = -1;
    private View sizedView;
    private String innerHtml = "";
    private boolean htmlMode;

    public WrappingLabel() {
        setAlignmentX(LEFT_ALIGNMENT);
    }

    public void setHtml(String innerHtml) {
        htmlMode = true;
        this.innerHtml = innerHtml == null ? "" : innerHtml;
        publish();
    }

    @Override
    public void setText(String text) {
        super.setText(text);
        laidOutWidth = -1;
        sizedView = null;
        settledWidth = -1;
    }

    @Override
    public void setBounds(int x, int y, int width, int height) {
        super.setBounds(x, y, width, height);
        if (!htmlMode || width <= 0 || width == settledWidth) {
            return;
        }
        int inner = innerWidth(width);
        if (inner <= 20) {
            return;
        }
        int needed = wrappedHeight(inner);
        settledWidth = width;
        if (Math.abs(needed - height) > 2) {
            revalidate();
        }
    }

    @Override
    public void setFont(java.awt.Font font) {
        super.setFont(font);
        laidOutWidth = -1;
        sizedView = null;
        if (htmlMode) {
            publish();
        }
    }

    private void publish() {
        String body = wraps() ? innerHtml : "<nobr>" + innerHtml + "</nobr>";
        setText("<html>" + body + "</html>");
    }

    private boolean wraps() {
        return !Boolean.FALSE.equals(getClientProperty(UiStyle.WRAP));
    }

    @Override
    public Dimension getPreferredSize() {
        int width = innerWidth(getWidth());
        if (width <= 20) {
            width = WidthLimit.of(this);
        }
        if (width <= 0) {
            width = PluginPanel.PANEL_WIDTH - 24;
        }
        View view = (View) getClientProperty(BasicHTML.propertyKey);
        if (view == null) {
            Dimension plain = super.getPreferredSize();
            return new Dimension(Math.min(plain.width, width), plain.height);
        }
        int layoutWidth = width;
        if (!wraps()) {
            layoutWidth = Math.max(width, (int) Math.ceil(view.getPreferredSpan(View.X_AXIS)));
        }
        if (view != sizedView || layoutWidth != laidOutWidth) {
            view.setSize(layoutWidth, 0);
            sizedView = view;
            laidOutWidth = layoutWidth;
        }
        int height = (int) Math.ceil(view.getPreferredSpan(View.Y_AXIS));
        return new Dimension(wraps() ? width : Math.min(layoutWidth, width), Math.max(1, height));
    }

    private int wrappedHeight(int innerWidth) {
        View view = (View) getClientProperty(BasicHTML.propertyKey);
        if (view == null) {
            return Math.max(1, getFontMetrics(getFont()).getHeight());
        }
        int layoutWidth = innerWidth;
        if (!wraps()) {
            layoutWidth = Math.max(innerWidth, (int) Math.ceil(view.getPreferredSpan(View.X_AXIS)));
        }
        view.setSize(layoutWidth, 0);
        sizedView = view;
        laidOutWidth = layoutWidth;
        return Math.max(1, (int) Math.ceil(view.getPreferredSpan(View.Y_AXIS)));
    }

    private int innerWidth(int width) {
        if (width <= 0) {
            return 0;
        }
        Insets insets = getInsets();
        if (insets == null) {
            return width;
        }
        return Math.max(0, width - insets.left - insets.right);
    }

    @Override
    public Dimension getMinimumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(0, preferred.height);
    }

    @Override
    public Dimension getMaximumSize() {
        Dimension preferred = getPreferredSize();
        return new Dimension(Integer.MAX_VALUE, preferred.height);
    }
}

package com.osr.jei.wiki;

import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Small access-ordered cache. The least recently used entry is dropped
 * when {@code maxSize} is exceeded. Session-long wiki results stay bounded.
 */
public final class BoundedCache<K, V> {

    private final int maxSize;
    private final LinkedHashMap<K, V> map;

    public BoundedCache(int maxSize) {
        this.maxSize = Math.max(1, maxSize);
        this.map = new LinkedHashMap<>(16, 0.75f, true);
    }

    public synchronized V get(K key) {
        return map.get(key);
    }

    public synchronized void put(K key, V value) {
        map.put(key, value);
        while (map.size() > maxSize) {
            Iterator<Map.Entry<K, V>> it = map.entrySet().iterator();
            it.next();
            it.remove();
        }
    }

    public synchronized int size() {
        return map.size();
    }
}

package com.osr.jei.wiki;

import com.osr.jei.model.DropEntry;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Parses the {@code item-drops} table from an "Item sources" section. */
public final class DropTableParser {

    /** {@code drops-sailing}, {@code drops-combat}, {@code drops-reward}, and the other level icons. */
    private static final Pattern LEVEL_KIND = Pattern.compile("class=\"drops-([a-z]+)\"");

    private DropTableParser() {
    }

    public static List<DropEntry> parse(String html) {
        if (html == null || html.isEmpty()) {
            return Collections.emptyList();
        }
        int marker = html.toLowerCase(Locale.ROOT).indexOf("item-drops");
        if (marker < 0) {
            return Collections.emptyList();
        }
        String lower = html.toLowerCase(Locale.ROOT);
        int tStart = lower.lastIndexOf("<table", marker);
        if (tStart < 0) {
            return Collections.emptyList();
        }
        int tEnd = lower.indexOf("</table>", marker);
        if (tEnd < 0) {
            return Collections.emptyList();
        }
        String table = html.substring(tStart, tEnd + 8);
        int tbodyStart = lowerTable(table).indexOf("<tbody>");
        if (tbodyStart >= 0) {
            int tbodyEnd = lowerTable(table).indexOf("</tbody>", tbodyStart);
            table = tbodyEnd >= 0
                ? table.substring(tbodyStart, tbodyEnd + 8)
                : table.substring(tbodyStart);
        }

        List<DropEntry> drops = new ArrayList<>();
        int pos = 0;
        String tableLower = lowerTable(table);
        while (true) {
            int rowStart = tableLower.indexOf("<tr", pos);
            if (rowStart < 0) {
                break;
            }
            int rowEnd = tableLower.indexOf("</tr>", rowStart);
            if (rowEnd < 0) {
                break;
            }
            String row = table.substring(rowStart, rowEnd + 5);
            pos = rowEnd + 5;
            if (!row.toLowerCase(Locale.ROOT).contains("<td")) {
                continue;
            }
            List<String> cells = Html.cellInner(row);
            if (cells.size() < 3) {
                continue;
            }
            String source = Html.strip(cells.get(0));
            String levelCell = cells.size() > 1 ? cells.get(1) : "";
            String level = plain(levelCell);
            String quantity = cells.size() > 2 ? plain(cells.get(2)) : "";
            String rate = cells.size() > 3 ? plain(cells.get(3)) : "";
            if (source.isEmpty()) {
                continue;
            }
            DropEntry drop = new DropEntry();
            drop.setSource(source);
            drop.setLevel(level);
            drop.setLevelKind(levelKind(levelCell));
            drop.setQuantity(quantity.isEmpty() ? "?" : quantity);
            drop.setRate(rate);
            drop.setRarity("");
            drops.add(drop);
        }
        return drops;
    }

    private static String lowerTable(String table) {
        return table.toLowerCase(Locale.ROOT);
    }

    static String levelKind(String cellHtml) {
        if (cellHtml == null || cellHtml.isEmpty()) {
            return "";
        }
        Matcher matcher = LEVEL_KIND.matcher(cellHtml.toLowerCase(Locale.ROOT));
        return matcher.find() ? matcher.group(1) : "";
    }

    private static String plain(String html) {
        return Html.strip(html)
            .replace('\u2013', '-')
            .replace('\u2014', '-')
            .replace('\u2212', '-');
    }
}

package com.osr.jei.wiki;

import com.osr.jei.model.EquipmentStats;

import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Parses {@code {{Infobox Bonuses}}} and item weight from cached wikitext. */
public final class EquipmentParser {

    private EquipmentParser() {
    }

    public static Optional<EquipmentStats> parseStats(String wikitext) {
        if (wikitext == null || wikitext.isEmpty()) {
            return Optional.empty();
        }
        int start = first(wikitext, "infobox bonuses");
        if (start < 0) {
            return Optional.empty();
        }
        String block = WikiText.extractTemplateBlock(wikitext, start);
        if (block == null) {
            return Optional.empty();
        }
        Map<String, String> p = WikiText.parseParams(block);
        String slot = WikiText.clean(p.getOrDefault("slot", ""));
        if (slot.isEmpty()) {
            return Optional.empty();
        }
        int speed = WikiText.firstInt(p.getOrDefault("aspeed", p.getOrDefault("speed", "0")));
        return Optional.of(new EquipmentStats(
            WikiText.signedInt(p.getOrDefault("astab", "0")),
            WikiText.signedInt(p.getOrDefault("aslash", "0")),
            WikiText.signedInt(p.getOrDefault("acrush", "0")),
            WikiText.signedInt(p.getOrDefault("amagic", "0")),
            WikiText.signedInt(p.getOrDefault("arange", "0")),
            WikiText.signedInt(p.getOrDefault("dstab", "0")),
            WikiText.signedInt(p.getOrDefault("dslash", "0")),
            WikiText.signedInt(p.getOrDefault("dcrush", "0")),
            WikiText.signedInt(p.getOrDefault("dmagic", "0")),
            WikiText.signedInt(p.getOrDefault("drange", "0")),
            WikiText.signedInt(p.getOrDefault("str", "0")),
            WikiText.signedInt(p.getOrDefault("rstr", "0")),
            WikiText.signedInt(stripPercent(p.getOrDefault("mdmg", "0"))),
            WikiText.signedInt(p.getOrDefault("prayer", "0")),
            slot,
            speed
        ));
    }

    /** Item weight in kilograms, or {@link Double#NaN} when the page has no weight. */
    public static double parseWeight(String wikitext) {
        if (wikitext == null || wikitext.isEmpty()) {
            return Double.NaN;
        }
        int start = first(wikitext, "infobox item");
        if (start < 0) {
            return Double.NaN;
        }
        String block = WikiText.extractTemplateBlock(wikitext, start);
        if (block == null) {
            return Double.NaN;
        }
        Map<String, String> p = WikiText.parseParams(block);
        String raw = WikiText.clean(p.getOrDefault("weight", ""));
        if (raw.isEmpty()) {
            return Double.NaN;
        }
        try {
            return Double.parseDouble(raw.replace(",", ""));
        } catch (NumberFormatException e) {
            return Double.NaN;
        }
    }

    private static String stripPercent(String s) {
        return s == null ? "0" : s.replace("%", "").trim();
    }

    private static int first(String wikitext, String templateName) {
        List<Integer> hits = WikiText.findTemplates(wikitext, templateName);
        return hits.isEmpty() ? -1 : hits.get(0);
    }
}

package com.osr.jei.wiki;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Small HTML helpers shared by the wiki table parsers.
 * These operate on fragments from the MediaWiki parse API, not arbitrary HTML.
 */
public final class Html {

    private static final Pattern DATA_SORT = Pattern.compile("data-sort-value=\"([^\"]*)\"");

    private Html() {
    }

    /** Turns line-break tags into spaces before other tags are stripped. */
    public static String breaksToSpaces(String html) {
        if (html == null || html.isEmpty()) {
            return "";
        }
        return html.replaceAll("(?i)<br\\s*/?>", " ");
    }

    public static String strip(String html) {
        if (html == null || html.isEmpty()) {
            return "";
        }
        String text = breaksToSpaces(html).replaceAll("<[^>]+>", "");
        text = text.replace("&amp;", "&")
            .replace("&lt;", "<")
            .replace("&gt;", ">")
            .replace("&nbsp;", " ")
            .replace("&#160;", " ")
            .replace("&ndash;", "–")
            .replace("&mdash;", "—")
            .replace("&#91;", "[")
            .replace("&#93;", "]");
        return text.trim().replaceAll("\\s+", " ");
    }

    /**
     * Returns each {@code <tag>...</tag>} element, including its outer tags.
     * Nested elements of the same tag are not supported; wiki table cells are flat.
     */
    public static List<String> elements(String row, String tag) {
        List<String> cells = new ArrayList<>();
        String open = "<" + tag;
        String close = "</" + tag + ">";
        int pos = 0;
        while (true) {
            int start = indexOfIgnoreCase(row, open, pos);
            if (start < 0) {
                break;
            }
            int end = indexOfIgnoreCase(row, close, start);
            if (end < 0) {
                break;
            }
            cells.add(row.substring(start, end + close.length()));
            pos = end + close.length();
        }
        return cells;
    }

    /** Inner HTML of each cell, excluding the outer {@code <td>} wrapper. */
    public static List<String> cellInner(String row) {
        List<String> cells = new ArrayList<>();
        int pos = 0;
        while (true) {
            int start = indexOfIgnoreCase(row, "<td", pos);
            if (start < 0) {
                break;
            }
            int closeGt = row.indexOf('>', start);
            if (closeGt < 0) {
                break;
            }
            int end = indexOfIgnoreCase(row, "</td>", closeGt);
            if (end < 0) {
                break;
            }
            cells.add(row.substring(closeGt + 1, end));
            pos = end + 5;
        }
        return cells;
    }

    public static String linkText(String cell) {
        int aStart = indexOfIgnoreCase(cell, "<a ", 0);
        if (aStart < 0) {
            aStart = indexOfIgnoreCase(cell, "<a\n", 0);
        }
        if (aStart < 0) {
            return "";
        }
        int gt = cell.indexOf('>', aStart);
        if (gt < 0) {
            return "";
        }
        int end = indexOfIgnoreCase(cell, "</a>", gt);
        if (end < 0) {
            return "";
        }
        return strip(cell.substring(gt + 1, end)).trim();
    }

    public static String headerLabel(String thHtml) {
        return strip(thHtml).toLowerCase(Locale.ROOT).trim();
    }

    /**
     * Reads {@code data-sort-value} when present, otherwise the first integer in the visible text.
     * Scientific values such as {@code 10e50} and the infinity glyph map to {@link Integer#MAX_VALUE}.
     *
     * @param whenMissing returned when the cell has no number (N/A, blank)
     */
    public static int sortNumber(String cellHtml, int whenMissing) {
        if (cellHtml == null || cellHtml.isEmpty()) {
            return whenMissing;
        }
        if (isInfinite(cellHtml)) {
            return Integer.MAX_VALUE;
        }
        Matcher sort = DATA_SORT.matcher(cellHtml);
        if (sort.find()) {
            Integer parsed = parseSortToken(sort.group(1));
            if (parsed != null) {
                return parsed;
            }
        }
        String text = strip(cellHtml).replace(",", "");
        if (text.isEmpty() || text.equalsIgnoreCase("n/a") || text.equalsIgnoreCase("na")) {
            return whenMissing;
        }
        if (isInfinite(text)) {
            return Integer.MAX_VALUE;
        }
        Matcher digits = Pattern.compile("\\d+").matcher(text);
        if (!digits.find()) {
            return whenMissing;
        }
        try {
            return Integer.parseInt(digits.group());
        } catch (NumberFormatException e) {
            return whenMissing;
        }
    }

    private static boolean isInfinite(String raw) {
        String lower = raw.toLowerCase(Locale.ROOT);
        return lower.contains("∞")
            || lower.contains("infinity")
            || lower.contains("10e50")
            || lower.contains("10e99");
    }

    private static Integer parseSortToken(String raw) {
        if (raw == null) {
            return null;
        }
        String v = raw.trim().replace(",", "");
        if (v.isEmpty()) {
            return null;
        }
        if (isInfinite(v) || v.equalsIgnoreCase("inf")) {
            return Integer.MAX_VALUE;
        }
        try {
            if (v.toLowerCase(Locale.ROOT).contains("e")) {
                double d = Double.parseDouble(v);
                if (Double.isInfinite(d) || d > Integer.MAX_VALUE) {
                    return Integer.MAX_VALUE;
                }
                if (d < 0) {
                    return null;
                }
                return (int) d;
            }
            long n = Long.parseLong(v);
            if (n > Integer.MAX_VALUE) {
                return Integer.MAX_VALUE;
            }
            if (n < 0) {
                return null;
            }
            return (int) n;
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private static int indexOfIgnoreCase(String haystack, String needle, int from) {
        if (haystack == null || needle == null) {
            return -1;
        }
        return haystack.toLowerCase(Locale.ROOT).indexOf(needle.toLowerCase(Locale.ROOT), from);
    }
}

package com.osr.jei.wiki;

import java.util.Locale;

/**
 * Cuts one section out of a full MediaWiki parse ({@code prop=text}).
 * Headings look like {@code <h2 id="Shop_locations">} inside {@code mw-heading} divs.
 * The table of contents links to {@code #Shop_locations} and must not be treated as the section.
 */
public final class HtmlSections {

    private HtmlSections() {
    }

    public static String sliceById(String html, String headlineId) {
        if (html == null || html.isEmpty() || headlineId == null || headlineId.isEmpty()) {
            return "";
        }
        String needle = "id=\"" + headlineId + "\"";
        int idAt = html.indexOf(needle);
        if (idAt < 0) {
            return "";
        }
        int headingAt = -1;
        int level = 0;
        for (int lv = 2; lv <= 6; lv++) {
            int at = html.lastIndexOf("<h" + lv, idAt);
            if (at > headingAt) {
                headingAt = at;
                level = lv;
            }
        }
        if (headingAt < 0 || level == 0) {
            return "";
        }
        int start = includeHeadingDiv(html, headingAt);
        int end = html.length();
        int searchFrom = idAt + needle.length();
        String lower = html.toLowerCase(Locale.ROOT);
        for (int lv = 2; lv <= level; lv++) {
            int found = lower.indexOf("<h" + lv, searchFrom);
            if (found >= 0) {
                found = includeHeadingDiv(html, found);
                if (found < end) {
                    end = found;
                }
            }
        }
        if (end <= start) {
            return "";
        }
        return html.substring(start, end);
    }

    private static int includeHeadingDiv(String html, int headingAt) {
        int div = html.lastIndexOf("<div", headingAt);
        if (div >= 0 && headingAt - div < 90) {
            String between = html.substring(div, headingAt);
            if (between.contains("mw-heading")) {
                return div;
            }
        }
        return headingAt;
    }
}

package com.osr.jei.wiki;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Display names for wiki location cells. {@code {{FloorNumber|uk=1}}} survives
 * ordinary template cleanup as the text {@code uk=1}, which is not a place name.
 */
public final class LocationNames {

    private static final Pattern UK_PARAM = Pattern.compile("(?i)\\buk\\s*=\\s*[^\\s),]+");
    private static final Pattern EMPTY_PARENS = Pattern.compile("\\(\\s*\\)");
    private static final Pattern SPACE_AFTER_OPEN = Pattern.compile("\\(\\s+");
    private static final Pattern SPACE_BEFORE_CLOSE = Pattern.compile("\\s+\\)");

    private LocationNames() {
    }

    public static String clean(String raw) {
        String text = WikiText.clean(raw);
        if (text.isEmpty()) {
            return "";
        }
        text = text.replace('\u2013', '-').replace('\u2014', '-').replace('\u2212', '-');
        text = UK_PARAM.matcher(text).replaceAll("");
        String previous;
        do {
            previous = text;
            text = EMPTY_PARENS.matcher(text).replaceAll("");
        } while (!text.equals(previous));
        text = SPACE_AFTER_OPEN.matcher(text).replaceAll("(");
        text = SPACE_BEFORE_CLOSE.matcher(text).replaceAll(")");
        return text.replaceAll("\\s+", " ").trim();
    }

    public static List<String> distinct(List<String> places) {
        Set<String> seen = new LinkedHashSet<>();
        if (places != null) {
            for (String place : places) {
                String cleaned = clean(place);
                if (!cleaned.isEmpty()
                    && !cleaned.equalsIgnoreCase("none")
                    && !cleaned.equalsIgnoreCase("n/a")) {
                    seen.add(cleaned);
                }
            }
        }
        return new ArrayList<>(seen);
    }
}

package com.osr.jei.wiki;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * World coordinates already present on a wiki page. Shop and monster pages
 * carry them in {@code {{Map}}} (and sometimes an infobox {@code mapX}/{@code mapY}).
 */
public final class MapPins {

    /**
     * One clicked place can list many tiles, as monster {@code {{LocLine}}}
     * rows do. The cap is per place, not a running total across clicks.
     */
    public static final int MAX = 32;

    private static final Pattern LOC_COORD = Pattern.compile(
        "x\\s*:\\s*(\\d+)\\s*,\\s*y\\s*:\\s*(\\d+)",
        Pattern.CASE_INSENSITIVE
    );

    public static final class Pin {
        public final int x;
        public final int y;
        public final int plane;

        public Pin(int x, int y, int plane) {
            this.x = x;
            this.y = y;
            this.plane = plane;
        }
    }

    private MapPins() {
    }

    public static List<Pin> parse(String wikitext) {
        Set<String> seen = new LinkedHashSet<>();
        List<Pin> pins = new ArrayList<>();
        if (wikitext == null || wikitext.isEmpty()) {
            return pins;
        }
        for (int index : WikiText.findTemplates(wikitext, "map")) {
            if (pins.size() >= MAX) {
                break;
            }
            String block = WikiText.extractTemplateBlock(wikitext, index);
            add(pins, seen, fromTemplate(block));
        }
        addLocLines(wikitext, pins, seen);
        if (pins.isEmpty()) {
            add(pins, seen, fromInfobox(wikitext));
        }
        return pins;
    }

    /**
     * Monster pages put every spawn in {@code {{LocLine}}} as {@code x:3109,y:9558},
     * often several pairs in one line, with {@code plane=} for the floor.
     * The item page does not copy those pairs, but the monster page already
     * loaded for the location list does.
     */
    private static void addLocLines(String wikitext, List<Pin> pins, Set<String> seen) {
        for (int index : WikiText.findTemplates(wikitext, "locline")) {
            if (pins.size() >= MAX) {
                return;
            }
            String block = WikiText.extractTemplateBlock(wikitext, index);
            if (block == null) {
                continue;
            }
            String plane = WikiText.coalesce(WikiText.parseParams(block), "plane", "z");
            Matcher matcher = LOC_COORD.matcher(block);
            while (matcher.find() && pins.size() < MAX) {
                add(pins, seen, pin(matcher.group(1), matcher.group(2), plane));
            }
        }
    }

    private static Pin fromTemplate(String block) {
        if (block == null) {
            return null;
        }
        Map<String, String> params = WikiText.parseParams(block);
        String xText = WikiText.coalesce(params, "x", "mapx", "1");
        String yText = WikiText.coalesce(params, "y", "mapy", "2");
        String planeText = WikiText.coalesce(params, "plane", "z", "3");
        Pin named = pin(xText, yText, planeText);
        if (named != null) {
            return named;
        }
        List<String> parts = WikiText.splitTopLevel(stripBraces(block));
        if (parts.size() >= 2) {
            return fromCoordinateText(parts.get(1), planeText);
        }
        return null;
    }

    private static Pin fromInfobox(String wikitext) {
        List<Integer> shops = WikiText.findTemplates(wikitext, "infobox shop");
        List<Integer> monsters = WikiText.findTemplates(wikitext, "infobox monster");
        List<Integer> hits = shops.isEmpty() ? monsters : shops;
        if (hits.isEmpty()) {
            return null;
        }
        String block = WikiText.extractTemplateBlock(wikitext, hits.get(0));
        if (block == null) {
            return null;
        }
        Map<String, String> params = WikiText.parseParams(block);
        return pin(
            WikiText.coalesce(params, "mapx", "x"),
            WikiText.coalesce(params, "mapy", "y"),
            WikiText.coalesce(params, "plane", "mapplane", "z")
        );
    }

    private static Pin fromCoordinateText(String text, String planeText) {
        if (text == null) {
            return null;
        }
        String[] bits = text.split(",");
        if (bits.length < 2) {
            return null;
        }
        String plane = bits.length >= 3 ? bits[2] : planeText;
        return pin(bits[0], bits[1], plane);
    }

    private static Pin pin(String xText, String yText, String planeText) {
        Integer x = coord(xText);
        Integer y = coord(yText);
        if (x == null || y == null || !onMap(x.intValue(), y.intValue())) {
            return null;
        }
        int plane = 0;
        Integer parsedPlane = coord(planeText);
        if (parsedPlane != null && parsedPlane.intValue() >= 0 && parsedPlane.intValue() <= 3) {
            plane = parsedPlane.intValue();
        }
        return new Pin(x.intValue(), y.intValue(), plane);
    }

    private static boolean onMap(int x, int y) {
        return x >= 1024 && x <= 4500 && y >= 1024 && y <= 11000;
    }

    private static Integer coord(String text) {
        if (text == null) {
            return null;
        }
        String digits = text.replace(",", "").trim().toLowerCase(Locale.ROOT);
        int end = 0;
        while (end < digits.length() && Character.isDigit(digits.charAt(end))) {
            end++;
        }
        if (end == 0) {
            return null;
        }
        try {
            return Integer.valueOf(digits.substring(0, end));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private static void add(List<Pin> pins, Set<String> seen, Pin pin) {
        if (pin == null || pins.size() >= MAX) {
            return;
        }
        String key = pin.x + ":" + pin.y + ":" + pin.plane;
        if (seen.add(key)) {
            pins.add(pin);
        }
    }

    private static String stripBraces(String block) {
        String inner = block;
        if (inner.startsWith("{{")) {
            inner = inner.substring(2);
        }
        if (inner.endsWith("}}")) {
            inner = inner.substring(0, inner.length() - 2);
        }
        return inner;
    }
}

package com.osr.jei.wiki;

import com.osr.jei.model.MonsterInfo;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/** Combat level and {@code {{LocLine}}} locations from a monster page. */
public final class MonsterParser {

    private MonsterParser() {
    }

    public static Optional<MonsterInfo> parse(String monsterName, String wikitext) {
        if (wikitext == null || wikitext.isEmpty()) {
            return Optional.empty();
        }
        int combat = parseCombatLevel(wikitext);
        List<String> locations = parseLocLines(wikitext);
        if (locations.isEmpty() && combat == 0) {
            return Optional.empty();
        }
        boolean mapped = !MapPins.parse(wikitext).isEmpty();
        return Optional.of(new MonsterInfo(monsterName, combat, locations, mapped));
    }

    static int parseCombatLevel(String wikitext) {
        List<Integer> hits = WikiText.findTemplates(wikitext, "infobox monster");
        if (hits.isEmpty()) {
            return 0;
        }
        String block = WikiText.extractTemplateBlock(wikitext, hits.get(0));
        if (block == null) {
            return 0;
        }
        Map<String, String> params = WikiText.parseParams(block);
        return WikiText.firstInt(WikiText.clean(WikiText.coalesce(params, "combat1", "combat", "combat2")));
    }

    static List<String> parseLocLines(String wikitext) {
        Set<String> seen = new LinkedHashSet<>();
        for (int idx : WikiText.findTemplates(wikitext, "locline")) {
            String block = WikiText.extractTemplateBlock(wikitext, idx);
            if (block == null) {
                continue;
            }
            Map<String, String> params = WikiText.parseParams(block);
            String location = LocationNames.clean(params.getOrDefault("location", ""));
            if (!location.isEmpty()
                && !location.equalsIgnoreCase("none")
                && !location.equalsIgnoreCase("n/a")) {
                seen.add(location);
            }
        }
        return new ArrayList<>(seen);
    }
}

