package com.osr.jei.wiki;

import java.io.IOException;
import java.io.InterruptedIOException;
import java.net.SocketTimeoutException;
import java.util.Locale;
import java.util.concurrent.CompletionException;

/** User-facing copy for a failed wiki or price read. No request is started here. */
public final class WikiFailures {

    private WikiFailures() {
    }

    public static String page(Throwable error) {
        return describe(error, "this page");
    }

    public static String monster(Throwable error) {
        return describe(error, "this monster");
    }

    private static String describe(Throwable error, String subject) {
        Throwable current = unwrap(error);
        if (current instanceof WikiBackoffException) {
            return "That wiki request was not sent again. Use Retry to try now.";
        }
        if (isTimeout(current)) {
            return "The OSRS Wiki timed out while loading " + subject + ". Use Retry to try again.";
        }
        if (current instanceof IOException) {
            String message = current.getMessage() == null ? "" : current.getMessage();
            if (message.startsWith("HTTP ")) {
                return "The OSRS Wiki returned an error (" + message + ") for " + subject + ". Use Retry to try again.";
            }
            if (message.toLowerCase(Locale.ROOT).contains("maxlag")) {
                return "The OSRS Wiki is busy loading " + subject + ". Use Retry in a moment.";
            }
            return "The OSRS Wiki could not be reached for " + subject + ". Use Retry when you are back online.";
        }
        return "The OSRS Wiki could not load " + subject + ". Use Retry to try again.";
    }

    private static Throwable unwrap(Throwable error) {
        Throwable current = error;
        while (current instanceof CompletionException && current.getCause() != null) {
            current = current.getCause();
        }
        return current;
    }

    private static boolean isTimeout(Throwable error) {
        if (error instanceof SocketTimeoutException) {
            return true;
        }
        if (error instanceof InterruptedIOException) {
            String message = error.getMessage() == null ? "" : error.getMessage().toLowerCase(Locale.ROOT);
            return message.contains("timeout") || message.contains("timed out");
        }
        return false;
    }
}

package com.osr.jei.wiki;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * RuneLite's shared OkHttp client and Gson. The client used here is a
 * {@code newBuilder()} of the injected one, so it keeps that dispatcher and
 * connection pool and only adds timeouts. Calls are enqueued, never run on
 * the client thread. A 429, 503, other 5xx, or maxlag response schedules one
 * delayed retry and never blocks a thread with sleep. A timeout or a dropped
 * connection is not retried. Transient failures are not cached by callers.
 */
@Slf4j
@Singleton
public class WikiHttp {

    public static final String USER_AGENT =
        "OSRS-Item-Browser (RuneLite plugin; +https://github.com/Vivialdi/osrs-item-browser)";

    public static final long MAX_BACKOFF_MS = 8_000L;
    public static final int CONNECT_TIMEOUT_SECONDS = 10;
    public static final int READ_TIMEOUT_SECONDS = 20;
    public static final int CALL_TIMEOUT_SECONDS = 20;

    private final OkHttpClient okHttpClient;
    private final Gson gson;
    private final ScheduledExecutorService retries = Executors.newSingleThreadScheduledExecutor(runnable -> {
        Thread thread = new Thread(runnable, "jei-http-retry");
        thread.setDaemon(true);
        return thread;
    });
    private final Set<Call> calls = ConcurrentHashMap.newKeySet();
    private final Set<Call> stableCalls = ConcurrentHashMap.newKeySet();
    private final Set<ScheduledFuture<?>> pendingRetries = ConcurrentHashMap.newKeySet();
    private final Set<ScheduledFuture<?>> stableRetries = ConcurrentHashMap.newKeySet();
    private final AtomicInteger epoch = new AtomicInteger();
    /** Bumped only on shutdown, so a session-long fetch survives item changes. */
    private final AtomicInteger lifetime = new AtomicInteger();

    @Inject
    public WikiHttp(OkHttpClient okHttpClient, Gson gson) {
        this.okHttpClient = okHttpClient.newBuilder()
            .connectTimeout(CONNECT_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .readTimeout(READ_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .callTimeout(CALL_TIMEOUT_SECONDS, TimeUnit.SECONDS)
            .build();
        this.gson = gson;
    }

    /** Derived client. Shares the injected client's dispatcher. */
    public OkHttpClient httpClient() {
        return okHttpClient;
    }

    /** Cancels item-page calls and their retries. Session-long fetches stay up. */
    public void beginRequest() {
        epoch.incrementAndGet();
        cancel(calls, pendingRetries);
    }

    /** Stop the retry scheduler. Does not wait for tasks to finish. */
    public void shutdown() {
        epoch.incrementAndGet();
        lifetime.incrementAndGet();
        cancel(calls, pendingRetries);
        cancel(stableCalls, stableRetries);
        retries.shutdownNow();
    }

    public CompletableFuture<JsonObject> getJson(String url) {
        return requestObject(url, false, false);
    }

    public CompletableFuture<JsonObject> getWiki(String url) {
        return requestObject(withMaxlag(url), true, false);
    }

    /**
     * One JSON value, array or object, that is not cancelled when the open
     * item changes. Shutdown still cancels it. Same User-Agent and retry as
     * {@link #getJson(String)}.
     */
    public CompletableFuture<JsonElement> getStableElement(String url) {
        CompletableFuture<JsonElement> future = new CompletableFuture<>();
        dispatch(url, false, true, future, 0, lifetime.get());
        return future;
    }

    private CompletableFuture<JsonObject> requestObject(String url, boolean mediawiki, boolean stable) {
        CompletableFuture<JsonElement> future = new CompletableFuture<>();
        int token = stable ? lifetime.get() : epoch.get();
        dispatch(url, mediawiki, stable, future, 0, token);
        return future.thenApply(WikiHttp::requireObject);
    }

    private static JsonObject requireObject(JsonElement element) {
        if (element == null || !element.isJsonObject()) {
            throw new IllegalStateException("Unexpected JSON");
        }
        return element.getAsJsonObject();
    }

    public static String withMaxlag(String url) {
        HttpUrl parsed = HttpUrl.parse(url);
        if (parsed == null || parsed.queryParameter("maxlag") != null) {
            return url;
        }
        return parsed.newBuilder().addQueryParameter("maxlag", "5").build().toString();
    }

    public static long retryAfterMillis(String header, long fallbackMs) {
        if (header == null || header.isEmpty()) {
            return fallbackMs;
        }
        try {
            long seconds = Long.parseLong(header.trim());
            if (seconds < 0) {
                return fallbackMs;
            }
            return Math.min(MAX_BACKOFF_MS, seconds * 1000L);
        } catch (NumberFormatException e) {
            return fallbackMs;
        }
    }

    private void dispatch(String url, boolean mediawiki, boolean stable, CompletableFuture<JsonElement> future, int attempt, int token) {
        if (token != tokenNow(stable) || future.isDone()) {
            future.completeExceptionally(new RequestCancelledException());
            return;
        }
        Request request = new Request.Builder()
            .url(url)
            .header("User-Agent", USER_AGENT)
            .build();
        Call call = okHttpClient.newCall(request);
        Set<Call> bucket = stable ? stableCalls : calls;
        bucket.add(call);
        call.enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                bucket.remove(call);
                if (token != tokenNow(stable)) {
                    future.completeExceptionally(new RequestCancelledException());
                    return;
                }
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(Call call, Response response) {
                bucket.remove(call);
                try (Response responseToClose = response) {
                    if (token != tokenNow(stable)) {
                        future.completeExceptionally(new RequestCancelledException());
                        return;
                    }
                    int code = responseToClose.code();
                    if (code == 429 || code == 503 || code >= 500) {
                        if (attempt == 0) {
                            scheduleRetry(url, mediawiki, stable, future, token,
                                retryAfterMillis(responseToClose.header("Retry-After"), 2_000L));
                            return;
                        }
                        future.completeExceptionally(new IOException("HTTP " + code));
                        return;
                    }
                    if (!responseToClose.isSuccessful() || responseToClose.body() == null) {
                        future.completeExceptionally(new IOException("HTTP " + code));
                        return;
                    }
                    ResponseBody body = responseToClose.body();
                    JsonElement element = gson.fromJson(body.string(), JsonElement.class);
                    if (element == null || element.isJsonNull()) {
                        future.completeExceptionally(new IOException("Unexpected JSON"));
                        return;
                    }
                    if (mediawiki && element.isJsonObject() && isMaxlag(element.getAsJsonObject())) {
                        if (attempt == 0) {
                            scheduleRetry(url, mediawiki, stable, future, token, 5_000L);
                            return;
                        }
                        future.completeExceptionally(new IOException("wiki maxlag"));
                        return;
                    }
                    future.complete(element);
                } catch (Exception e) {
                    if (token != tokenNow(stable)) {
                        future.completeExceptionally(new RequestCancelledException());
                    } else {
                        future.completeExceptionally(e);
                    }
                }
            }
        });
    }

    private void scheduleRetry(
        String url,
        boolean mediawiki,
        boolean stable,
        CompletableFuture<JsonElement> future,
        int token,
        long waitMs
    ) {
        if (token != tokenNow(stable)) {
            future.completeExceptionally(new RequestCancelledException());
            return;
        }
        long delay = Math.min(MAX_BACKOFF_MS, Math.max(0L, waitMs));
        Set<ScheduledFuture<?>> bucket = stable ? stableRetries : pendingRetries;
        ScheduledFuture<?> scheduled = retries.schedule(() -> {
            bucket.removeIf(ScheduledFuture::isDone);
            dispatch(url, mediawiki, stable, future, 1, token);
        }, delay, TimeUnit.MILLISECONDS);
        bucket.add(scheduled);
    }

    private int tokenNow(boolean stable) {
        return stable ? lifetime.get() : epoch.get();
    }

    private static void cancel(Set<Call> calls, Set<ScheduledFuture<?>> retries) {
        for (Call call : calls) {
            call.cancel();
        }
        calls.clear();
        for (ScheduledFuture<?> scheduled : retries) {
            scheduled.cancel(false);
        }
        retries.clear();
    }

    private static boolean isMaxlag(JsonObject obj) {
        if (obj == null || !obj.has("error") || !obj.get("error").isJsonObject()) {
            return false;
        }
        JsonObject error = obj.getAsJsonObject("error");
        return error.has("code") && "maxlag".equals(error.get("code").getAsString());
    }
}

package com.osr.jei.wiki;

import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.function.LongSupplier;

/**
 * One {@code action=parse} per page. Item pages ask for rendered HTML.
 * Monster and map reads ask for wikitext only, which is enough for
 * {@code {{LocLine}}} and {@code {{Map}}} and is much smaller.
 * Callers that ask for the same page at the same time share one future.
 * A successful parse, including a confirmed missing page, is cached.
 * Transport failures are not cached; the same page is not requested again
 * until {@link #FAILURE_BACKOFF_MS} has passed or {@link #allowRetry(String)} runs.
 */
@Slf4j
@Singleton
public class WikiPages {

    public static final int CACHE_SIZE = 48;
    public static final long TTL_MS = 30L * 60L * 1000L;
    public static final long FAILURE_BACKOFF_MS = 8_000L;

    static final String API =
        "https://oldschool.runescape.wiki/api.php?action=parse&prop=wikitext|text&format=json&redirects=true&page=";
    /** No rendered HTML. Used for monster locations and map pins. */
    static final String WIKITEXT_API =
        "https://oldschool.runescape.wiki/api.php?action=parse&prop=wikitext&format=json&redirects=true&page=";

    private final WikiHttp wikiHttp;
    private final LongSupplier clock;
    private final TtlCache<String, PageContent> cache = new TtlCache<>(CACHE_SIZE, TTL_MS);
    private final TtlCache<String, PageContent> wikitextOnly = new TtlCache<>(CACHE_SIZE, TTL_MS);
    private final Map<String, CompletableFuture<PageContent>> inflight = new HashMap<>();
    private final LinkedHashMap<String, Long> retryNotBefore = new LinkedHashMap<>(16, 0.75f, true);
    private final Object lock = new Object();

    @Inject
    public WikiPages(WikiHttp wikiHttp) {
        this(wikiHttp, System::currentTimeMillis);
    }

    public WikiPages(WikiHttp wikiHttp, LongSupplier clock) {
        this.wikiHttp = wikiHttp;
        this.clock = clock == null ? System::currentTimeMillis : clock;
    }

    /** Drop a cached page and the failure holdoff so the next load hits the network once. */
    public void allowRetry(String title) {
        if (title == null || title.isEmpty()) {
            return;
        }
        synchronized (lock) {
            String key = key(title);
            retryNotBefore.remove(key);
            cache.remove(key);
            wikitextOnly.remove(key);
        }
    }

    public int size() {
        synchronized (lock) {
            return cache.size();
        }
    }

    public CompletableFuture<PageContent> load(String title) {
        return load(title, true);
    }

    /**
     * Wikitext only. A page already fetched with HTML is reused. A wikitext-only
     * result is not reused by {@link #load(String)}, which still needs the tables.
     */
    public CompletableFuture<PageContent> loadWikitext(String title) {
        return load(title, false);
    }

    private CompletableFuture<PageContent> load(String title, boolean rendered) {
        if (title == null || title.trim().isEmpty()) {
            return CompletableFuture.completedFuture(PageContent.MISSING);
        }
        String key = key(title);
        String flight = (rendered ? "f:" : "w:") + key;
        CompletableFuture<PageContent> created = new CompletableFuture<>();
        synchronized (lock) {
            long now = clock.getAsLong();
            PageContent hit = rendered ? cache.get(key, now) : cachedWikitext(key, now);
            if (hit != null) {
                return CompletableFuture.completedFuture(hit);
            }
            Long until = retryNotBefore.get(key);
            if (until != null && now < until) {
                created.completeExceptionally(new WikiBackoffException());
                return created;
            }
            retryNotBefore.remove(key);
            CompletableFuture<PageContent> existing = inflight.get(flight);
            if (existing != null) {
                return existing;
            }
            inflight.put(flight, created);
        }
        String encoded = URLEncoder.encode(title.replace(' ', '_'), StandardCharsets.UTF_8);
        String url = (rendered ? API : WIKITEXT_API) + encoded;
        final long sent = System.nanoTime();
        if (!rendered) {
            log.debug("Wiki wikitext request sent for {}", title);
        }
        try {
            wikiHttp.getWiki(url).whenComplete((root, error) -> {
                if (!rendered) {
                    log.debug("Wiki wikitext response for {} in {} ms", title, (System.nanoTime() - sent) / 1_000_000L);
                }
                finish(key, flight, title, created, root, error, rendered);
            });
        } catch (RuntimeException e) {
            finish(key, flight, title, created, null, e, rendered);
        }
        return created;
    }

    private PageContent cachedWikitext(String key, long now) {
        PageContent full = cache.get(key, now);
        if (full != null) {
            return full;
        }
        return wikitextOnly.get(key, now);
    }

    private void finish(
        String key,
        String flight,
        String title,
        CompletableFuture<PageContent> created,
        JsonObject root,
        Throwable error,
        boolean rendered
    ) {
        if (error != null) {
            Throwable cause = unwrap(error);
            boolean cancelled = cause instanceof RequestCancelledException;
            synchronized (lock) {
                if (inflight.get(flight) == created) {
                    inflight.remove(flight);
                }
                if (!cancelled) {
                    noteFailure(key, clock.getAsLong());
                }
            }
            created.completeExceptionally(cause);
            return;
        }
        PageContent page = toPage(title, root);
        synchronized (lock) {
            if (rendered) {
                cache.put(key, page, clock.getAsLong());
            } else {
                wikitextOnly.put(key, page, clock.getAsLong());
            }
            retryNotBefore.remove(key);
            if (inflight.get(flight) == created) {
                inflight.remove(flight);
            }
        }
        created.complete(page);
    }

    private void noteFailure(String key, long now) {
        retryNotBefore.put(key, now + FAILURE_BACKOFF_MS);
        while (retryNotBefore.size() > CACHE_SIZE) {
            Iterator<String> it = retryNotBefore.keySet().iterator();
            it.next();
            it.remove();
        }
    }

    private static String key(String title) {
        return title.toLowerCase(Locale.ROOT);
    }

    private static PageContent toPage(String title, JsonObject root) {
        if (root == null || !root.has("parse")) {
            log.debug("[Item Browser] Wiki page missing: {}", title);
            return PageContent.MISSING;
        }
        JsonObject parse = root.getAsJsonObject("parse");
        String wikitext = "";
        String html = "";
        if (parse.has("wikitext") && parse.get("wikitext").isJsonObject()) {
            wikitext = parse.getAsJsonObject("wikitext").get("*").getAsString();
        }
        if (parse.has("text") && parse.get("text").isJsonObject()) {
            html = parse.getAsJsonObject("text").get("*").getAsString();
        }
        log.debug("[Item Browser] Wiki page fetched: {}", title);
        return new PageContent(wikitext, html, false);
    }

    private static Throwable unwrap(Throwable error) {
        Throwable current = error;
        while (current instanceof java.util.concurrent.CompletionException && current.getCause() != null) {
            current = current.getCause();
        }
        return current;
    }
}

package com.osr.jei.wiki;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Shared wikitext helpers. Recipe, equipment, and monster parsing all use this
 * so template walking stays consistent.
 */
public final class WikiText {

    private static final Pattern WIKILINK = Pattern.compile("\\[\\[(?:[^|\\]]*\\|)?([^\\]]+)\\]\\]");
    private static final Pattern TEMPLATE1 = Pattern.compile("\\{\\{[^{}|]*\\|([^{}|]*)\\}\\}");
    private static final Pattern TEMPLATE2 = Pattern.compile("\\{\\{[^{}]*\\}\\}");
    private static final Pattern EXTLINK = Pattern.compile("\\[https?://\\S+\\s([^\\]]+)\\]");
    private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");
    private static final Pattern DIGITS = Pattern.compile("\\d+");
    private static final Pattern SIGNED_INT = Pattern.compile("[+-]?\\d+");
    private static final Pattern DECIMAL = Pattern.compile("[0-9]+(?:\\.[0-9]+)?");

    private WikiText() {
    }

    public static String extractTemplateBlock(String text, int startIdx) {
        if (text == null || startIdx < 0 || startIdx >= text.length()) {
            return null;
        }
        int depth = 0;
        int i = startIdx;
        while (i < text.length() - 1) {
            char c = text.charAt(i);
            char next = text.charAt(i + 1);
            if (c == '{' && next == '{') {
                depth++;
                i += 2;
            } else if (c == '}' && next == '}') {
                depth--;
                if (depth == 0) {
                    return text.substring(startIdx, i + 2);
                }
                i += 2;
            } else {
                i++;
            }
        }
        return null;
    }

    /** Indexes of templates whose name starts with {@code nameLower}, for example {@code "recipe"}. */
    public static List<Integer> findTemplates(String wikitext, String nameLower) {
        List<Integer> hits = new ArrayList<>();
        if (wikitext == null || wikitext.isEmpty() || nameLower == null) {
            return hits;
        }
        String lower = wikitext.toLowerCase(Locale.ROOT);
        String needle = "{{" + nameLower.toLowerCase(Locale.ROOT);
        int from = 0;
        while (from < lower.length()) {
            int idx = lower.indexOf(needle, from);
            if (idx < 0) {
                break;
            }
            int after = idx + needle.length();
            if (after >= lower.length()) {
                break;
            }
            char boundary = lower.charAt(after);
            // Reject prefixes such as {{recipename. A real call is followed by |, space, newline, or }.
            if (boundary == '|' || boundary == ' ' || boundary == '\n' || boundary == '\t' || boundary == '}') {
                hits.add(idx);
                from = after;
            } else {
                from = idx + 2;
            }
        }
        return hits;
    }

    public static Map<String, String> parseParams(String block) {
        Map<String, String> params = new LinkedHashMap<>();
        if (block == null || block.isEmpty()) {
            return params;
        }
        String inner = block;
        if (inner.startsWith("{{")) {
            inner = inner.substring(2);
        }
        if (inner.endsWith("}}")) {
            inner = inner.substring(0, inner.length() - 2);
        }
        List<String> parts = splitTopLevel(inner);
        for (int i = 1; i < parts.size(); i++) {
            String part = parts.get(i).replace("\n", " ").trim();
            if (part.isEmpty()) {
                continue;
            }
            int eq = part.indexOf('=');
            if (eq <= 0) {
                continue;
            }
            String key = part.substring(0, eq).trim().toLowerCase(Locale.ROOT);
            String val = part.substring(eq + 1).trim();
            if (!key.isEmpty()) {
                params.put(key, val);
            }
        }
        return params;
    }

    public static List<String> splitTopLevel(String text) {
        List<String> parts = new ArrayList<>();
        if (text == null) {
            return parts;
        }
        int depth = 0;
        int start = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (i + 1 < text.length()) {
                char nx = text.charAt(i + 1);
                if ((c == '{' && nx == '{') || (c == '[' && nx == '[')) {
                    depth++;
                    i++;
                    continue;
                }
                if ((c == '}' && nx == '}') || (c == ']' && nx == ']')) {
                    depth = Math.max(0, depth - 1);
                    i++;
                    continue;
                }
            }
            if (c == '|' && depth == 0) {
                parts.add(text.substring(start, i));
                start = i + 1;
            }
        }
        parts.add(text.substring(start));
        return parts;
    }

    public static String coalesce(Map<String, String> params, String... keys) {
        if (params == null) {
            return "";
        }
        for (String key : keys) {
            String v = params.get(key);
            if (v != null && !v.trim().isEmpty()) {
                return v;
            }
        }
        return "";
    }

    public static String clean(String text) {
        if (text == null || text.trim().isEmpty()) {
            return "";
        }
        text = WIKILINK.matcher(text).replaceAll("$1");
        text = TEMPLATE1.matcher(text).replaceAll("$1");
        text = TEMPLATE2.matcher(text).replaceAll("");
        text = EXTLINK.matcher(text).replaceAll("$1");
        text = text.replaceAll("'{2,}", "");
        text = text.replace("&amp;", "&")
            .replace("&lt;", "<")
            .replace("&gt;", ">")
            .replace("&nbsp;", " ")
            .replace("&#160;", " ");
        text = HTML_TAG.matcher(text).replaceAll("");
        return text.replaceAll("\\s+", " ").trim();
    }

    public static int firstInt(String text) {
        if (text == null || text.isEmpty()) {
            return 0;
        }
        Matcher m = DIGITS.matcher(text.replace(",", ""));
        return m.find() ? Integer.parseInt(m.group()) : 0;
    }

    public static int signedInt(String raw) {
        if (raw == null || raw.isEmpty()) {
            return 0;
        }
        String cleaned = clean(raw).replace(",", "");
        Matcher m = SIGNED_INT.matcher(cleaned);
        return m.find() ? Integer.parseInt(m.group()) : 0;
    }

    public static double firstDouble(String text) {
        if (text == null || text.isEmpty()) {
            return 0;
        }
        Matcher m = DECIMAL.matcher(text.replace(",", ""));
        return m.find() ? Double.parseDouble(m.group()) : 0;
    }
}

package com.osr.jei;

import com.osr.jei.drops.DropSort;
