        long fetched = 50_000L;
        long later = fetched + PriceSnapshot.TTL_MS;
        assertEquals("7 min old", PriceAge.suffix(timeless, fetched, later));
        assertEquals(PriceAge.UNAVAILABLE, "Grand Exchange prices are unavailable.");
    }

    @Test
    public void quoteKeepsTradeTimesAndLookupMarksAFailedSnapshot() {
        JsonObject entry = new JsonObject();
        entry.addProperty("high", 120);
        entry.addProperty("low", 80);
        entry.addProperty("highTime", 111);
        entry.addProperty("lowTime", 90);
        PriceQuote quote = PriceQuote.fromItem(entry);
        assertEquals(111L, quote.newestTimeSeconds());

        assertTrue(PriceLookup.from(PriceSnapshot.empty(), true, 2, 1_000L).unavailable);
        long fetched = 1_000L;
        PriceSnapshot fresh = new PriceSnapshot(fetched, java.util.Collections.singletonMap(2, quote));
        PriceLookup ready = PriceLookup.from(fresh, false, 2, fetched + 1_000L);
        assertFalse(ready.unavailable);
        assertFalse(ready.stale);
        assertEquals(120L, ready.quote.instantBuy);
        PriceLookup stale = PriceLookup.from(fresh, true, 2, fetched + PriceSnapshot.TTL_MS);
        assertFalse(stale.unavailable);
        assertTrue(stale.stale);
    }

    @Test
    public void oneLatestDownloadFeedsEveryItemAndAFailureDoesNotRetryImmediately() throws Exception {
        FakeHttp http = new FakeHttp();
        try {
            PriceService prices = new PriceService(http);
            CompletableFuture<PriceLookup> nature = prices.lookup(561);
            assertTrue(http.entered.await(2, TimeUnit.SECONDS));
            CompletableFuture<PriceLookup> law = prices.lookup(563);
            assertEquals(1, http.calls.get());
            http.blocked.complete(latest());
            assertEquals(100L, nature.join().quote.instantBuy);
            assertEquals(40L, law.join().quote.instantBuy);
            assertEquals(1, http.calls.get());
            assertFalse(prices.lookup(561).join().unavailable);
            assertEquals(1, http.calls.get());
        } finally {
            http.shutdown();
        }
    }

    @Test
    public void priceFailureWaitsUntilTheCallerAllowsAnotherAttempt() {
        FakeHttp http = new FakeHttp();
        http.block = false;
        http.failure = new IOException("offline");
        try {
            PriceService prices = new PriceService(http);
            assertTrue(prices.lookup(561).join().unavailable);
            assertEquals(1, http.calls.get());
            assertTrue(prices.lookup(563).join().unavailable);
            assertEquals(1, http.calls.get());
            prices.allowRetry();
            http.failure = null;
            PriceLookup loaded = prices.lookup(561).join();
            assertFalse(loaded.unavailable);
            assertEquals(100L, loaded.quote.instantBuy);
            assertEquals(2, http.calls.get());
        } finally {
            http.shutdown();
        }
    }

    private static JsonObject latest() {
        JsonObject nature = new JsonObject();
        nature.addProperty("high", 100);
        nature.addProperty("low", 90);
        nature.addProperty("highTime", 50);
        JsonObject law = new JsonObject();
        law.addProperty("high", 40);
        law.addProperty("low", 30);
        JsonObject data = new JsonObject();
        data.add("561", nature);
        data.add("563", law);
        JsonObject root = new JsonObject();
        root.add("data", data);
        return root;
    }

    private static final class FakeHttp extends WikiHttp {
        private final AtomicInteger calls = new AtomicInteger();
        private final CountDownLatch entered = new CountDownLatch(1);
        private final CompletableFuture<JsonObject> blocked = new CompletableFuture<>();
        private volatile Throwable failure;
        private volatile boolean block = true;

        private FakeHttp() {
            super(new OkHttpClient(), new Gson());
        }

        @Override
        public CompletableFuture<JsonObject> getJson(String url) {
            calls.incrementAndGet();
            entered.countDown();
            if (failure != null) {
                CompletableFuture<JsonObject> failed = new CompletableFuture<>();
                failed.completeExceptionally(failure);
                return failed;
            }
            if (block) {
                return blocked;
            }
            return CompletableFuture.completedFuture(latest());
        }
    }
}

package com.osr.jei.requirements;

import com.osr.jei.model.RecipeInfo;
import com.osr.jei.model.RecipeIngredient;
import com.osr.jei.service.ItemDetails;
import com.osr.jei.wiki.PageContent;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class RequirementCheckTest {

    private static final String WHIP = ""
        + "{{Infobox Item\n|name = Abyssal whip\n|quest = No\n|weight = 0.453\n}}\n"
        + "The '''abyssal whip''' is a one-handed [[melee weapon]] which requires an [[Attack]] level of 70 to wield.\n"
        + "==Combat stats==\n"
        + "{{Infobox Bonuses\n|aslash = +82\n|str = +82\n|slot = weapon\n|speed = 4\n}}\n"
        + "==Upgrading==\n"
        + "An [[abyssal tentacle]] requires an [[Attack]] level of 75.\n";

    private static final String SCIMITAR = ""
        + "{{Infobox Item\n|quest = No\n}}\n"
        + "It can only be wielded by players who have 60 [[Attack]] and have completed the [[Monkey Madness I]] quest.\n"
        + "A [[monkeyspeak amulet]] does not need to be worn, unless you have completed [[Monkey Madness II]].\n";

    private static final String HELMET = ""
        + "{{Infobox Item\n|quest = No\n}}\n"
        + "[[Reinforced goggles]] are additionally required only if the quest [[A Porcine of Interest]] is completed.\n"
        + "It requires 10 [[Defence]] to equip.\n"
        + "Despite the helmet requiring a [[nose peg]], which requires 60 [[Slayer]] to equip, the Slayer helmet requires no particular Slayer level to wear.\n";

    private static final String AVA = ""
        + "{{Infobox Item\n|quest = [[Animal Magnetism]]\n}}\n"
        + "'''Ava's accumulator''' is awarded by completing the quest [[Animal Magnetism]] if the player is level 50 [[Ranged]] or above.\n"
        + "It is equipped in the [[cape slot]].\n";

    private static final String PLATE = ""
        + "{{Infobox Item\n|quest = No\n}}\n"
        + "It has no [[Defence]] requirement to equip.\n"
        + "{{Recipe\n|skill1 = Smithing\n|skill1lvl = 33\n|skill1exp = 125\n|mat1 = Iron bar\n|mat1quantity = 5\n}}\n";

    private static final String STAFF = ""
        + "{{Infobox Item\n|quest = No\n}}\n"
        + "A staff.\n"
        + "==Requirements==\n"
        + "{{SCP|Magic|75}}\n"
        + "Completion of [[Desert Treasure I]] is required to wield this staff.\n"
        + "==Combat stats==\n";

    @Test
    public void parsesWieldLinesAndIgnoresOtherSections() {
        ItemRequirements whip = RequirementParser.parse(WHIP);
        assertEquals(1, whip.skills.size());
        assertEquals("Attack", whip.skills.get(0).name);
        assertEquals(70, whip.skills.get(0).level);
        assertTrue(whip.quests.isEmpty());

        ItemRequirements scimitar = RequirementParser.parse(SCIMITAR);
        assertEquals("Attack", scimitar.skills.get(0).name);
        assertEquals(60, scimitar.skills.get(0).level);
        assertEquals(Collections.singletonList("Monkey Madness I"), scimitar.quests);

        ItemRequirements helmet = RequirementParser.parse(HELMET);
        assertEquals(1, helmet.skills.size());
        assertEquals("Defence", helmet.skills.get(0).name);
        assertEquals(10, helmet.skills.get(0).level);
        assertTrue(helmet.quests.isEmpty());

        ItemRequirements ava = RequirementParser.parse(AVA);
        assertTrue(ava.skills.isEmpty());
        assertEquals(Collections.singletonList("Animal Magnetism"), ava.quests);

        ItemRequirements plate = RequirementParser.parse(PLATE);
        assertTrue(plate.isEmpty());

        ItemRequirements staff = RequirementParser.parse(STAFF);
        assertEquals("Magic", staff.skills.get(0).name);
        assertEquals(75, staff.skills.get(0).level);
        assertEquals("Desert Treasure I", staff.quests.get(0));
    }

    @Test
    public void pageParseKeepsRequirementsWithTheRecipe() {
        ItemDetails details = ItemDetails.from(new PageContent(PLATE, "", false));
        assertEquals("Smithing", details.recipes.get(0).skill);
        assertEquals(33, details.recipes.get(0).level);
        assertTrue(details.requirements.isEmpty());
    }

    @Test
    public void questNamesMatchExactly() {
        Map<String, String> index = QuestNames.index(Arrays.asList(
            "Dragon Slayer I",
            "Dragon Slayer II",
            "Monkey Madness I",
            "Animal Magnetism"
        ));
        assertEquals("Dragon Slayer I", QuestNames.canonical(index, "Dragon Slayer I"));
        assertNull(QuestNames.canonical(index, "Dragon Slayer"));
        assertNull(QuestNames.canonical(index, "Monkey Madness"));
        assertNull(QuestNames.canonical(index, "Fight Cave"));
        assertEquals("Animal Magnetism", QuestNames.canonical(index, "Animal Magnetism quest"));
    }

    @Test
    public void ambiguousQuestNamesAreNeverMet() {
        Map<String, String> index = QuestNames.index(Arrays.asList("Twin Quest", "Twin-Quest"));
        assertNull(QuestNames.canonical(index, "Twin Quest"));
        ProgressSnapshot loggedIn = snapshot(99, QuestProgress.FINISHED, "twin quest");
        assertEquals(Mark.NEUTRAL, RequirementJudge.quest("Twin Quest", index, loggedIn, true));
    }

    @Test
    public void comparisonUsesRealLevelsAndNeverMarksUnknownAsMet() {
        Map<String, String> quests = QuestNames.index(Collections.singletonList("Monkey Madness I"));
        ProgressSnapshot ready = snapshot(60, QuestProgress.FINISHED, "monkey madness i");
        ProgressSnapshot shortLevel = snapshot(59, QuestProgress.FINISHED, "monkey madness i");
        ProgressSnapshot inProgress = snapshot(60, QuestProgress.IN_PROGRESS, "monkey madness i");

        assertEquals(Mark.MET, RequirementJudge.skill("Attack", 60, ready, true));
        assertEquals(Mark.UNMET, RequirementJudge.skill("Defense", 61, ready, true));
        assertEquals(Mark.NEUTRAL, RequirementJudge.skill("Woodworking", 10, ready, true));
        assertEquals(Mark.MET, RequirementJudge.quest("Monkey Madness I", quests, ready, true));
        assertEquals(Mark.UNMET, RequirementJudge.quest("Monkey Madness I", quests, inProgress, true));
        assertEquals(Mark.NEUTRAL, RequirementJudge.quest("Not A Real Quest", quests, ready, true));
        assertEquals(Mark.NEUTRAL, RequirementJudge.skill("Attack", 60, ProgressSnapshot.LOGGED_OUT, true));
        assertEquals(Mark.NEUTRAL, RequirementJudge.quest("Monkey Madness I", quests, ready, false));

        RecipeInfo recipe = new RecipeInfo(
            "Smithing", 99, "Anvil", 1,
            Collections.singletonList(new RecipeIngredient("Rune bar", 1)),
            1, "", "Crafting", 40);
        assertEquals(Mark.UNMET, RequirementJudge.recipe(recipe, shortLevel, true));
        Map<String, Integer> skilled = new HashMap<>();
        skilled.put("Smithing", 99);
        skilled.put("Crafting", 40);
        ProgressSnapshot both = new ProgressSnapshot(true, skilled, Collections.<String, QuestProgress>emptyMap());
        assertEquals(Mark.MET, RequirementJudge.recipe(recipe, both, true));
        assertEquals(Mark.NEUTRAL, RequirementJudge.recipe(recipe, both, false));
    }

    private static ProgressSnapshot snapshot(int attack, QuestProgress quest, String questKey) {
        Map<String, Integer> skills = new HashMap<>();
        skills.put("Attack", attack);
        skills.put("Defence", 60);
        skills.put("Smithing", 50);
        skills.put("Crafting", 40);
        Map<String, QuestProgress> quests = new HashMap<>();
        quests.put(questKey, quest);
        return new ProgressSnapshot(true, skills, quests);
    }
}

package com.osr.jei.search;

import com.osr.jei.model.SearchItem;
import org.junit.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class JunkItemFilterTest {

    private static final int CHAIR = 6122;
    private static final int BEER_GLASS = 6123;
    private static final int YAK_CRATE = 32559;

    /** Cosmetics and holiday gear that must stay searchable. */
    private static final int[] KEPT = {
        1050, // Santa hat
        1037, // Bunny ears
        1038, // Red partyhat
        1040, // Yellow partyhat
        1042, // Blue partyhat
        1044, // Green partyhat
        1046, // Purple partyhat
        1048, // White partyhat
        11862, // Black partyhat
        11863, // Rainbow partyhat
        9925, // Skeleton mask
        9924, // Skeleton shirt
        9923, // Skeleton leggings
        3057, // Mime mask
        3058, // Mime top
        3059, // Mime legs
        11850, // Graceful hood
        11854, // Graceful top
        12888, // Santa jacket
        13663 // Bunny top
    };

    @Test
    public void listsHoldTheExampleItemsAndNotCosmetics() {
        assertTrue(AnimationItems.contains(CHAIR));
        assertTrue(AnimationItems.contains(BEER_GLASS));
        assertEquals(61, AnimationItems.size());
        assertTrue(TaskCarryItems.contains(YAK_CRATE));
        assertEquals(374, TaskCarryItems.size());
        assertFalse(AnimationItems.contains(YAK_CRATE));
        assertFalse(TaskCarryItems.contains(CHAIR));
        for (int id : KEPT) {
            assertFalse("animation list has " + id, AnimationItems.contains(id));
            assertFalse("task carry list has " + id, TaskCarryItems.contains(id));
        }
    }

    @Test
    public void searchHidesBothListsUntilTheSettingsAreOn() {
        SearchItem chair = item(CHAIR, "A chair");
        SearchItem glass = item(BEER_GLASS, "Beer glass");
        SearchItem crate = item(YAK_CRATE, "Crate of yak hair");
        SearchItem whip = item(4151, "Abyssal whip");
        SearchItem santa = item(1050, "Santa hat");
        List<SearchItem> all = Arrays.asList(chair, glass, crate, whip, santa);

        SearchCriteria hidden = criteria(false, false);
        assertTrue(ItemSearch.rank(all, "chair", 10, hidden).isEmpty());
        assertTrue(ItemSearch.rank(all, "glass", 10, hidden).isEmpty());
        assertTrue(ItemSearch.rank(all, "yak", 10, hidden).isEmpty());
        assertEquals("Abyssal whip", ItemSearch.rank(all, "whip", 10, hidden).get(0).name);
        assertEquals("Santa hat", ItemSearch.rank(all, "santa", 10, hidden).get(0).name);

        SearchCriteria equip = new SearchCriteria(
            SearchCriteria.Trade.ANY,
            SearchCriteria.Members.ANY,
            SearchCriteria.Equip.EQUIPABLE,
            SearchCriteria.SlotChoice.ANY,
            false,
            false
        );
        assertTrue(ItemSearch.rank(all, "crate", 10, equip).isEmpty());
        assertEquals("Abyssal whip", ItemSearch.rank(all, "whip", 10, equip).get(0).name);

        SearchCriteria shown = criteria(true, true);
        assertEquals("A chair", ItemSearch.rank(all, "chair", 10, shown).get(0).name);
        assertEquals("Beer glass", ItemSearch.rank(all, "glass", 10, shown).get(0).name);
        assertEquals("Crate of yak hair", ItemSearch.rank(all, "yak", 10, shown).get(0).name);
    }

    private static SearchCriteria criteria(boolean animation, boolean taskCarry) {
        return new SearchCriteria(
            SearchCriteria.Trade.ANY,
            SearchCriteria.Members.ANY,
            SearchCriteria.Equip.ANY,
            SearchCriteria.SlotChoice.ANY,
            animation,
            taskCarry
        );
    }

    private static SearchItem item(int id, String name) {
        return new SearchItem(id, name, true, 0, ItemTraits.pack(true, false, true, 3));
    }
}

package com.osr.jei.search;

import com.osr.jei.model.SearchItem;
import org.junit.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SearchFilterTest {

    @Test
    public void packsSlotZeroSeparatelyFromMissing() {
        int head = ItemTraits.pack(true, true, true, 0);
        assertTrue(ItemTraits.members(head));
        assertTrue(ItemTraits.tradeable(head));
        assertTrue(ItemTraits.equipable(head));
        assertEquals(0, ItemTraits.slot(head));

        int plain = ItemTraits.pack(false, false, false, -1);
        assertFalse(ItemTraits.equipable(plain));
        assertEquals(-1, ItemTraits.slot(plain));
        assertEquals(3, ItemTraits.slot(ItemTraits.pack(false, true, true, 3)));
    }

    @Test
    public void filtersRunBeforeTheResultLimit() {
        SearchItem whip = item(4151, "Abyssal whip", true, flags(true, true, 3));
        SearchItem coins = item(995, "Coins", false, flags(true, false, -1));
        SearchItem cape = item(6570, "Fire cape", false, flags(false, true, 1));
        SearchItem bow = item(9185, "Rune crossbow", true, flags(true, true, 3));
        SearchItem plate = item(1117, "Steel platebody", false, flags(true, true, 4));
        List<SearchItem> all = Arrays.asList(whip, coins, cape, bow, plate);

        SearchCriteria weapons = new SearchCriteria(
            SearchCriteria.Trade.ANY,
            SearchCriteria.Members.ANY,
            SearchCriteria.Equip.EQUIPABLE,
            SearchCriteria.SlotChoice.WEAPON
        );
        List<SearchItem> found = ItemSearch.rank(all, "ss", 10, weapons);
        assertEquals(2, found.size());
        assertEquals("Abyssal whip", found.get(0).name);
        assertEquals("Rune crossbow", found.get(1).name);

        SearchCriteria freeTradeable = new SearchCriteria(
            SearchCriteria.Trade.TRADEABLE,
            SearchCriteria.Members.FREE,
            SearchCriteria.Equip.ANY,
            SearchCriteria.SlotChoice.ANY
        );
        List<SearchItem> free = ItemSearch.rank(all, "co", 10, freeTradeable);
        assertEquals(1, free.size());
        assertEquals("Coins", free.get(0).name);

        SearchCriteria untradeable = new SearchCriteria(
            SearchCriteria.Trade.UNTRADEABLE,
            SearchCriteria.Members.ANY,
            SearchCriteria.Equip.ANY,
            SearchCriteria.SlotChoice.ANY
        );
        List<SearchItem> locked = ItemSearch.rank(all, "fi", 10, untradeable);
        assertEquals(1, locked.size());
        assertEquals("Fire cape", locked.get(0).name);

        assertEquals("Abyssal whip", ItemSearch.rank(all, "ab", 10, SearchCriteria.ANY).get(0).name);
    }

    private static int flags(boolean tradeable, boolean equipable, int slot) {
        return ItemTraits.pack(false, tradeable, equipable, slot);
    }

    private static SearchItem item(int id, String name, boolean members, int traits) {
        int packed = members ? traits | ItemTraits.MEMBERS : traits & ~ItemTraits.MEMBERS;
        return new SearchItem(id, name, members, 0, packed);
    }
}

package com.osr.jei.ui;

import com.osr.jei.crafting.BuildExpander;
