import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ShopAndPageParseTest {

    private static final String SHOPS = ""
        + "<div class=\"mw-heading mw-heading3\"><h3 id=\"Shop_locations\">Shop locations</h3></div>"
        + "<table class=\"wikitable store-locations-list\"><tr>"
        + "<th>Seller</th><th>Location</th>"
        + "<th>Number<br />in stock</th><th>Restock<br />time</th>"
        + "<th>Price<br />sold at</th><th>Price<br />bought at</th>"
        + "</tr>"
        + "<tr><td><a href=\"/w/Shantay_Pass_Shop\">Shantay Pass Shop.</a></td><td>Desert</td>"
        + "<td data-sort-value=\"0\">0</td><td data-sort-value=\"60\">1m</td>"
        + "<td data-sort-value=\"2\">2</td><td>1</td></tr>"
        + "<tr><td>Fishing Guild Shop</td><td>Guild</td>"
        + "<td data-sort-value=\"10\">10</td><td>26m</td>"
        + "<td data-sort-value=\"70\">70</td><td>20</td></tr>"
        + "<tr><td>Theatre of Blood Supplies</td><td>ToB</td>"
        + "<td data-sort-value=\"10e50\"><span>\u221e</span></td><td>N/A</td>"
        + "<td data-sort-value=\"1\">1</td><td>1</td></tr>"
        + "<tr><td>TzHaar shop</td><td>Mor Ul Rek</td>"
        + "<td data-sort-value=\"5\">5</td><td>1m</td>"
        + "<td data-sort-value=\"67\">67 Tokkul</td><td>20</td></tr>"
        + "</table>";

    private static final String PAGE = ""
        + "<h2 id=\"Products\">Products</h2>"
        + "<table class=\"wikitable\"><tr><td><a href=\"/w/Iron_platebody\">Iron platebody</a></td></tr></table>"
        + "<div class=\"mw-heading mw-heading2\"><h2 id=\"Item_sources\">Item sources</h2></div>"
        + "<table class=\"item-drops\"><tr><td>Goblin</td><td>2</td><td>1</td><td>1/128</td></tr></table>"
        + SHOPS
        + "<h2 id=\"Changes\">Changes</h2><p>later</p>";

    private static final String WIKI = ""
        + "{{Infobox Item\n|name = Bucket\n|weight = 1.5\n}}\n"
        + "{{Recipe\n|skill1 = Smithing\n|skill1lvl = 33\n|skill1exp = 37.5\n"
        + "|facilities = Anvil\n|mat1 = Iron bar\n|mat1quantity = 5\n}}\n"
        + "{{Recipe\n|skill1 = Cooking\n|skill1lvl = 1\n|skill1exp = 0\n"
        + "|mat1 = Bucket of water\n|mat1quantity = 1\n}}\n"
        + "{{Infobox Bonuses\n|astab = 0\n|dstab = 3\n|slot = body\n|aspeed = 4\n}}\n";

    @Test
    public void stockColumnIsNotRestockAndZeroStaysZero() {
        List<ShopEntry> shops = ShopTableParser.parse(SHOPS);
        assertEquals(4, shops.size());

        ShopEntry shantay = shops.get(0);
        assertEquals("Shantay Pass Shop", shantay.shopName);
        assertEquals(0, shantay.stock);
        assertTrue(shantay.permanentlyOutOfStock());
        assertEquals(2, shantay.price);
        assertEquals("gp", shantay.currency);
        assertTrue(shantay.sells);

        ShopEntry guild = shops.get(1);
        assertEquals(10, guild.stock);
        assertFalse(guild.permanentlyOutOfStock());
        assertEquals(70, guild.price);

        ShopEntry tob = shops.get(2);
        assertEquals(ShopEntry.INFINITE, tob.stock);
        assertTrue(tob.infiniteStock());

        ShopEntry tzhaar = shops.get(3);
        assertEquals("Tokkul", tzhaar.currency);
        assertFalse(tzhaar.isCoins());
        assertEquals(67, tzhaar.price);
        assertEquals(5, tzhaar.stock);
    }

    @Test
    public void onePageFeedsRecipesDropsAndShops() {
        ItemDetails details = ItemDetails.from(new PageContent(WIKI, PAGE, false));
        assertEquals(2, details.recipes.size());
        RecipeInfo smithing = details.recipes.get(0);
        assertEquals("Smithing", smithing.skill);
        assertEquals(33, smithing.level);
        assertEquals(1, smithing.ingredients.size());
        assertEquals("Iron bar", smithing.ingredients.get(0).name);
        assertEquals(5, smithing.ingredients.get(0).quantity);
        assertEquals("Cooking", details.recipes.get(1).skill);

        assertEquals(1, details.drops.size());
        DropEntry drop = details.drops.get(0);
        assertEquals("Goblin", drop.getSource());
        assertEquals("2", drop.getLevel());
        assertEquals("1", drop.getQuantity());
        assertEquals("1/128", drop.getRate());

        assertEquals(4, details.shops.size());
        assertTrue(details.stats.isPresent());
        EquipmentStats stats = details.stats.get();
        assertEquals("body", stats.slot);
        assertEquals(3, stats.defStab);
        assertEquals(4, stats.speed);
        assertEquals(1.5, details.weight, 0.001);
        assertEquals(1, details.products.size());
        assertEquals("Iron platebody", details.products.get(0));
    }

    @Test
    public void sectionSliceStopsAtTheNextHeading() {
        String products = HtmlSections.sliceById(PAGE, "Products");
        assertTrue(products.contains("Iron platebody"));
        assertFalse(products.contains("Goblin"));
        String sources = HtmlSections.sliceById(PAGE, "Item_sources");
        assertTrue(sources.contains("Goblin"));
        assertTrue(sources.contains("Shantay Pass Shop"));
        assertFalse(sources.contains("later"));
    }
}

package com.osr.jei.wiki;

import com.osr.jei.model.ShopEntry;
import com.osr.jei.service.ItemDetails;
import org.junit.Test;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Live wiki {@code store-locations-list} tables. Air battlestaff's own page does
 * not include this table (and the storeline bucket has no row for it), so an
 * empty shop list there is the page, not a missed column. Staff of air, bread,
 * bronze axe, and air rune do include it, including version notes in the seller cell.
 */
public class StoreLocationsListTest {

    @Test
    public void staffOfAirIncludesZaffAndVersionNotes() throws Exception {
        List<ShopEntry> shops = ShopTableParser.parse(fixture("wiki/staff-of-air-shops.html"));
        ShopEntry zaff = named(shops, "Zaff's Superior Staffs!");
        assertEquals(1500, zaff.price);
        assertEquals(2, zaff.stock);
        assertEquals("gp", zaff.currency);
        assertTrue(zaff.sells);
        assertTrue(names(shops).contains("Magic Guild Store (Runes and Staves)"));
        assertTrue(names(shops).contains("Baba Yaga's Magic Shop (post-quest)"));
        assertTrue(names(shops).contains("Baba Yaga's Magic Shop"));
    }

    @Test
    public void breadBronzeAxeAndAirRuneUseTheSameTable() throws Exception {
        List<ShopEntry> bread = ShopTableParser.parse(fixture("wiki/bread-shops.html"));
        ShopEntry stall = named(bread, "Ardougne Baker's Stall (east)");
        assertEquals(12, stall.price);
        assertEquals(10, stall.stock);

        List<ShopEntry> axes = ShopTableParser.parse(fixture("wiki/bronze-axe-shops.html"));
        ShopEntry bob = named(axes, "Bob's Brilliant Axes");
        assertEquals(16, bob.price);
        assertEquals(10, bob.stock);
        assertTrue(names(axes).contains("Obli's General Store (Karamja gloves)"));

        List<ShopEntry> runes = ShopTableParser.parse(fixture("wiki/air-rune-shops.html"));
        ShopEntry aubury = named(runes, "Aubury's Rune Shop");
        assertEquals(4, aubury.price);
        assertEquals(5000, aubury.stock);
        assertTrue(names(runes).contains("Baba Yaga's Magic Shop (post-quest)"));
    }

    @Test
    public void tableIsFoundWithoutTheExpectedHeading() throws Exception {
        String table = fixture("wiki/staff-of-air-shops.html");
        String page = "<h2 id=\"Trivia\">Trivia</h2><p>No shop heading.</p>" + table;
        ItemDetails details = ItemDetails.from(new PageContent("", page, false));
        assertTrue(names(details.shops).contains("Zaff's Superior Staffs!"));
    }

    @Test
    public void pageWithoutAStoreTableHasNoShops() {
        ItemDetails details = ItemDetails.from(new PageContent("", "<p>Air battlestaff</p>", false));
        assertTrue(details.shops.isEmpty());
    }

    private static ShopEntry named(List<ShopEntry> shops, String name) {
        for (ShopEntry shop : shops) {
            if (name.equals(shop.shopName)) {
                return shop;
            }
        }
        throw new AssertionError(name + " missing from " + names(shops));
    }

    private static String names(List<ShopEntry> shops) {
        StringBuilder text = new StringBuilder();
        for (ShopEntry shop : shops) {
            if (text.length() > 0) {
                text.append(", ");
            }
            text.append(shop.shopName);
        }
        return text.toString();
    }

    private static String fixture(String path) throws Exception {
        InputStream in = StoreLocationsListTest.class.getClassLoader().getResourceAsStream(path);
        if (in == null) {
            throw new AssertionError("Missing fixture " + path);
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buffer = new byte[4096];
        int read;
        while ((read = in.read(buffer)) >= 0) {
            out.write(buffer, 0, read);
        }
        in.close();
        return new String(out.toByteArray(), StandardCharsets.UTF_8);
    }
}

package com.osr.jei.wiki;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import okhttp3.OkHttpClient;
import org.junit.Test;

import java.io.IOException;
import java.io.InterruptedIOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class WikiLoadTest {

    @Test
    public void cachedPageIsNotFetchedTwice() {
        FakeHttp http = new FakeHttp();
        try {
            WikiPages pages = new WikiPages(http, () -> 1_000L);
            PageContent first = pages.load("Rune platebody").join();
            PageContent second = pages.load("rune platebody").join();
            assertEquals(1, http.calls.get());
            assertEquals("Rune platebody", first.wikitext);
            assertEquals(first.wikitext, second.wikitext);
            assertFalse(second.missing);
            assertTrue(pages.load("Missing page").join().missing);
            assertTrue(pages.load("Missing page").join().missing);
            assertEquals(2, http.calls.get());
        } finally {
            http.shutdown();
        }
    }

    @Test
    public void concurrentRequestsForTheSamePageShareOneCall() throws Exception {
        FakeHttp http = new FakeHttp();
        try {
            WikiPages pages = new WikiPages(http, () -> 1_000L);
            CompletableFuture<PageContent> first = pages.load("Abyssal whip");
            assertTrue(http.entered.await(2, TimeUnit.SECONDS));
            CompletableFuture<PageContent> second = pages.load("Abyssal whip");
            assertEquals(1, http.calls.get());
            assertSame(first, second);
            http.blocked.complete(page("Abyssal whip"));
            assertEquals("Abyssal whip", first.join().wikitext);
            assertEquals("Abyssal whip", second.join().wikitext);
            assertEquals(1, http.calls.get());
            assertTrue(pages.size() <= WikiPages.CACHE_SIZE);
        } finally {
            http.shutdown();
        }
    }

    @Test
    public void pageCacheIsBoundedAndExpires() {
        FakeHttp http = new FakeHttp();
        try {
            long[] now = {5_000L};
            WikiPages pages = new WikiPages(http, () -> now[0]);
            for (int i = 0; i < WikiPages.CACHE_SIZE + 3; i++) {
                pages.load("Item " + i).join();
            }
            assertEquals(WikiPages.CACHE_SIZE + 3, http.calls.get());
            assertEquals(WikiPages.CACHE_SIZE, pages.size());
            pages.load("Item " + (WikiPages.CACHE_SIZE + 2)).join();
            assertEquals(WikiPages.CACHE_SIZE + 3, http.calls.get());
            pages.load("Item 0").join();
            assertEquals(WikiPages.CACHE_SIZE + 4, http.calls.get());

            int beforeExpiry = http.calls.get();
            pages.load("Item " + (WikiPages.CACHE_SIZE + 2)).join();
            assertEquals(beforeExpiry, http.calls.get());
            now[0] += WikiPages.TTL_MS;
            pages.load("Item " + (WikiPages.CACHE_SIZE + 2)).join();
            assertEquals(beforeExpiry + 1, http.calls.get());
        } finally {
            http.shutdown();
        }
    }

    @Test
    public void monsterReadSkipsRenderedHtmlAndDoesNotBlockAFullPage() {
        FakeHttp http = new FakeHttp();
        try {
            WikiPages pages = new WikiPages(http, () -> 1_000L);
            PageContent lite = pages.loadWikitext("Zamorak crafter").join();
            assertTrue(http.lastUrl.contains("prop=wikitext&"));
            assertFalse(http.lastUrl.contains("prop=wikitext|text"));
            assertFalse(lite.missing);
            assertEquals(1, http.calls.get());
            pages.loadWikitext("zamorak crafter").join();
            assertEquals(1, http.calls.get());
            pages.load("Zamorak crafter").join();
            assertEquals(2, http.calls.get());
            assertTrue(http.lastUrl.contains("prop=wikitext|text"));
            pages.loadWikitext("Zamorak crafter").join();
            assertEquals(2, http.calls.get());
        } finally {
            http.shutdown();
        }
    }

    @Test
    public void failureBackoffDoesNotCallAgainUntilRetry() {
        FakeHttp http = new FakeHttp();
        try {
            long[] now = {20_000L};
            WikiPages pages = new WikiPages(http, () -> now[0]);
            http.failure = new IOException("HTTP 503");
            assertFailed(pages.load("Coal"));
            assertEquals(1, http.calls.get());
            now[0] += 1_000L;
            assertFailed(pages.load("Coal"));
            assertEquals(1, http.calls.get());

            http.failure = new RequestCancelledException();
            pages.allowRetry("Coal");
            assertFailed(pages.load("Coal"));
            assertEquals(2, http.calls.get());
            http.failure = null;
            assertFalse(pages.load("Coal").join().missing);
            assertEquals(3, http.calls.get());
        } finally {
            http.shutdown();
        }
    }

    @Test
    public void httpClientKeepsTheInjectedDispatcherAndSetsTimeouts() {
        OkHttpClient base = new OkHttpClient();
        WikiHttp http = new WikiHttp(base, new Gson());
        try {
            assertSame(base.dispatcher(), http.httpClient().dispatcher());
            assertSame(base.connectionPool(), http.httpClient().connectionPool());
            assertEquals(WikiHttp.CONNECT_TIMEOUT_SECONDS * 1000, http.httpClient().connectTimeoutMillis());
            assertEquals(WikiHttp.READ_TIMEOUT_SECONDS * 1000, http.httpClient().readTimeoutMillis());
            assertEquals(WikiHttp.CALL_TIMEOUT_SECONDS * 1000, http.httpClient().callTimeoutMillis());
            assertTrue(WikiHttp.USER_AGENT.contains("OSRS-Item-Browser"));
            assertTrue(WikiHttp.USER_AGENT.contains("RuneLite"));
            assertTrue(WikiHttp.USER_AGENT.contains("github.com/Vivialdi/osrs-item-browser"));
        } finally {
            http.shutdown();
        }
    }

    @Test
    public void failureCopyNamesTimeoutsBusyPagesAndBackoff() {
        assertTrue(WikiFailures.page(new InterruptedIOException("timeout")).contains("timed out"));
        assertTrue(WikiFailures.page(new IOException("HTTP 503")).contains("HTTP 503"));
        assertTrue(WikiFailures.page(new IOException("wiki maxlag")).contains("busy"));
        assertTrue(WikiFailures.page(new IOException("connection reset")).contains("could not be reached"));
        assertTrue(WikiFailures.page(new WikiBackoffException()).contains("Retry"));
        assertTrue(WikiFailures.monster(new IOException("down")).contains("monster"));
        assertTrue(com.osr.jei.service.ItemDetails.from(PageContent.MISSING).missing);
        assertFalse(com.osr.jei.service.ItemDetails.EMPTY.missing);
    }

    private static void assertFailed(CompletableFuture<PageContent> future) {
        try {
            future.join();
            fail("expected the wiki load to fail");
        } catch (CompletionException expected) {
            assertTrue(expected.getCause() != null);
        }
    }

    private static JsonObject page(String marker) {
        JsonObject star = new JsonObject();
        star.addProperty("*", marker);
        JsonObject parse = new JsonObject();
        parse.add("wikitext", star);
        parse.add("text", star);
        JsonObject root = new JsonObject();
        root.add("parse", parse);
        return root;
    }

    private static final class FakeHttp extends WikiHttp {
        private final AtomicInteger calls = new AtomicInteger();
        private volatile String lastUrl = "";
        private final CountDownLatch entered = new CountDownLatch(1);
        private final CompletableFuture<JsonObject> blocked = new CompletableFuture<>();
        private volatile Throwable failure;
        private int loads;

        private FakeHttp() {
            super(new OkHttpClient(), new Gson());
        }

        @Override
        public CompletableFuture<JsonObject> getWiki(String url) {
            lastUrl = url;
            int n = calls.incrementAndGet();
            entered.countDown();
            if (blocked != null && loads == 0 && failure == null && url.contains("Abyssal_whip")) {
                loads++;
                return blocked;
            }
            if (failure != null) {
                CompletableFuture<JsonObject> failed = new CompletableFuture<>();
                failed.completeExceptionally(failure);
                return failed;
            }
            if (url.toLowerCase().contains("missing")) {
                return CompletableFuture.completedFuture(new JsonObject());
            }
            String marker = "page-" + n;
            int item = url.lastIndexOf("Item");
            if (item >= 0) {
                marker = url.substring(item).replace('_', ' ');
            } else if (url.toLowerCase().contains("rune")) {
                marker = "Rune platebody";
            }
            return CompletableFuture.completedFuture(page(marker));
        }
    }
}
